const leagueIdx=t=>{let i=0;LEAGUES.forEach((l,k)=>{if(t>=l.min)i=k});return i};
const league=t=>LEAGUES[leagueIdx(t)];
const lvl=()=>Math.floor(Math.sqrt(S.xp/100))+1;
const streakNow=()=>(S.playDay===today()||S.playDay===yday())?S.streak:0;
function ensureDaily(){if(!S.daily||S.daily.d!==today())S.daily={d:today(),c:0,done:false}}
function markPlayed(){const t=today();if(S.playDay===t)return;S.streak=S.playDay===yday()?S.streak+1:1;S.playDay=t;if(S.streak>1&&S.streak%7===0){S.inv.premium++;setTimeout(()=>toast(`🔥 ¡Racha de ${S.streak} días! Sobre Premium de regalo`),500)}else if(S.streak===3){S.inv.normal++;setTimeout(()=>toast('🔥 ¡3 días seguidos! Sobre de regalo'),500)}save()}

/* ====== PREGUNTAS: normalizar e importar ====== */
function normAsig(a){a=String(a||'').trim();const up=a.toUpperCase().replace(/\s+/g,'');if(ASIG[up])return up;const l=a.toLowerCase();
 if(/redes.*\b(2|dos|ii)\b|rst ?2/.test(l))return 'RST2';if(/redes|rst/.test(l))return 'RST1';if(/se[ñn]al|sys/.test(l))return 'SYS';
 if(/(electr|ed).*\b(2|dos|ii)\b|ed2/.test(l))return 'ED2';if(/electr|ed ?1/.test(l))return 'ED1';if(/mat/.test(l))return 'MAT3';if(/prog/.test(l))return 'PROG2';return null}
function temaKey(t){const m=String(t).match(/^\s*(?:tema\s*)?T?\s*(\d+)/i);return m?'T'+m[1]:String(t).trim().toLowerCase()}
function normQ(o){
 if(!o||typeof o!=='object')throw 'no es una pregunta';
 const asig=normAsig(o.asig||o.asignatura);if(!asig)throw 'asignatura desconocida ('+(o.asig||'vacía')+')';
 const tema=String(o.tema||'').trim();if(!tema)throw 'falta el tema';
 const q=String(o.q||o.pregunta||o.enunciado||'').trim();if(!q)throw 'falta el enunciado';
 let ops=o.ops||o.opciones;if(!Array.isArray(ops)||ops.length<2)throw 'necesita al menos 2 opciones';ops=ops.map(x=>String(x));
 let ok=o.ok??o.correcta;if(typeof ok==='string'&&!/^\d+$/.test(ok))ok=ops.indexOf(ok);ok=parseInt(ok);if(!(ok>=0&&ok<ops.length))throw 'el campo "ok" no apunta a ninguna opción';
 const dif=Math.min(4,Math.max(1,parseInt(o.dif??o.dificultad)||2));
 let tabla=o.tabla||null;if(tabla&&typeof tabla==='object'&&Array.isArray(tabla.filas))tabla={titulo:String(tabla.titulo||'Datos'),cols:(tabla.cols||[]).map(String),filas:tabla.filas.map(r=>(Array.isArray(r)?r:[r]).map(String))};else tabla=null;
 return {id:hash(asig+'|'+tema+'|'+q),asig,tema,tk:temaKey(tema),dif,q,ops,ok,sol:String(o.sol||o.solucion||''),trap:String(o.trap||''),calc:!!(o.calc??o.calculadora),tabla};
}
function fixBS(t){return t.replace(/(^|[^\\])\\(?=[a-zA-Z]{2,}|[{}()\[\],;!:%| ])/g,'$1\\\\').replace(/(^|[^\\])\\(?=[a-zA-Z]{2,}|[{}()\[\],;!:%| ])/g,'$1\\\\')}
function topArrays(t){const out=[];let depth=0,inS=false,escp=false,start=-1;for(let i=0;i<t.length;i++){const ch=t[i];if(inS){if(escp)escp=false;else if(ch==='\\')escp=true;else if(ch==='"')inS=false;continue}
 if(ch==='"'&&depth>0){inS=true;continue}if(ch==='['){if(depth===0)start=i;depth++}else if(ch===']'&&depth>0){depth--;if(depth===0)out.push(t.slice(start,i+1))}}return out}
function parseImport(txt){
 const t=fixBS(txt.replace(/```(?:json)?/gi,''));const blocks=topArrays(t);if(!blocks.length)throw 'No encuentro ningún bloque [ ... ] de preguntas.';
 let all=[];for(const b of blocks){try{const v=JSON.parse(b);if(Array.isArray(v))all=all.concat(v)}catch(e){}}
 if(!all.length)throw 'El JSON no es válido. Pídele a Gemini que lo repita SOLO como bloque de código JSON.';return all}
function temasOf(a){const m=new Map();S.qs.forEach(q=>{if(q.asig===a&&!m.has(q.tk))m.set(q.tk,q.tema)});return [...m].map(([tk,name])=>({tk,name})).sort((x,y)=>x.tk.localeCompare(y.tk,undefined,{numeric:true}))}
function failPool(){return S.qs.filter(q=>{const s=S.st[q.id];return s&&s.w>0&&(s.l===0||s.w>=s.c)})}
function pickQs(pred,n,difs){const base=S.qs.filter(pred);const qc=S.qc||0,ls=S.ls||{};const w=q=>{const s=S.st[q.id]||{c:0,w:0};const rec=qc-(ls[q.id]??-1e9);return s.c-2*s.w+Math.random()*2+(rec<60?8-rec/10:0)};
 const prim=base.filter(q=>difs.includes(q.dif)).map(q=>[w(q),q]).sort((a,b)=>a[0]-b[0]).map(x=>x[1]);
 const dist=d=>Math.min(...difs.map(x=>Math.abs(x-d)));
 const sec=shuffle(base.filter(q=>!difs.includes(q.dif))).sort((a,b)=>dist(a.dif)-dist(b.dif));
 let res=prim.concat(sec).slice(0,n);const gc=genCands(pred,difs.length?difs:[1,2,3,4]);if(gc.length){const fresh=base.filter(q=>difs.includes(q.dif)&&(qc-(ls[q.id]??-1e9))>=60).length;const gp=fresh>=n*2?.25:.5;res=res.map(q=>Math.random()<gp?(makeGen(pk(gc))||q):q);while(res.length<n){const g=makeGen(pk(gc));if(!g)break;res.push(g)}}
 return shuffle(res)}

/* ====== CARTAS CREADAS ====== */
const RAR_AL={b:'B',bronce:'B',bronze:'B',p:'P',plata:'P',silver:'P',o:'O',oro:'O',gold:'O',i:'I',icon:'I',icono:'I',leyenda:'I'};
const SR={B:[42,62],P:[55,75],O:[70,88],I:[88,99]};
const AB_AL={fifty:'fifty','50/50':'fifty',eliminar:'fifty',freeze:'freeze',congelar:'freeze',double:'double',x2:'double',doble:'double',shield:'shield',escudo:'shield',skip:'skip',cambiar:'skip',boost:'boost',recarga:'boost',coins:'coins',monedas:'coins'};
const isCardObj=o=>o&&typeof o==='object'&&(o.tipo==='carta'||o.type==='card'||(('nombre' in o||'rareza' in o)&&!('q' in o)&&!('ops' in o)));
function normCard(o){const n=String(o.nombre||o.name||o.n||'').trim().slice(0,40);if(!n)throw 'carta sin nombre';
 const ar=String(o.asig||o.asignatura||'ALL').trim();const a=/^(all|todas)$/i.test(ar)?'ALL':normAsig(ar);if(!a)throw `asignatura desconocida en la carta "${n}"`;
 const r=RAR_AL[String(o.rareza||o.r||'B').trim().toLowerCase()];if(!r)throw `rareza desconocida en la carta "${n}"`;
 const [lo,hi]=SR[r],seed=parseInt(hash(a+n),36),given=Array.isArray(o.stats)?o.stats.map(x=>parseInt(x)):[];
 const s=[0,1,2,3].map(i=>Number.isFinite(given[i])?Math.min(hi,Math.max(lo,given[i])):lo+Math.floor(seed/(7**i))%(hi-lo+1));
 const ab=r==='I'?(AB_AL[String(o.habilidad||o.ab||'').trim().toLowerCase()]||Object.keys(AB)[seed%6]):null;
 const e=Array.from(String(o.emoji||o.e||'').trim()).slice(0,3).join('')||'🃏';
 return {id:'c_'+hash(a+'|'+n.toLowerCase()),a,r,n,e,s,b:String(o.texto||o.descripcion||o.b||'').slice(0,400),ab,custom:true}}
function addCard(c){S.custom=S.custom||[];const k=S.custom.findIndex(x=>x.id===c.id);if(k>=0)S.custom[k]=c;else S.custom.push(c);refreshCards();return k<0}
function delCard(btn,id){if(!btn.dataset.c){btn.dataset.c=1;btn.textContent='¿Seguro?';return}S.custom=(S.custom||[]).filter(c=>c.id!==id);delete S.cards[id];S.deck=S.deck.filter(x=>x!==id);refreshCards();save();const m=$('#mng');if(m)m.outerHTML=manageHTML();toast('Carta borrada')}
function cardForm(){const asOpts=[['ALL','🌍 Todas'],...ASIGS.map(a=>[a.id,a.icon+' '+a.name])];
 modal(`<h3>✏️ Crear carta</h3><div class="mut">La carta entra en los sobres: tendrás que conseguirla abriéndolos. Sus estadísticas se ponen solas según la rareza.</div>
 <label class="mut" for="cf-n" style="display:block;margin-top:10px">Nombre</label><input id="cf-n" maxlength="40" placeholder="Fibra multimodo">
 <div class="row"><div><label class="mut" for="cf-e">Emoji</label><input id="cf-e" value="🃏"></div><div><label class="mut" for="cf-r">Rareza</label><select id="cf-r"><option value="B">Bronce</option><option value="P" selected>Plata</option><option value="O">Oro</option><option value="I">ICON</option></select></div></div>
 <label class="mut" for="cf-a">Asignatura</label><select id="cf-a">${asOpts.map(([v,l])=>`<option value="${v}">${esc(l)}</option>`).join('')}</select>
 <label class="mut" for="cf-b">Texto de la carta (concepto y fórmula; las fórmulas entre $...$)</label><textarea id="cf-b" rows="3" style="font-family:Inter,sans-serif;font-size:15px" placeholder="Varios modos de propagación: más dispersión que la monomodo."></textarea>
 <div id="cf-abw" class="hidden"><label class="mut" for="cf-ab">Habilidad ICON</label><select id="cf-ab">${Object.entries(AB).map(([k,v])=>`<option value="${k}">${v.s}: ${esc(v.d)}</option>`).join('')}</select></div>
 <button class="btn" id="cf-ok" style="margin-top:6px">Crear carta</button>`);
 const rs=$('#cf-r');rs.onchange=()=>$('#cf-abw').classList.toggle('hidden',rs.value!=='I');
 $('#cf-ok').onclick=()=>{try{const c=normCard({nombre:$('#cf-n').value,emoji:$('#cf-e').value,rareza:rs.value,asig:$('#cf-a').value,texto:$('#cf-b').value,habilidad:$('#cf-ab').value});if(CARD[c.id]&&!c.custom){toast('Ya existe esa carta');return}const isNew=addCard(c);save();closeModal();sfx('gold');toast(isNew?`✏️ "${c.n}" creada: ya puede salir en los sobres`:`"${c.n}" actualizada`);render()}catch(e){toast(String(e))}}}

/* ====== CARTAS Y MAZO ====== */
let stat=(c,i)=>{const o=S.cards[c.id]||{};return Math.min((SR[c.r]||[0,99])[1],c.s[i]+2*((o.l||1)-1)+(o.sh?3:0)+(o.aw?5:0))};
const maxL=o=>o&&o.aw?10:5,xpNeed=l=>40*l;
const AWC={B:2,P:2,O:2,I:1};
const weekAsig=()=>ASIGS[Math.floor((Date.now()/86400000+3)/7)%ASIGS.length].id;
function gainCardXP(q){if(!M)return;const wk=(q.asig===weekAsig()?2:1)*(M.mode==='run'&&hasR('chip')?2:1);S.deck.forEach(id=>{const c=CARD[id],o=S.cards[id];if(!c||!o)return;const amt=(c.a===q.asig||c.a==='ALL'?12:4)*wk;const mx=maxL(o);if(o.l>=mx){o.xp=Math.min(xpNeed(o.l),(o.xp||0)+amt);return}o.xp=(o.xp||0)+amt;while(o.l<mx&&o.xp>=xpNeed(o.l)){o.xp-=xpNeed(o.l);o.l++;(M.cardUps=M.cardUps||[]).push(`${c.e} ${c.n} → Nv ${o.l}`);floatTxt(`⬆️ ${c.e} Nv ${o.l}`,'#86efac',500)}})}
function hasMastIn(a){return Object.entries(S.mast).some(([k,v])=>v>=1&&(a==='ALL'||k.startsWith(a+'|')))}
function awaken(id){const c=CARD[id],o=S.cards[id];if(!c||!o||o.aw)return;const cost=200*RM[c.r];if(o.l<5||o.n-1<AWC[c.r]||!hasMastIn(c.a)||S.coins<cost){toast('Aún no cumples los requisitos');return}o.n-=AWC[c.r];S.coins-=cost;o.aw=1;save();closeModal();celebrate('⭐',`¡${esc(c.n)} ha despertado!`,'+5 a todas sus estadísticas y nivel máximo 10. Sigue subiéndola respondiendo preguntas de su asignatura.');render()}
function ownedCards(){return CARDS.filter(c=>S.cards[c.id]).sort((a,b)=>RORD[b.r]-RORD[a.r])}
const SYN_A={RST1:'Enlace dedicado',RST2:'Enrutamiento propio',ED1:'Reloj síncrono',ED2:'Bus de datos',SYS:'Señal en fase',MAT3:'Base ortonormal',PROG2:'Compilación limpia'};
function synergies(cs){const out=[],byA={},byR={};cs.forEach(c=>{if(c.a!=='ALL')byA[c.a]=(byA[c.a]||0)+1;byR[c.r]=(byR[c.r]||0)+1});
 Object.entries(byA).forEach(([a,n])=>{if(n>=3)out.push({n:SYN_A[a]+' total',d:`3 cartas de ${ASIG[a].name}: +4 s y +15 % 🪙`,tb:4,cm:.15});else if(n>=2)out.push({n:SYN_A[a],d:`2 cartas de ${ASIG[a].name}: +2 s`,tb:2})});
 if(cs.length===3&&new Set(cs.map(c=>c.a)).size===3)out.push({n:'Red troncal',d:'3 asignaturas distintas: +15 % XP',xm:.15});
 if((byR.I||0)>=2)out.push({n:'Salón de la fama',d:'2 o más ICON: +20 % 🪙',cm:.2});
 if(cs.length===3&&Object.keys(byR).length===1&&!byR.I)out.push({n:'Multiplexación perfecta',d:'3 cartas de la misma rareza: +1 🛡️',sh:1});
 if(cs.length===3&&Object.keys(byR).length===3)out.push({n:'Jerarquía digital',d:'3 rarezas distintas: +3 s',tb:3});
 return out}
const PERKS=[{g:'SYS',m:'blitz',n:'〰️ Filtro activo',d:'Contrarreloj: +1 s extra por acierto por carta (máx. 2)'},{g:'MAT3',m:'calc',n:'∑ Precisión',d:'Preguntas con calculadora: +20 % de tiempo por carta (máx. 3)'},{g:'RED',m:'quick',n:'📡 Interferencia',d:'Duelo: el rival acierta un 3 % menos por carta (máx. 3)'},{g:'ED',m:'surv',n:'⏱️ Reloj de respaldo',d:'Supervivencia: +1 vida por carta (máx. 2)'},{g:'PROG2',m:'level',n:'💻 Depurador',d:'Mundos y jefes: +1 escudo por carta (máx. 2)'}];
const grpOf=a=>a==='RST1'||a==='RST2'?'RED':a==='ED1'||a==='ED2'?'ED':a;
const MODE_N={blitz:'Contrarreloj',calc:'todos los modos',quick:'Duelo',surv:'Supervivencia',level:'Mundos'};
function deckBonus(asig,deck=S.deck,mode){const cs=deck.map(id=>CARD[id]).filter(Boolean);let tb=0,v=0,b=0,r=0,m=0;
 cs.forEach(c=>{tb+=Math.max(0,stat(c,0)-50);v+=Math.max(0,stat(c,1)-50);b+=Math.max(0,stat(c,2)-50);r+=Math.max(0,stat(c,3)-50);if(asig&&asig!=='ALL'&&(c.a===asig||c.a==='ALL'))m++});
 const syn=synergies(cs),d={tb:Math.round(tb/10),cm:1+v/200+0.1*m,xm:1+b/200,sh:Math.floor(r/40),icons:cs.filter(c=>c.r==='I'),syn};
 syn.forEach(x=>{d.tb+=x.tb||0;d.cm+=x.cm||0;d.xm+=x.xm||0;d.sh+=x.sh||0});
 const g={};cs.forEach(c=>{const k=grpOf(c.a);g[k]=(g[k]||0)+1});d.g=g;
 const mm=mode==='boss'?'level':mode;d.perks=PERKS.filter(x=>g[x.g]).map(x=>({...x,k:g[x.g],on:!mode||x.m==='calc'||x.m===mm}));return d}
const bonusText=d=>`⏱️ +${d.tb} s · 🪙 x${d.cm.toFixed(2)} · ⭐ x${d.xm.toFixed(2)} · 🛡️ ${d.sh} escudo${d.sh===1?'':'s'}${d.syn.length?d.syn.map(x=>`<div class="syn">⚡ <b>${x.n}</b> · ${x.d}</div>`).join(''):'<div class="syn off">Sinergias: junta 2 cartas de una asignatura, 3 asignaturas distintas, 3 rarezas iguales o distintas, o 2 ICON.</div>'}${(d.perks||[]).map(x=>`<div class="perk ${x.on?'':'off'}">🎮 <b>${x.n}</b> x${x.k} · ${x.d}${x.on?'':' (no se aplica en este modo)'}</div>`).join('')}`;
const EMBK={RST1:'queue',RST2:'graph',SYS:'wave',MAT3:'matrix',ED1:'gate',ED2:'gate',PROG2:'code',ALL:'bolt'};
const EMB={wave:'<path d="M0 50 Q12.5 10 25 50 T50 50 T75 50 T100 50"/><path d="M0 50 Q12.5 80 25 50 T50 50 T75 50 T100 50" opacity=".5"/>',
 graph:'<path d="M20 30 L50 15 L80 35 L70 78 L35 70 Z M50 15 L35 70 M20 30 L70 78"/><circle cx="20" cy="30" r="6"/><circle cx="50" cy="15" r="6"/><circle cx="80" cy="35" r="6"/><circle cx="35" cy="70" r="6"/><circle cx="70" cy="78" r="6"/>',
 gate:'<path d="M28 25 H52 A25 25 0 0 1 52 75 H28 Z M10 38 H28 M10 62 H28 M77 50 H95"/>',
 queue:'<rect x="6" y="38" width="12" height="24"/><rect x="22" y="38" width="12" height="24"/><rect x="38" y="38" width="12" height="24"/><path d="M54 50 H66"/><circle cx="80" cy="50" r="13"/>',
 matrix:'<path d="M22 14 H12 V86 H22 M78 14 H88 V86 H78"/><circle cx="32" cy="32" r="4"/><circle cx="50" cy="32" r="4"/><circle cx="68" cy="32" r="4"/><circle cx="32" cy="50" r="4"/><circle cx="50" cy="50" r="4"/><circle cx="68" cy="50" r="4"/><circle cx="32" cy="68" r="4"/><circle cx="50" cy="68" r="4"/><circle cx="68" cy="68" r="4"/>',
 code:'<path d="M35 25 L14 50 L35 75 M65 25 L86 50 L65 75 M56 18 L44 82"/>',bolt:'<path d="M56 8 L24 56 H48 L40 92 L76 40 H52 Z"/>'};
const embSVG=c=>`<svg class="emb" viewBox="0 0 100 100" fill="none" stroke="currentColor" stroke-width="3.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${EMB[EMBK[c.a]||'bolt']}</svg>`;
function cardHTML(c,o={}){if(o.locked){const A=c.a==='ALL'?null:ASIG[c.a];return `<div class="gcard locked"><div class="rt">${RN[c.r]}</div><div class="em">❔</div><div class="nm">???</div><div class="as">${A?A.icon:'🌍'}</div></div>`}
 const own=S.cards[c.id],A=c.a==='ALL'?null:ASIG[c.a],lv=own?own.l:1;
 return `<div class="gcard r-${c.r}${own&&own.sh?' shiny':''}${own&&own.aw?' awk':''}">${own&&own.aw?'<i class="awm">⭐</i>':''}${own&&own.sh?'<i class="shm">✨</i>':''}${c.r==='I'?embSVG(c):''}<div class="rt">${RN[c.r]}</div>${lv>1?`<div class="lv">Nv${lv}</div>`:''}${c.custom?'<div class="cu">✏️</div>':''}<div class="ovr"><b>${Math.round(c.s.reduce((a,_,i)=>a+stat(c,i),0)/4)}</b></div><div class="em"><span>${esc(c.e)}</span></div><div class="nm">${esc(c.n)}</div><div class="as">${A?A.icon+' '+esc(A.name):'🌍 Todas'}</div><div class="st"><span>SEÑ ${stat(c,0)}</span><span>VEL ${stat(c,1)}</span><span>AB ${stat(c,2)}</span><span>ROB ${stat(c,3)}</span></div>${o.count&&own&&own.n>1?`<div class="cnt">x${own.n}</div>`:''}</div>`}
function deckHTML(asig,mode){const cells=[0,1,2].map(i=>{const c=CARD[S.deck[i]];return c?`<div onclick="pickDeck()">${cardHTML(c)}</div>`:`<div class="slot" onclick="pickDeck()">+</div>`}).join('');
 return `<div class="grid3" style="margin-top:8px">${cells}</div><div class="mut" style="margin-top:8px">${bonusText(deckBonus(asig,S.deck,mode))}${asig&&asig!=='ALL'?' (incluye +10% por cartas de la asignatura)':''}</div>`}
function pickDeck(){const owned=ownedCards();if(!owned.length){toast('Abre sobres para conseguir cartas 🎁');return}let sel=S.deck.filter(id=>CARD[id]);
 modal(`<h3>Elige tu mazo (máx. 3)</h3><div class="mut" id="dk-b">${bonusText(deckBonus(null,sel))}</div><div class="mut">SEÑAL = más tiempo · VELOCIDAD = monedas · ANCHO DE BANDA = XP y copas · ROBUSTEZ = escudos. Los ICON tienen una habilidad.<br>🎮 Ventajas por asignatura: Señales → Contrarreloj · Mates 3 → cálculos · Redes → Duelo · Electrónica → Supervivencia · Programación → Mundos.</div><div class="grid3" style="margin-top:10px">${owned.map(c=>`<div class="pick ${sel.includes(c.id)?'sel':''}" data-id="${c.id}">${cardHTML(c)}</div>`).join('')}</div><button class="btn" style="margin-top:14px" id="dk-ok">Listo</button>`);
 $('#modal').querySelectorAll('.pick').forEach(el=>el.onclick=()=>{const id=el.dataset.id;if(sel.includes(id))sel=sel.filter(x=>x!==id);else if(sel.length<3)sel.push(id);else{toast('Máximo 3 cartas: quita una antes');return}el.classList.toggle('sel',sel.includes(id));$('#dk-b').innerHTML=bonusText(deckBonus(null,sel))});
 $('#dk-ok').onclick=()=>{S.deck=sel;save();closeModal();render()}}

/* ====== NAVEGACIÓN ====== */
const V=$('#view');let route='home',ARG=null;
function go(r,arg){const changed=route!==r;if(arg!==undefined)ARG=arg;route=r;stopTimer();if(r!=='play')closeCalc();window.scrollTo(0,0);render();V.scrollTop=0;if(changed){V.classList.remove('view-enter');void V.offsetWidth;V.classList.add('view-enter')}}
const VIEWS={};
function render(){renderTop();renderNav();(VIEWS[route]||VIEWS.home)();updateGameAtmosphere()}
let PREV=null;
function renderTop(){const L=league(S.trophies),cur={c:S.coins,t:S.trophies};const bc=PREV&&cur.c!==PREV.c,bt=PREV&&cur.t!==PREV.t;
 $('#top').innerHTML=`<div class="pill p-coin ${bc?'bump':''}"><i>🪙</i>${S.coins}</div><div class="pill p-tro ${bt?'bump':''}"><i>${L.e}</i>${S.trophies}</div><div class="pill p-fire"><i>🔥</i>${streakNow()}</div><div class="pill p-lvl"><i>⭐</i>Nv ${lvl()}</div><button class="sound-toggle" type="button" aria-label="${S.sound?'Silenciar sonido':'Activar sonido'}" aria-pressed="${!!S.sound}" title="${S.sound?'Silenciar sonido':'Activar sonido'}" onclick="toggleSound()">${S.sound?'🔊':'🔇'}</button>`;
 if(bc){const d=cur.c-PREV.c;const e=document.createElement('div');e.className='tdelta '+(d>0?'up':'down');e.textContent=(d>0?'+':'')+d+' 🪙';$('#top').appendChild(e);setTimeout(()=>e.remove(),1300)}PREV=cur}
const NAV=[['home','🏠','Inicio'],['worlds','🗺️','Mundos'],['packs','🎁','Sobres'],['album','🃏','Álbum'],['more','☰','Más']];
const SUB={home:['quick','result','pass','profile','flash','run','exam'],worlds:['world'],more:['imp','prompt','tables','stats','road','backup','settings','ach']};
function renderNav(){const n=$('#nav');if(route==='play'){n.style.display='none';return}n.style.display='';const dot={packs:pendingPacks()>0,home:claimable()||S.spinDay!==today()||passClaimable()>0||S.chests.some(c=>c.end&&Date.now()>=c.end)};n.innerHTML='<div class="in">'+NAV.map(([r,e,t])=>`<button class="${route===r||(SUB[r]||[]).includes(route)?'on':''}" onclick="go('${r}')"><span>${e}</span>${t}${dot[r]?'<i class="dot"></i>':''}</button>`).join('')+'</div>'}

