const pendingPacks=()=>(S.freeDay!==today()?1:0)+(S.inv.normal||0)+(S.inv.premium||0)+(S.inv.themed||0)+(S.inv.mutation||0)+S.iconPacks;
const claimable=()=>{ensureMis();return S.mis.list.some(x=>!x.cl&&x.p>=x.g)};
VIEWS.home=()=>{ensureMis();const pp=pendingPacks(),cl=claimable();const li=leagueIdx(S.trophies),L=LEAGUES[li],nx=LEAGUES[li+1],lv=lvl(),b0=(lv-1)**2*100,b1=lv**2*100,fails=failPool().length,m=S.mis,spin=S.spinDay!==today();
 const T=myTitle(),pt=passTier(),pcl=passClaimable();V.innerHTML=`<div class="logo"><svg viewBox="0 0 120 30" aria-hidden="true"><path d="M2 15 Q12 2 22 15 T42 15 T62 15 T82 15 T102 15 T118 15"/></svg><b>TELECOM</b><span>LEGENDS</span></div><div class="hero" onclick="go('profile')" style="cursor:pointer"><div class="mut">${T.e} ${T.n} · <u>perfil</u></div><div class="emblem"><span>${L.e}</span></div><div class="lg">${L.n}</div><div class="mut">${nx?`${nx.min-S.trophies} copas para ${nx.e} ${nx.n}`:'¡Liga máxima!'}</div><div class="xpbar"><i style="width:${Math.round((S.xp-b0)/(b1-b0)*100)}%"></i></div><div class="mut">Nivel ${lv} · ${S.xp-b0}/${b1-b0} XP</div></div>
 ${pp?`<button class="btn gold pulse" style="margin-bottom:12px" onclick="go('packs')">🎁 Tienes ${pp} sobre${pp>1?'s':''} por abrir</button>`:''}
 <div class="modes">
  <button class="mode wide" data-w="" style="--c:#2563eb" onclick="go('exam')"><span>📄</span><b>Simulacro de examen</b><small>10 preguntas, 8 minutos y nota sobre 10${S.exam&&S.exam.ALL?` · mejor mezcla ${Number(S.exam.ALL).toFixed(1)}`:''}</small></button>
  <button class="mode" data-w="" style="--c:#7c5cff" onclick="QS.mode='duel';go('quick')"><span>⚔️</span><b>Duelo</b><small>10 preguntas contra un rival · ganas copas</small></button>
  <button class="mode" data-w="" style="--c:#c026d3" onclick="QS.mode='clash';go('quick')"><span>🃏</span><b>Batalla de cartas</b><small>Tu mazo contra el suyo · acierta para potenciar tus cartas</small></button>
  <button class="mode" data-w="" style="--c:#d97706" onclick="QS.mode='cup';go('quick')"><span>🏆</span><b>Copa Telecom</b><small>Cuartos, semis y final${S.cupDay!==today()?' · <b>¡gratis hoy!</b>':''}</small></button>
  <button class="mode" data-w="" style="--c:#0d9488" onclick="go('flash')"><span>📚</span><b>Tarjetas de estudio</b><small>Pregunta, respuesta y tú dices si lo sabías</small></button>
  <button class="mode" data-w="" style="--c:#e11d48" onclick="QS.mode='surv';go('quick')"><span>❤️</span><b>Supervivencia</b><small>3 vidas y cada vez más difícil · récord ${S.rec.surv}</small></button>
  <button class="mode" data-w="" style="--c:#0891b2" onclick="QS.mode='blitz';go('quick')"><span>⏱️</span><b>Contrarreloj</b><small>60 s para acertar todo lo que puedas · récord ${S.rec.blitz}</small></button>
  <button class="mode" data-w="" style="--c:#7f1d1d" onclick="go('run')"><span>🏰</span><b>Expedición</b><small>${S.run&&S.run.v===2?`<b>En curso · acto ${S.run.act} · piso ${S.run.floor}</b>`:'Roguelike de 3 actos: enemigos, reliquias, pociones y jefes'}</small></button>
  <button class="mode" data-w="" style="--c:#16a34a" onclick="go('worlds')"><span>🗺️</span><b>Mundos</b><small>10 niveles por tema y jefes finales</small></button></div>
 <div class="row" style="margin-bottom:12px"><button class="btn sec" ${fails?'':'disabled'} onclick="startFails()">🎯 Fallos (${fails})</button><button class="btn sec" onclick="startSmartReview()">🩺 Repaso</button><button class="btn ${spin?'gold':'sec'}" onclick="spinWheel()">🎡 Ruleta${spin?' gratis':''}</button></div>
 ${chestsHTML()}
 <div class="card-box ${pcl?'glow':''}" onclick="go('pass')" style="cursor:pointer"><div class="rowb"><b>🎫 Pase Telecom · nivel ${pt}/${PASS_T}</b>${pcl?`<span class="badge">¡${pcl} por cobrar!</span>`:'<span class="mut">›</span>'}</div><div class="xpbar"><i style="width:${pt>=PASS_T?100:S.pass.p%PASS_P/PASS_P*100}%"></i></div><small class="mut">+10 por acierto y +30 por victoria · siguiente: ${pt<PASS_T?passRw(pt+1).t:'¡completado!'}</small></div>
 <div class="fwb weekb">⭐ Asignatura de la semana: <b>${ASIG[weekAsig()].icon} ${esc(ASIG[weekAsig()].name)}</b> · monedas y XP de cartas x2</div>
 ${S.fwd!==today()?'<div class="fwb">⭐ Primera victoria del día en Duelo: <b>monedas x2</b> y un cofre seguro</div>':''}
 ${S.freeDay!==today()?`<div class="card-box glow"><b>🎁 Sobre gratis de hoy</b><div class="mut">Uno cada día. ¡No pierdas la racha! (3 días = sobre extra; 7 días = Premium)</div><button class="btn gold" style="margin-top:10px" onclick="openPack('free')">Abrir gratis</button></div>`:''}
 <div class="card-box ${cl?'glow':''}"><div class="rowb"><b>🎯 Misiones de hoy ${cl?'<span class="badge">¡Cobra!</span>':''}</b><span class="mut">${m.list.filter(x=>x.cl).length}/3 cobradas</span></div>${m.list.map((x,i)=>`<div class="mis"><div><div style="font-size:14px">${esc(x.t)}</div><div class="xpbar"><i style="width:${x.p/x.g*100}%"></i></div><small class="mut">${x.p}/${x.g} · +${x.rw} 🪙</small></div>${x.cl?'✅':x.p>=x.g?`<button class="btn gold sm" onclick="claimMis(${i})">Cobrar</button>`:''}</div>`).join('')}<div class="mut">Cobra las 3 → ✨ Sobre Premium${m.bonus?' (conseguido)':''}</div></div>${wmisHTML()}
 <div class="card-box"><div class="rowb"><b>🃏 Tu mazo</b><button class="lnk" onclick="pickDeck()">Cambiar</button></div>${deckHTML()}</div>
 <button class="menu" onclick="go('diag')"><span>🧭</span><div><b>Diagnóstico de estudio</b><small>Tus temas flojos y una sesión dirigida por el Director</small></div><i>›</i></button>
 ${S.qs.length<80?`<div class="card-box"><b>📥 Mete tus preguntas</b><div class="mut">Tienes ${S.qs.length} preguntas. Pídele más a Gemini con el prompt y pega su respuesta en Importar.</div><div class="row" style="margin-top:10px"><button class="btn sec" onclick="go('prompt')">📋 Prompt</button><button class="btn" onclick="go('imp')">📥 Importar</button></div></div>`:''}`};

/* ====== MISIONES, LOGROS, RULETA ====== */
const MT=[{k:'clashw',t:'Gana {g} batallas de cartas',g:[1,2]},{k:'flash',t:'Repasa {g} tarjetas de estudio',g:[10,20]},{k:'win',t:'Gana {g} duelos',g:[2,3]},{k:'correct',t:'Acierta {g} preguntas',g:[15,25]},{k:'combo',t:'Consigue un combo de {g}',g:[5,7],max:1},{k:'hard',t:'Acierta {g} preguntas Difíciles o Extremas',g:[4,8]},{k:'level',t:'Supera {g} niveles de un mundo',g:[2,3]},{k:'pack',t:'Abre {g} sobres',g:[1,2]},{k:'surv',t:'Llega a {g} aciertos en Supervivencia',g:[8,12],max:1},{k:'blitz',t:'Haz {g} aciertos en una Contrarreloj',g:[8,12],max:1},{k:'fast',t:'Acierta rápido ⚡ {g} veces',g:[5,10]}];
function ensureMis(){if(S.mis&&S.mis.d===today())return;S.mis={d:today(),bonus:false,list:shuffle(MT).slice(0,3).map(m=>{const g=rnd(m.g);return {k:m.k,t:m.t.replace('{g}',g),g,p:0,max:!!m.max,rw:m.rw?m.rw(g):(m.k==='win'||m.k==='level'?40+g*30:40+g*6),cl:false}})};save()}
function prog(k,v){ensureMis();ensureWMis();S.wmis.list.forEach(m=>{if(m.k!==k||m.p>=m.g)return;m.p=m.max?Math.max(m.p,v):m.p+v;if(m.p>=m.g){m.p=m.g;setTimeout(()=>toast('📆 Misión semanal completada: '+m.t),700)}});S.mis.list.forEach(m=>{if(m.k!==k||m.p>=m.g)return;m.p=m.max?Math.max(m.p,v):m.p+v;if(m.p>=m.g){m.p=m.g;setTimeout(()=>toast('🎯 Misión completada: '+m.t),500)}})}
function claimMis(i){const m=S.mis.list[i];if(!m||m.cl||m.p<m.g)return;m.cl=true;S.coins+=m.rw;sfx('gold');toast(`+${m.rw} 🪙`);
 if(!S.mis.bonus&&S.mis.list.every(x=>x.cl)){S.mis.bonus=true;S.inv.premium++;celebrate('🎯','¡Misiones completadas!','Te llevas un ✨ Sobre Premium. Lo tienes en Sobres.')}save();render()}
