const ACTS=[
 {n:'El Laboratorio',c:'#b45309',e:'🔬',en:[['Resistencia rebelde','🔌'],['Condensador cargado','🔋'],['Diodo zombi','🧟'],['Ruido térmico','🌡️'],['Cable pelado','🐍'],['Protoboard maldita','🧩']],el:[['Osciloscopio poseído','📟'],['Fuente de alimentación loca','⚡']],boss:['El Gran Cortocircuito','🌩️',['furia','espinas']]},
 {n:'La Red',c:'#1d4ed8',e:'🌐',en:[['Paquete perdido','📦'],['Colisión CSMA','💥'],['Bucle de encaminamiento','🔁'],['Trama corrupta','🧬'],['Router zombi','🛜'],['Eco de latencia','📶']],el:[['Tormenta de broadcast','🌪️'],['Kraken de la latencia','🐙']],boss:['La Hidra de la Congestión','🐉',['regenera','blindado']]},
 {n:'El Núcleo',c:'#7e22ce',e:'🖥️',en:[['Bug de memoria','🐛'],['Puntero colgante','🪝'],['Fuga de memoria','💧'],['Microinstrucción rebelde','🧩'],['Aliasing fantasma','👻'],['Matriz singular','🔳']],el:[['Máquina de estados infinita','♾️'],['Transformada maldita','🌀']],boss:['El Señor del Kernel','👑',['vampiro','dificil','escudo']]}];
const TRAITS={rapido:{e:'⏩',n:'Rápido',d:'−30 % de tiempo para responder'},blindado:{e:'🛡️',n:'Blindado',d:'Recibe un 30 % menos de daño'},regenera:{e:'💚',n:'Regenera',d:'Recupera un 5 % de vida en cada pregunta'},furia:{e:'😡',n:'Furia',d:'Su ataque sube +2 en cada pregunta'},vampiro:{e:'🧛',n:'Vampiro',d:'Se cura lo que te quita'},dificil:{e:'🧠',n:'Erudito',d:'Sus preguntas son un nivel más difíciles'},espinas:{e:'🌵',n:'Espinas',d:'Te quita 2 PV cada vez que le golpeas'},escudo:{e:'🔰',n:'Escudo',d:'Bloquea tu primer golpe'}};
const RELICS={osc:{e:'📟',n:'Osciloscopio',d:'+8 s en cada pregunta'},ext:{e:'🧯',n:'Extintor',d:'Un escudo extra en cada combate'},pri:{e:'🔷',n:'Prisma',d:'+50 % de gemas'},bat:{e:'🔋',n:'Batería',d:'+15 PV máximos'},las:{e:'🎯',n:'Mira láser',d:'+2 💎 por acierto'},tir:{e:'🩹',n:'Tiritas',d:'Recuperas 6 PV tras cada combate'},tre:{e:'🍀',n:'Trébol',d:'25 % de que un fallo no te haga daño'},ant:{e:'📡',n:'Antena',d:'Las preguntas son un nivel más fáciles'},chip:{e:'💾',n:'Chip de memoria',d:'Tus cartas ganan el doble de XP en la expedición'},
 amp:{e:'🔊',n:'Amplificador',d:'+25 % de daño'},tes:{e:'⚡',n:'Bobina de Tesla',d:'Cada 3.er acierto de un combate hace x3'},vam:{e:'🦇',n:'Vampiro de señal',d:'Recuperas 3 PV por acierto'},cua:{e:'⚛️',n:'Bit cuántico',d:'+20 % de probabilidad de crítico'},dis:{e:'🧊',n:'Disipador',d:'Recibes un 25 % menos de daño'},rul:{e:'🎲',n:'Ruleta rusa',d:'+60 % de daño, pero recibes un 40 % más'},fib:{e:'💡',n:'Fibra óptica',d:'Tu primer acierto de cada combate hace x2'},ven:{e:'🪟',n:'Ventana deslizante',d:'El primer fallo de cada combate hace la mitad y no rompe el combo'},mod:{e:'📠',n:'Módem 56k',d:'+15 s por pregunta, pero −10 % de daño'},rel:{e:'⌚',n:'Reloj atómico',d:'+1 hueco de poción (máximo 4)'}};
const POTS={bomba:{e:'💣',n:'Bomba de pulso',d:'Quita 35 PV al enemigo'},botiquin:{e:'🧪',n:'Botiquín',d:'Recuperas 20 PV'},escudo:{e:'🛡️',n:'Escudo',d:'+1 escudo en este combate'},reloj:{e:'⏳',n:'Reloj de arena',d:'Congela el tiempo de esta pregunta'},tijeras:{e:'✂️',n:'Tijeras 50/50',d:'Elimina 2 opciones incorrectas'},sobre:{e:'🔥',n:'Sobrecarga',d:'Tu próximo acierto hace x3'}};
const hasR=k=>!!(S.run&&S.run.relics.includes(k));
const hasTr=t=>!!(S.run&&S.run.enemy&&S.run.enemy.traits.includes(t));
const potMax=()=>hasR('rel')?4:3;
function relicChoices(){return shuffle(Object.keys(RELICS).filter(k=>!S.run.relics.includes(k))).slice(0,3)}
function addRelic(k){const r=S.run;if(!k||!RELICS[k]||r.relics.includes(k))return;r.relics.push(k);trk('relMax',r.relics.length,1);if(k==='bat'){r.maxhp+=15;r.hp+=15}toast(`${RELICS[k].e} Reliquia: ${RELICS[k].n}`)}
function addPot(k){const r=S.run;k=k||pk(Object.keys(POTS));if(r.pots.length>=potMax()){toast('Pociones llenas');return false}r.pots.push(k);toast(`${POTS[k].e} Poción: ${POTS[k].n}`);return true}
function giveDeckXP(n){S.deck.forEach(id=>{const c=CARD[id],o=S.cards[id];if(!c||!o)return;const mx=maxL(o);o.xp=(o.xp||0)+n*(hasR('chip')?2:1);while(o.l<mx&&o.xp>=xpNeed(o.l)){o.xp-=xpNeed(o.l);o.l++;toast(`⬆️ ${c.e} ${c.n} → Nv ${o.l}`)}if(o.l>=mx)o.xp=Math.min(o.xp,xpNeed(o.l))})}
function routeQuestionMatches(k,q){if(k==='calc')return !!q.calc;if(k==='tables')return !!q.tabla||q.route==='tables';if(k==='code')return q.route==='code'||/```/.test(q.q||'');if(k==='speed')return !q.calc&&!q.tabla&&q.route!=='tables'&&q.route!=='code'&&!/```/.test(q.q||'')&&(q.q||'').length<=160&&q.dif<=2;return true}
function genNodes(f){if(f>=RUN_F)return ['boss'];const r=S.run,asig=r&&r.asig||'ALL',focus=['calc','tables','code','speed'].filter(k=>S.qs.some(q=>(asig==='ALL'||q.asig===asig)&&routeQuestionMatches(k,q)));const pool=f<=2?['combat','combat','event','treasure']:f===RUN_F-1?['rest','shop','elite']:['combat','combat','elite','shop','rest','event','treasure','combat','elite'];const out=new Set();if(focus.length)out.add(pk(focus));let g=0;while(out.size<(f%3===0?3:2)&&g++<60)out.add(pk(pool));return [...out]}
function genEnemy(kind){const r=S.run,A=ACTS[r.act-1],sc=(1+.1*r.asc)*(1+(r.floor-1)*.07),ac=1+.08*r.asc;let t,traits=[],hp,atk;
 if(kind==='boss'){t=A.boss;traits=[...A.boss[2]];hp=120+60*(r.act-1);atk=9+3*(r.act-1)}
 else{t=pk(kind==='elite'?A.el:A.en);hp=30+22*(r.act-1);atk=6+3*(r.act-1);const tk=Object.keys(TRAITS);if(kind==='elite'){hp*=1.7;atk*=1.3;traits=shuffle(tk).slice(0,1+(r.act>1?1:0))}else if(Math.random()<.3+.3*r.act)traits=[pk(tk)]}
 hp=Math.round(hp*sc);return {n:t[0],e:t[1],hp,maxhp:hp,atk:Math.round(atk*ac),traits,boss:kind==='boss',elite:kind==='elite',shieldUp:traits.includes('escudo')}}
function runPred(){const r=S.run,a=r.asig;return q=>(a==='ALL'||q.asig===a)&&(!r.challenge||routeQuestionMatches(r.challenge,q))}
function runDifs(kind){const r=S.run,E=r.enemy;let d=Math.max(1,Math.min(4,r.act+(r.floor>=5?1:0)-(hasR('ant')?1:0)+(kind==='elite'?1:0)+(E&&E.traits.includes('dificil')?1:0)+(['calc','tables','code'].includes(r.challenge)?1:0)));return kind==='boss'?[...new Set([Math.max(2,d),Math.min(4,d+1)])]:[d]}
function runFight(kind){const r=S.run;if(!r.enemy)r.enemy=genEnemy(kind);r.enemy.kind=kind;save();const difs=runDifs(kind),p=runPred(),count=kind==='boss'?3:1,qs=pickQs(p,count,difs).map((q,i)=>kind==='boss'?Object.assign({},q,{q:`CUELLO DE BOTELLA · ETAPA ${i+1}/3\n${q.q}`}):q);startMatch({mode:'run',runNode:kind,asig:r.asig,pred:p,runDifs:difs,qs,endless:kind!=='boss',noTimer:false});const E0=r.enemy;setTimeout(()=>floatTxt(`${E0.e} ${E0.n}`,'#fca5a5'),350)}
function runTime(t){let x=t;if(hasTr('rapido'))x*=.7;if(hasR('mod'))x+=15;if(S.run&&S.run.challenge==='speed')x*=.75;return x}
function runDmg(){const cs=S.deck.map(id=>CARD[id]).filter(Boolean),q=M.qs[M.i].q;const pw=cs.length?cs.reduce((a,c)=>a+[0,1,2,3].reduce((x,i)=>x+stat(c,i),0)/4,0)/cs.length:50,vel=cs.length?cs.reduce((a,c)=>a+stat(c,1),0)/cs.length:50;
 let d=10+pw/8+4*(S.run.act-1);if(cs.some(c=>c.a===q.asig||c.a==='ALL'))d+=4;d*=1+.05*Math.min(M.combo,10);if(hasR('amp'))d*=1.25;if(hasR('rul'))d*=1.6;if(hasR('mod'))d*=.9;if(M.gold)d*=2;
 M.hits=(M.hits||0)+1;if(hasR('tes')&&M.hits%3===0){d*=3;floatTxt('⚡ ¡Bobina de Tesla! x3','#fde047',400)}if(hasR('fib')&&M.hits===1)d*=2;if(M.over3){d*=3;M.over3=false}
 if(Math.random()<.08+vel/1000+(hasR('cua')?.2:0)){d*=2;floatTxt('💥 ¡CRÍTICO!','#fb923c',150)}return Math.round(d)}
function runBar(){const r=S.run,E=r&&r.enemy;if(!r||!E)return '';const A=ACTS[r.act-1];
 return `<div class="enemy ${E.boss?'boss':E.elite?'elite':''}" style="--ac:${A.c}"><div class="en-top"><span class="en-e">${E.e}</span><div class="en-info"><b>${esc(E.n)}${E.boss?' · JEFE':E.elite?' · ÉLITE':''}${E.p2?' · FASE 2':''}</b><div class="en-tr">${E.traits.map(t=>`<i onclick="toast('${TRAITS[t].e} ${TRAITS[t].n}: ${TRAITS[t].d}')">${TRAITS[t].e} ${TRAITS[t].n}</i>`).join('')||'<i>Normal</i>'}</div></div><div class="en-int">⚔️ <b id="eint">${E.atk}</b><small>si fallas</small></div></div>
 <div class="hpb"><i id="ehp" style="width:${E.hp/E.maxhp*100}%"></i><span id="ehpt">${E.hp}/${E.maxhp}${E.shieldUp?' 🔰':''}</span></div>
 <div class="hpb me"><i id="php2" style="width:${r.hp/r.maxhp*100}%"></i><span id="phpt">❤️ ${r.hp}/${r.maxhp}</span></div>
 <div class="pots">${r.pots.map((k,i)=>`<button class="pot" onclick="usePot(${i})" aria-label="${POTS[k].n}">${POTS[k].e}</button>`).join('')}<span class="mut">💎 <b id="rgm">${r.gems}</b> · ${A.e} Acto ${r.act} · piso ${r.floor}</span></div></div>`}
function updRunUI(){const r=S.run,E=r&&r.enemy;if(!r)return;const s=(id,v,w)=>{const e=$('#'+id);if(!e)return;if(w)e.style.width=v;else e.textContent=v};if(E){s('ehp',Math.max(0,E.hp/E.maxhp*100)+'%',1);s('ehpt',`${E.hp}/${E.maxhp}${E.shieldUp?' 🔰':''}`);s('eint',E.atk)}s('php2',Math.max(0,r.hp/r.maxhp*100)+'%',1);s('phpt',`❤️ ${r.hp}/${r.maxhp}`);s('rgm',r.gems)}
function usePot(i){const r=S.run;if(!M||M.ans!==null||!r||!r.enemy)return;const k=r.pots[i];if(!k)return;r.pots.splice(i,1);trk('pot');prog('pot',1);const E=r.enemy,it=M.qs[M.i],q=it.q;sfx('power');
 if(k==='bomba'){E.hp=Math.max(0,E.hp-35);r.dmg+=35;floatTxt('💣 −35','#fca5a5')}else if(k==='botiquin'){r.hp=Math.min(r.maxhp,r.hp+20);floatTxt('🧪 +20 PV','#86efac')}else if(k==='escudo'){M.shields++;floatTxt('🛡️ +1 escudo','#7dd3fc')}else if(k==='reloj'){M.frozen=true;floatTxt('⏳ Tiempo congelado','#7dd3fc')}else if(k==='tijeras'){shuffle(it.order.filter(x=>x!==q.ok&&!M.hidden.has(x))).slice(0,q.ops.length>2?2:0).forEach(x=>M.hidden.add(x))}else if(k==='sobre'){M.over3=true;floatTxt('🔥 Próximo acierto x3','#fb923c')}
 save();if(E.hp<=0){M.runWin=true;M.over=true;stopTimer();floatTxt('☠️ ¡Derrotado!','#fca5a5');setTimeout(()=>endMatch(),700);return}drawQ()}
function runOnAnswer(good,saved){const r=S.run,E=r&&r.enemy;if(!r||!E)return;
 if(good){let dmg=runDmg();if(E.shieldUp){E.shieldUp=false;floatTxt('🔰 ¡Bloqueado!','#7dd3fc',200)}else{if(hasTr('blindado'))dmg=Math.round(dmg*.7);E.hp=Math.max(0,E.hp-dmg);r.dmg+=dmg;floatTxt(`💥 −${dmg}`,'#fca5a5',200);if(hasTr('espinas'))r.hp=Math.max(0,r.hp-2)}
  if(hasR('vam'))r.hp=Math.min(r.maxhp,r.hp+3);if(hasR('las'))r.gems+=2;
  if(E.boss&&!E.p2&&E.hp>0&&E.hp<=E.maxhp/2){E.p2=true;['rapido','furia'].forEach(t=>{if(!E.traits.includes(t))E.traits.push(t)});setTimeout(()=>{floatTxt('😈 ¡FASE 2!','#f87171');sfx('icon');shake()},500)}}
 else if(!saved){if(hasR('tre')&&Math.random()<.25)floatTxt('🍀 ¡El trébol te salva!','#86efac');else{const half=hasR('ven')&&!M.venUsed;let d=Math.round(E.atk*(hasR('dis')?.75:1)*(hasR('rul')?1.4:1)*(half?.5:1));if(half){M.venUsed=true;M.combo=M.comboBefore||0}r.hp=Math.max(0,r.hp-d);floatTxt(`−${d} PV`,'#ef4444',200);if(hasTr('vampiro'))E.hp=Math.min(E.maxhp,E.hp+d)}}
 if(hasTr('furia'))E.atk+=E.boss?1:2;updRunUI();
 if(E.hp<=0){M.over=true;M.runWin=true;setTimeout(()=>{floatTxt('☠️ ¡Derrotado!','#fca5a5');sfx('gold')},300)}else if(r.hp<=0){M.over=true;M.runWin=false}save()}
function runOnShow(){const r=S.run,E=r&&r.enemy;if(!E)return;if(hasTr('regenera')&&E.hp>0&&E.hp<E.maxhp){E.hp=Math.min(E.maxhp,E.hp+Math.round(E.maxhp*.05))}}
function runAfterMatch(){const r=S.run;S.matches++;S.pass.p+=M.correct*6;const ups=M.cardUps||[];if(ups.length)setTimeout(()=>toast('⬆️ '+ups.join(' · ')),500);
 checkMastery([...new Set(M.res.map(x=>{const q=findQ(x.id);return q?q.asig+'|'+q.tk:null}).filter(Boolean))]);
 if(!r)return go('home');if(r.hp<=0)return runEnd(false);if(!M.runWin){save();return go('run')}
 const E=r.enemy;r.enemy=null;r.kills=(r.kills||0)+1;if(E.boss){trk('acts');prog('act',1)}if(E.elite)trk('elites');if(E.traits&&E.traits.length>=2)trk('trait2');const gem=Math.round((E.boss?40:E.elite?18:8+r.act*3)*(hasR('pri')?1.5:1)*(1+.15*r.asc));r.gems+=gem;if(hasR('tir'))r.hp=Math.min(r.maxhp,r.hp+6);
 if(E.boss&&r.act>=RUN_ACTS){save();return runEnd(true)}
 r.reward=E.boss||E.elite?{type:'relic',opts:relicChoices(),gem,boss:E.boss,pot:Math.random()<.5}:{type:'pick',opts:shuffle(['pot','gems','xp','maxhp']).slice(0,3),gem};
 save();go('run')}
function runReward(k){const r=S.run,R=r.reward;if(!R)return;if(R.type==='relic')addRelic(k);else if(k==='pot')addPot();else if(k==='gems')r.gems+=15;else if(k==='xp')giveDeckXP(40);else if(k==='maxhp'){r.maxhp+=5;r.hp+=5}
 if(R.type==='relic'&&R.pot)addPot();const boss=R.boss;r.reward=null;sfx('gold');
 if(boss){r.act++;r.floor=1;r.path=[];r.hp=Math.min(r.maxhp,r.hp+Math.round(r.maxhp*.5));r.nodes=genNodes(1);save();const A=ACTS[r.act-1];celebrate(A.e,`Acto ${r.act}: ${A.n}`,'Recuperas la mitad de tu vida. Los enemigos ahora son más duros… y dan más gemas.');go('run');return}
 runAdvance()}
