 const A=ACTS[r.act-1];const path=Array.from({length:RUN_F},(_,i)=>i+1).map(f=>`<i class="${f<r.floor?'done':f===r.floor?'now':''}">${f===RUN_F?A.boss[1]:f<r.floor?(NODES2[r.path[f-1]]||{}).e||'·':f}</i>`).join('');
