 const t=(M.mode==='quick'?DIFS[M.dif]:DIFS[q.dif]).t;M.tMax=((q.calc?(t*3+30)*M.calcT:t)+M.bonus.tb)*(M.mod&&MODS[M.mod].t||1);if(M.mode==='run'){M.tMax=runTime(M.tMax);runOnShow()}M.t=M.tMax;M.t0=Date.now();
