function quitMatch(){modal(`<h3>¿Salir de la partida?</h3><div class="mut">No te llevarás recompensas de esta partida.</div><div class="row" style="margin-top:14px"><button class="btn sec" onclick="closeModal()">Seguir</button><button class="btn" onclick="closeModal();stopTimer();M=null;go('home')">Salir</button></div>`)}
