function rollR(kind){const o=PACKS[kind].o,b=0.005*leagueIdx(S.trophies),I=o.I+b,r=Math.random();return r<I?'I':r<I+o.O?'O':r<I+o.O+o.P?'P':'B'}
function openPack(type,gift){let kind=type;if(type==='free'){if(S.freeDay===today())return;S.freeDay=today();kind='normal'}else if(type==='icon'){if(S.iconPacks<1)return;S.iconPacks--}else if(type==='invP'){if(S.inv.premium<1)return;S.inv.premium--;kind='premium'}else if(type==='invN'){if(S.inv.normal<1)return;S.inv.normal--;kind='normal'}else if(type==='invT'){if((S.inv.themed||0)<1)return;S.inv.themed--;kind='themed'}else if(type==='invM'){if((S.inv.mutation||0)<1)return;S.inv.mutation--;kind='mutation'}
 else if(!gift){const p=PACKS[type].p;if(S.coins<p){toast('No tienes monedas suficientes 🪙');sfx('bad');return}S.coins-=p}
 const info=grantCards(3,kind,type==='icon',kind==='themed'&&TL_PACK_ASIG!=='ALL'?TL_PACK_ASIG:null);if(kind==='mutation')S.mutagen=(S.mutagen||0)+1;prog('pack',1);save();renderTop();showOpening(info,kind==='mutation'?{n:PACKS[kind].n+' · +1 catalizador'}:PACKS[kind])}
function grantCards(n,kind,forceI,asig){const got=[];const pityHit=!forceI&&(S.pity||0)>=39;for(let i=0;i<n;i++){const r=(forceI||pityHit)&&i===0?'I':rollR(kind);let pool=CARDS.filter(c=>c.r===r&&(!asig||c.a===asig||c.a==='ALL'));if(!pool.length)pool=CARDS.filter(c=>c.r===r);got.push(rnd(pool))}if(pityHit)setTimeout(()=>toast('★ ¡ICON garantizada por la barra de suerte!'),400);S.pity=got.some(c=>c.r==='I')?0:(S.pity||0)+1;got.sort((a,b)=>RORD[a.r]-RORD[b.r]);const shp=kind==='premium'||kind==='themed'?.07:kind==='mutation'?.08:.04;
 const info=got.map(c=>{const had=!!S.cards[c.id];if(had)S.cards[c.id].n++;else S.cards[c.id]={n:1,l:1};const sh=Math.random()<shp;if(sh)S.cards[c.id].sh=1;return {c,isNew:!had,sh}});
 info.forEach(({c})=>{if(S.deck.length<3&&!S.deck.includes(c.id))S.deck.push(c.id)});return info}
function showOpening(info,pk){let rev=0;
 modal(`<h3>${pk.n}</h3><div class="mut">Toca cada carta para darle la vuelta</div><div class="rays" aria-hidden="true"></div><div class="pack-stage">${info.map((x,i)=>`<div class="flip" data-i="${i}"><div class="in"><div class="dorso"><span>📡</span>TL</div><div class="frontc">${cardHTML(x.c)}<span class="newb ${x.sh?'shb':x.isNew?'':'dup'}">${x.sh?'✨ BRILLANTE':x.isNew?'NUEVA':'REPETIDA'}</span></div></div></div>`).join('')}</div><div class="row" style="margin-top:16px"><button class="btn sec" id="op-all">Abrir todas</button><button class="btn" id="op-ok" disabled>Continuar</button></div>`,true);
 const flips=[...$('#modal').querySelectorAll('.flip')];
 const open=el=>{if(el.classList.contains('open'))return;const x=info[+el.dataset.i];el.classList.add('open','g-'+x.c.r);rev++;
  sfx('cardFlip',x.c.r);if(x.sh){setTimeout(()=>{toast(`✨ ¡${x.c.n} BRILLANTE! +3 a todo`);confetti(60,['#7cffcb','#94d0ff','#fff','#ffe66d'])},350)}if(x.c.r==='I'){vib([80,50,80,50,200]);flash();confetti(120,['#ff6ad5','#ffe66d','#7cffcb','#94d0ff','#fff']);setTimeout(()=>toast(`★ ¡ICON! ${x.c.n}`),300)}else if(x.c.r==='O'){confetti(40,['#fde68a','#fbbf24','#fff'])}
  if(rev===info.length)$('#op-ok').disabled=false};
 flips.forEach(el=>el.onclick=()=>open(el));$('#op-all').onclick=()=>flips.forEach((el,i)=>setTimeout(()=>open(el),i*500));$('#op-ok').onclick=()=>{closeModal();render();checkSets();checkAch()};if(info.length===1&&flips[0])setTimeout(()=>open(flips[0]),400)}

/* ====== ÁLBUM ====== */
let AF='ALL';
VIEWS.album=()=>{const list=CARDS.filter(c=>AF==='ALL'||(AF==='I'?c.r==='I':c.a===AF)).sort((a,b)=>RORD[b.r]-RORD[a.r]);const own=CARDS.filter(c=>S.cards[c.id]).length;
 V.innerHTML=`<div class="rowb"><h2>🃏 Álbum <span class="mut">${own}/${CARDS.length}</span></h2><div class="row" style="flex:none;gap:6px"><button class="btn sm sec" onclick="workshop()">♻️ Taller ✨${S.dust}</button><button class="btn sm sec" onclick="cardForm()">✏️ Crear</button></div></div><div class="chips">${chip('Todas',AF==='ALL',"AF='ALL';render()")}${chip('★ ICON',AF==='I',"AF='I';render()")}${ASIGS.map(a=>chip(a.icon+' '+esc(a.name),AF===a.id,`AF='${a.id}';render()`)).join('')}</div>
 <div class="grid3">${list.map(c=>`<div onclick="${S.cards[c.id]?'cardDetail':'craftCard'}('${c.id}')">${cardHTML(c,{locked:!S.cards[c.id],count:true})}</div>`).join('')}</div>`};
const upCost=(c,o)=>50*o.l*RM[c.r];
const DUST={B:5,P:15,O:40,I:150},CRAFT={B:40,P:100,O:250,I:1000},UPD={B:10,P:25,O:60,I:200},FUS={B:5,P:5,O:6},NEXTR={B:'P',P:'O',O:'I'};
const dupCount=r=>CARDS.filter(c=>c.r===r&&S.cards[c.id]).reduce((x,c)=>x+S.cards[c.id].n-1,0);
function workshop(){const tot=CARDS.filter(c=>S.cards[c.id]).reduce((x,c)=>x+(S.cards[c.id].n-1)*DUST[c.r],0);
 modal(`<h3>♻️ Taller</h3><div class="lg" style="text-align:center">✨ ${S.dust}</div><div class="mut" style="text-align:center">Polvo de señal</div>
 <div class="card-box" style="margin-top:12px"><b>Reciclar repetidas</b><div class="mut">Convierte todas tus repetidas en polvo (te quedas 1 de cada). Bronce ${DUST.B} · Plata ${DUST.P} · Oro ${DUST.O} · ICON ${DUST.I}.</div><button class="btn" style="margin-top:10px" id="ws-rec" ${tot?'':'disabled'}>♻️ Reciclar todo (+${tot} ✨)</button></div>
 <div class="card-box"><b>Fusionar</b><div class="mut">Junta repetidas de una rareza y consigue una carta de la rareza siguiente (si puede ser, una que no tengas).</div>${['B','P','O'].map(r=>{const n=dupCount(r);return `<button class="btn ${r==='O'?'gold':'sec'}" style="margin-top:10px" ${n>=FUS[r]?'':'disabled'} onclick="fuse('${r}')">🔮 ${FUS[r]} ${RN[r]} → 1 ${RN[NEXTR[r]]} <small>(tienes ${n})</small></button>`}).join('')}</div>
 <div class="mut">El polvo también sirve para subir cartas de nivel y para fabricar cartas que te falten: toca una carta bloqueada del Álbum.</div>`);
 $('#ws-rec').onclick=()=>{CARDS.forEach(c=>{const o=S.cards[c.id];if(o&&o.n>1){S.dust+=(o.n-1)*DUST[c.r];o.n=1}});save();sfx('gold');toast(`+${tot} ✨ polvo`);workshop();render()}}
function fuse(r){let need=FUS[r];if(dupCount(r)<need)return;const pool=CARDS.filter(c=>c.r===r&&S.cards[c.id]&&S.cards[c.id].n>1).sort((a,b)=>S.cards[b.id].n-S.cards[a.id].n);
 while(need>0){for(const c of pool){if(need>0&&S.cards[c.id].n>1){S.cards[c.id].n--;need--}}}
 const nr=NEXTR[r],miss=CARDS.filter(c=>c.r===nr&&!S.cards[c.id]),c=rnd(miss.length?miss:CARDS.filter(x=>x.r===nr)),isNew=!S.cards[c.id];if(isNew)S.cards[c.id]={n:1,l:1};else S.cards[c.id].n++;save();renderTop();showOpening([{c,isNew}],{n:'🔮 Fusión'})}
function craftCard(id){const c=CARD[id],cost=CRAFT[c.r];if(S.cards[id])return cardDetail(id);
 modal(`<h3>🔨 Fabricar carta</h3><div class="dcard">${cardHTML(c,{locked:true})}</div><div class="mut" style="text-align:center">Carta ${RN[c.r]} ${c.a==='ALL'?'':'de '+esc(ASIG[c.a].name)}. Descubrirás cuál es al fabricarla.</div><button class="btn gold" style="margin-top:12px" id="cr-ok" ${S.dust>=cost?'':'disabled'}>Fabricar por ${cost} ✨ (tienes ${S.dust})</button>`);
 $('#cr-ok').onclick=()=>{if(S.dust<cost)return;S.dust-=cost;S.cards[id]={n:1,l:1};save();renderTop();showOpening([{c,isNew:true}],{n:'🔨 Fabricada'})}}
function cardDetail(id){const c=CARD[id],o=S.cards[id];if(!o)return;const inDeck=S.deck.includes(id),cost=upCost(c,o),extra=o.n-1,canUp=o.l<maxL(o)&&extra>=o.l&&S.coins>=cost;
 modal(`<div class="dcard">${cardHTML(c)}</div><div class="sol">${fmt(c.b)}</div>${c.ab?`<div class="card-box"><b>✨ Habilidad: ${AB[c.ab].s}</b><div class="mut">${AB[c.ab].d}. Una vez por partida.</div></div>`:''}
 <div class="card-box" style="margin-top:10px"><b>🎯 Cómo sacarle partido</b><div class="mut">Mejor estadística: <b>${STATN[c.s.indexOf(Math.max(...c.s))]}</b> (${Math.max(...c.s.map((_,k)=>stat(c,k)))}).${(()=>{const pk=PERKS.find(x=>x.g===grpOf(c.a));return pk?` Ventaja de asignatura: ${pk.n}, ${pk.d}.`:''})()} En la Batalla de cartas pega +30 si la pregunta es de su asignatura.</div></div><div class="mut">Nivel ${o.l}/${maxL(o)} · Copias: ${o.n}. Cada nivel suma +2 a cada estadística.</div>
 <div class="card-box" style="margin-top:8px"><b>📈 Experiencia de la carta</b><div class="xpbar"><i style="width:${o.l>=maxL(o)?100:Math.min(100,(o.xp||0)/xpNeed(o.l)*100)}%"></i></div><div class="mut">${o.l>=maxL(o)?(o.aw?'Nivel máximo':'Tope de nivel 5: despiértala para llegar a 10'):`${o.xp||0}/${xpNeed(o.l)} XP para el nivel ${o.l+1}`}. Gana XP en el mazo cuando aciertas: +12 por pregunta de ${c.a==='ALL'?'cualquier asignatura':esc(ASIG[c.a].name)}, +4 por las demás (x2 en la asignatura de la semana).</div></div>
 ${o.aw?'<div class="card-box awbox"><b>⭐ Carta despertada</b><div class="mut">+5 a todo y nivel máximo 10.</div></div>':`<div class="card-box awbox"><b>⭐ Despertar</b><div class="mut">${o.l>=5?'✅':'⬜'} Nivel 5 · ${o.n-1>=AWC[c.r]?'✅':'⬜'} ${AWC[c.r]} repetida${AWC[c.r]>1?'s':''} · ${hasMastIn(c.a)?'✅':'⬜'} Maestría 🥉 en un tema de ${c.a==='ALL'?'cualquier asignatura':esc(ASIG[c.a].name)} · ${200*RM[c.r]} 🪙</div><button class="btn gold" style="margin-top:8px" onclick="awaken('${c.id}')" ${o.l>=5&&o.n-1>=AWC[c.r]&&hasMastIn(c.a)&&S.coins>=200*RM[c.r]?'':'disabled'}>⭐ Despertar: +5 a todo y nivel máx. 10</button></div>`}
 <button class="btn ${inDeck?'sec':''}" style="margin-top:12px" id="cd-deck">${inDeck?'Quitar del mazo':'Añadir al mazo'}</button>
 <div class="row" style="margin-top:10px"><button class="btn green" id="cd-up" ${canUp?'':'disabled'}>⬆️ ${o.l<maxL(o)?`Mejorar (${o.l} rep. + ${cost} 🪙)`:'Nivel máximo'}</button><button class="btn green" id="cd-upd" ${o.l<maxL(o)&&S.dust>=UPD[c.r]*o.l?'':'disabled'}>✨ ${o.l<maxL(o)?`Mejorar con ${UPD[c.r]*o.l} polvo`:'Máximo'}</button></div>
 <div class="row" style="margin-top:10px"><button class="btn sec" id="cd-sell" ${extra>0?'':'disabled'}>Vender rep. +${SELL[c.r]} 🪙</button><button class="btn sec" id="cd-rec" ${extra>0?'':'disabled'}>♻️ Reciclar rep. +${DUST[c.r]} ✨</button></div>${c.custom?'':''}`);
 $('#cd-upd').onclick=()=>{const k=UPD[c.r]*o.l;if(o.l>=maxL(o)||S.dust<k)return;S.dust-=k;o.l++;save();sfx('lvl');confetti(40);cardDetail(id);render()};
 $('#cd-rec').onclick=()=>{if(o.n<2)return;o.n--;S.dust+=DUST[c.r];save();sfx('flip');cardDetail(id);render()};
 $('#cd-deck').onclick=()=>{if(inDeck)S.deck=S.deck.filter(x=>x!==id);else if(S.deck.length<3)S.deck.push(id);else{toast('Mazo lleno: quita una carta antes');return}save();cardDetail(id);renderTop()};
 $('#cd-up').onclick=()=>{if(!canUp)return;o.n-=o.l;S.coins-=cost;o.l++;save();sfx('lvl');confetti(40);cardDetail(id);render()};
 $('#cd-sell').onclick=()=>{if(extra<1)return;o.n--;S.coins+=SELL[c.r];save();sfx('flip');cardDetail(id);render()}}

/* ====== MÁS ====== */
VIEWS.more=()=>{V.innerHTML=`<h2>☰ Más</h2>${[['pets','🐾','Mis compis','Mascotas coleccionables que evolucionan contigo'],['diag','🧭','Diagnóstico de estudio','Radar por asignatura, formatos y sesión dirigida'],['pass','🎫','Pase Telecom','30 niveles de recompensas'],['profile','🧑‍🎓','Perfil y títulos','Elige tu título'],['ach','🏅','Logros y colecciones','Desbloquea premios'],['imp','📥','Importar preguntas','Pega aquí lo que te dé Gemini'],['prompt','📋','Prompt para Gemini','Genera el texto para pedir preguntas'],['tables','📊','Formulario y tablas','Erlang, PDH/SDH, bandas, códigos de línea...'],['calc','🧮','Calculadora','Científica, dB, bits, bases y complejos'],['stats','📈','Estadísticas','Aciertos por asignatura y tema'],['road','🏆','Camino de copas','Premios por subir copas'],['backup','💾','Copia de seguridad','Pasa tu progreso del PC al móvil'],['settings','⚙️','Ajustes','Sonido, niveles sin tiempo, borrar']].map(([r,e,t,d])=>`<button class="menu" onclick="${r==='calc'?'openCalc()':`go('${r}')`}"><span>${e}</span><div><b>${t}</b><small>${d}</small></div><i>›</i></button>`).join('')}`};
const back=`<button class="lnk" onclick="go('more')">← Más</button>`;
VIEWS.imp=()=>{V.innerHTML=`${back}<h2>📥 Importar preguntas</h2><div class="mut">Pega la respuesta de Gemini tal cual (el bloque JSON): sirve tanto para preguntas como para cartas. Puedes pegar varios bloques seguidos. Si algo ya existe, se actualiza.</div>
 <textarea id="imp-t" rows="9" placeholder='[{"asig":"RST1","tema":"T1 ...","dif":2,"q":"...","ops":[...],"ok":0,"sol":"...","calc":true,"tabla":null}]'></textarea>
 <button class="btn" onclick="doImport()">Importar</button><div id="imp-r"></div><h3 style="margin-top:22px">Tus preguntas</h3>${manageHTML()}`};
function doImport(){const t=$('#imp-t').value,r=$('#imp-r');if(!t.trim()){r.innerHTML='<div class="err">Pega primero el texto.</div>';return}
 let arr;try{arr=parseImport(t)}catch(e){r.innerHTML=`<div class="err">❌ ${esc(e)}</div>`;return}
 let add=0,upd=0,cAdd=0,cUpd=0;const bad=[],per={};
 arr.forEach((o,i)=>{try{if(isCardObj(o)){addCard(normCard(o))?cAdd++:cUpd++;return}const q=normQ(o),k=S.qs.findIndex(x=>x.id===q.id);if(k>=0){S.qs[k]=q;upd++}else{S.qs.push(q);add++}const key=ASIG[q.asig].name+' · '+q.tema;per[key]=(per[key]||0)+1}catch(e){bad.push(`#${i+1}: ${e}`)}});
 save();r.innerHTML=`${cAdd+cUpd?`<div class="okb">🃏 ${cAdd} cartas nuevas${cUpd?`, ${cUpd} actualizadas`:''}. Ya pueden salir en los sobres.</div>`:''}${add+upd?`<div class="okb">✅ ${add} preguntas nuevas${upd?`, ${upd} actualizadas`:''}<br>${Object.entries(per).map(([k,v])=>`${esc(k)}: ${v}`).join('<br>')}</div>`:''}${bad.length?`<div class="err">⚠️ ${bad.length} descartadas:<br>${bad.slice(0,10).map(esc).join('<br>')}</div>`:''}`;
 if(add||cAdd){$('#imp-t').value='';sfx('ok');confetti(40)}const m=$('#mng');if(m)m.outerHTML=manageHTML()}
function manageHTML(){const rows=ASIGS.map(a=>{const t=temasOf(a.id);if(!t.length)return '';return `<div class="card-box"><b>${a.icon} ${esc(a.name)}</b>${t.map(x=>`<div class="mrow"><span>${esc(x.name)} · ${S.qs.filter(q=>q.asig===a.id&&q.tk===x.tk).length}</span><button class="del" onclick="delTema(this,'${a.id}','${jsq(x.tk)}')">Borrar</button></div>`).join('')}</div>`}).join('');
 const cs=(S.custom||[]);const cards=cs.length?`<div class="card-box"><b>✏️ Cartas creadas (${cs.length})</b>${cs.map(c=>`<div class="mrow"><span>${esc(c.e)} ${esc(c.n)} · ${RN[c.r]} · ${c.a==='ALL'?'Todas':esc(ASIG[c.a].name)}</span><button class="del" onclick="delCard(this,'${c.id}')">Borrar</button></div>`).join('')}</div>`:'';
 return `<div id="mng">${rows||'<div class="mut">No hay preguntas todavía.</div>'}${cards}</div>`}
function delTema(btn,a,tk){if(!btn.dataset.c){btn.dataset.c=1;btn.textContent='¿Seguro?';return}S.qs=S.qs.filter(q=>!(q.asig===a&&q.tk===tk));save();const m=$('#mng');if(m)m.outerHTML=manageHTML();toast('Tema borrado')}

const PG={asig:'RST1',tema:'',files:'',n:25,mode:'q'};
VIEWS.prompt=()=>{V.innerHTML=`${back}<h2>📋 Prompt para Gemini</h2><div class="mut">Elige si quieres preguntas o cartas, rellena los datos, copia el texto y pégalo en Gemini. Después pega su respuesta en Importar. Pide las preguntas de un tema cada vez.</div>
 <div class="chips" style="margin-top:12px">${chip('❓ Preguntas',PG.mode==='q',"PG.mode='q';render()")}${chip('🃏 Cartas',PG.mode==='c',"PG.mode='c';render()")}</div>
 <div class="mut">Asignatura</div><div class="chips">${ASIGS.map(a=>chip(a.icon+' '+esc(a.name),PG.asig===a.id,`PG.asig='${a.id}';render()`)).join('')}</div>
 <div class="${PG.mode==='c'?'hidden':''}"><label class="mut" for="pg-t">Tema: empieza por T1, T2... y usa SIEMPRE el mismo nombre</label><input id="pg-t" value="${esc(PG.tema)}" placeholder="T1 Fundamentos de transmisión" oninput="PG.tema=this.value;updPrompt()">
 <label class="mut" for="pg-f">Archivos del tema (opcional)</label><input id="pg-f" value="${esc(PG.files)}" placeholder="Tema1.pdf y Sol_T1.pdf" oninput="PG.files=this.value;updPrompt()"></div>
 <div class="mut">Cantidad</div><div class="chips">${[10,15,25].map(n=>chip(n+(PG.mode==='c'?' cartas':' preguntas'),PG.n===n,`PG.n=${n};render()`)).join('')}</div>
 <textarea id="pg-out" rows="12" readonly></textarea><button class="btn" onclick="copyPrompt()">📋 Copiar prompt</button>
 <div class="mut" style="margin-top:10px">Si Gemini se corta, pide 10 o 15 de cada vez. Si no sabes los nombres de los temas, pregúntale antes: "¿qué temas hay en la carpeta X?".</div>`;updPrompt()};
function dist(n){return n>=25?[8,8,6,3]:n>=15?[5,5,3,2]:[3,3,3,1]}
function genCardPrompt(){const a=ASIG[PG.asig],n=PG.n,have=CARDS.filter(c=>c.a===a.id).map(c=>c.n);
return `Lee el contenido de mi carpeta "${a.folder}" (${a.full}) de Drive y crea ${n} cartas coleccionables para mi juego de estudio, sobre los conceptos, componentes, técnicas, teoremas y personajes históricos que aparecen en mis apuntes.

REGLAS
- Solo conceptos que aparezcan en mis PDF de esta asignatura.
- Rarezas: Bronce (elementos y conceptos básicos), Plata (técnicas y métodos), Oro (teoremas y conceptos clave) e Icon (personajes históricos relacionados con la asignatura; como mucho 2).
- Reparto aproximado: 40 % Bronce, 30 % Plata, 20 % Oro y 10 % Icon.
- "texto": 1–2 frases sobre el concepto, con su fórmula clave en LaTeX entre $...$ (con las barras dobles: $\\\\frac{a}{b}$). En los Icon, qué aportaron.
- "emoji": un emoji que lo represente.
- "habilidad": solo en los Icon, una de estas: 50/50, congelar, x2, escudo, cambiar, monedas. En las demás, null.
${have.length?`- No repitas estas cartas, que ya existen: ${have.join(', ')}.\n`:''}
FORMATO: responde SOLO con un bloque de código JSON, sin texto antes ni después:
[
{"tipo":"carta","asig":"${a.id}","nombre":"...","emoji":"💡","rareza":"Plata","texto":"...","habilidad":null},
{"tipo":"carta","asig":"${a.id}","nombre":"...","emoji":"🧠","rareza":"Icon","texto":"...","habilidad":"congelar"}
]`}
function genPrompt(){if(PG.mode==='c')return genCardPrompt();const a=ASIG[PG.asig],tema=PG.tema.trim()||'T1 [nombre del tema]',n=PG.n,d=dist(n);
return `Lee a fondo el contenido de este tema de mi Drive (apuntes, relación de ejercicios y soluciones, si las hay) y genera preguntas para mi juego de estudio.

ASIGNATURA: ${a.id} (${a.full}, carpeta "${a.folder}")
TEMA: ${tema}
${PG.files.trim()?`ARCHIVOS: ${PG.files.trim()}\n`:''}CANTIDAD: ${n} preguntas

REGLAS
- Solo contenido de ese tema, con la misma notación y las mismas fórmulas que mis PDF. Nada de otros temas ni asignaturas.
- Reparto: ${d[0]} de dificultad 1 (conceptos), ${d[1]} de dificultad 2 (fórmulas directas), ${d[2]} de dificultad 3 (como los ejercicios de la relación, con otros números) y ${d[3]} de dificultad 4 (tipo examen).
- 4 opciones (o 2 si es Verdadero/Falso). Las incorrectas, del mismo tema y basadas en errores típicos. Solo una correcta.
- Comprueba cada cálculo dos veces con el método de los solucionarios.
- "ok" = posición de la opción correcta, empezando en 0.
- "sol" = solución corta paso a paso.
- "calc" = true si hace falta calculadora.
- "tabla" = si la pregunta necesita datos en forma de tabla, ponlos con el formato del ejemplo; si no, null. Si hace falta un valor de una tabla del PDF (Erlang, transformadas...), dalo en el enunciado.
- Fórmulas en LaTeX entre $...$, con las barras dobles: $\\\\frac{L}{R}$.
- Si hay código, ponlo entre \`\`\` dentro del texto, con \\n para los saltos de línea.
- Usa EXACTAMENTE "asig":"${a.id}" y "tema":"${tema}" en todas.

FORMATO: responde SOLO con un bloque de código JSON, sin texto antes ni después:
[
{"asig":"${a.id}","tema":"${tema}","dif":2,"q":"Enunciado...","ops":["correcta","incorrecta","incorrecta","incorrecta"],"ok":0,"sol":"$t_{tx}=\\\\frac{L}{R}=...$","calc":true,"tabla":null},
{"asig":"${a.id}","tema":"${tema}","dif":3,"q":"Con los datos de la tabla...","ops":["...","...","...","..."],"ok":2,"sol":"...","calc":true,"tabla":{"titulo":"Datos","cols":["Tramo","d (km)","R"],"filas":[["A-B","300","10 Mbps"],["B-C","30","1 Mbps"]]}}
]`}
function updPrompt(){const o=$('#pg-out');if(o)o.value=genPrompt()}
function copyPrompt(){const o=$('#pg-out');copyText(o.value,o)}
function copyText(t,el){const ok=()=>toast('Copiado ✅');try{navigator.clipboard.writeText(t).then(ok).catch(()=>fallback())}catch(e){fallback()}
 function fallback(){try{el.removeAttribute('readonly');el.select();document.execCommand('copy');el.setAttribute('readonly','');ok()}catch(e){toast('Selecciona el texto y cópialo a mano')}}}

/* ====== TABLAS ====== */
function erlangB(c,I){let b=1;for(let n=1;n<=c;n++)b=I*b/(n+I*b);return b}
function erlangC(c,I){if(I>=c)return 1;const b=erlangB(c,I);return c*b/(c-I*(1-b))}
function erlangI(c,B){let lo=0,hi=c*4+20;for(let k=0;k<60;k++){const m=(lo+hi)/2;if(erlangB(c,m)<B)lo=m;else hi=m}return (lo+hi)/2}
const T=(titulo,cols,filas)=>tableHTML({titulo,cols,filas});
VIEWS.tables=()=>{const own={};S.qs.forEach(q=>{if(q.tabla){const k=q.asig+'|'+q.tabla.titulo+'|'+JSON.stringify(q.tabla.filas);own[k]={a:q.asig,t:q.tabla}}});const ownL=Object.values(own);
 V.innerHTML=`${back}<h2>📊 Formulario y tablas</h2>
 <details class="card-box" open><summary><b>☎️ Calculadora Erlang B / C</b></summary><div class="row" style="margin-top:10px"><div><label class="mut" for="er-c">c (servidores)</label><input id="er-c" type="number" min="1" value="5" oninput="erCalc()"></div><div><label class="mut" for="er-i">I (Erlangs)</label><input id="er-i" type="number" step="0.01" value="3" oninput="erCalc()"></div></div><div id="er-r" class="sol"></div></details>
 <details class="card-box"><summary><b>📋 Tabla Erlang-B</b> · tráfico I (E) según c y bloqueo</summary><div style="margin-top:10px">${T('Erlang-B: I ofrecido',['c','1 %','2 %','5 %','10 %'],Array.from({length:20},(_,i)=>[String(i+1),...[.01,.02,.05,.1].map(B=>erlangI(i+1,B).toFixed(2))]))}</div><div class="mut">Calculada con la fórmula exacta. Si tus apuntes usan otra tabla, manda la suya.</div></details>
 <details class="card-box"><summary><b>🏗️ Jerarquías PDH y SDH</b></summary><div style="margin-top:10px">${T('PDH (europea)',['Nivel','R'],[['E1','2,048 Mbps (30 canales de 64 kbps)'],['E2','8,448 Mbps'],['E3','34,368 Mbps'],['E4','139,264 Mbps']])}${T('SDH',['Nivel','R'],[['STM-1','155,52 Mbps'],['STM-4','622,08 Mbps'],['STM-16','2 488,32 Mbps'],['STM-64','9 953,28 Mbps']])}</div></details>
 <details class="card-box"><summary><b>📻 Bandas del espectro</b></summary><div style="margin-top:10px">${T('Bandas (UIT)',['Banda','Rango','Propagación','Usos'],[['MF','300 kHz – 3 MHz','Onda de superficie','Radio AM'],['HF','3 – 30 MHz','Ionosférica','Onda corta, marítimo'],['VHF','30 – 300 MHz','Espacial (LOS)','Radio FM'],['UHF','300 MHz – 3 GHz','Espacial (LOS)','TDT, móviles, WiFi 2,4 GHz'],['SHF','3 – 30 GHz','Espacial (LOS)','Radioenlaces, satélite, WiFi 5 GHz'],['EHF','30 – 300 GHz','LOS (mucha atenuación)','Milimétricas, 5G mmWave']])}</div></details>
 <details class="card-box"><summary><b>〽️ Códigos de línea</b></summary><div style="margin-top:10px">${T('Códigos de línea',['Código','Componente continua','Autosincronizado','1er nulo'],[['NRZ unipolar','Sí','No','R'],['NRZ polar','Sí (si no está equilibrado)','No','R'],['RZ unipolar','Sí','Parcial','2R'],['AMI (bipolar)','No','No (salvo rachas de 1)','R'],['Manchester','No','Sí','2R']])}</div></details>
 <details class="card-box"><summary><b>💥 Acceso al medio</b></summary><div style="margin-top:10px">${T('Técnicas',['Técnica','Throughput','Vulnerable'],[['ALOHA puro','$S=Ge^{-2G}$, máx. 0,184 en G=0,5','$2t_{tx}$'],['ALOHA ranurado','$S=Ge^{-G}$, máx. 0,368 en G=1','$t_{tx}$'],['CSMA','—','$t_{prop}$'],['CSMA/CD','Detecta si $t_{tx}>2t_{prop}$','—'],['Sondeo','$S_{max}=\\frac{t_{tx}}{t_{tx}+\\tau}$','—'],['Reserva','$S_{max}=\\frac{t_{tx}}{t_{tx}+t_{mr}}$','—']])}<div class="mut">Ethernet a 10 Mbps: $L_{min}=64$ B $=512$ bits. Fórmulas sacadas del índice de tus apuntes: compruébalas con las transparencias.</div></div></details>
 <details class="card-box"><summary><b>🧮 Colas M/M/1</b></summary><div class="sol">$\\rho=\\frac{\\lambda}{\\mu}$   $N=\\frac{\\rho}{1-\\rho}$   $Q=\\frac{\\rho^2}{1-\\rho}$\n$T=\\frac{1}{\\mu-\\lambda}$   $W=\\frac{\\rho}{\\mu-\\lambda}$\nLittle: $N=\\lambda T$, $Q=\\lambda W$</div></details>
 ${ownL.length?`<h3>Tablas de tus preguntas</h3>${ownL.map(x=>`<div class="mut">${ASIG[x.a].icon} ${esc(ASIG[x.a].name)}</div>${tableHTML(x.t)}`).join('')}`:''}`;erCalc()};
function erCalc(){const c=parseInt($('#er-c')?.value),I=parseFloat($('#er-i')?.value),r=$('#er-r');if(!r)return;if(!(c>0)||!(I>=0)){r.textContent='Introduce c ≥ 1 e I ≥ 0';return}
 const b=erlangB(c,I);r.textContent=`E_B(${c}; ${I}) = ${b.toFixed(4)}\n`+(I<c?`E_C(${c}; ${I}) = ${erlangC(c,I).toFixed(4)}\nρ = I/c = ${(I/c).toFixed(3)}`:'E_C: el sistema con cola es inestable (I ≥ c)')}

