VIEWS.ach=()=>{const got=ACH.filter(a=>S.ach[a[0]]).length;V.innerHTML=`${back}<h2>🏅 Logros <span class="mut">${got}/${ACH.length}</span></h2><div class="card-box">${ACH.map(([id,e,n,d,,rw])=>`<div class="ach ${S.ach[id]?'':'no'}"><span>${e}</span><div><b>${n}</b><small>${d}</small></div><small>${S.ach[id]?'✅':'+'+rw+' 🪙'}</small></div>`).join('')}</div>
 <h3>📖 Colecciones</h3><div class="card-box">${ASIGS.map(a=>{const cs=CARDS.filter(c=>c.a===a.id),o=cs.filter(c=>S.cards[c.id]).length;return `<div class="srow"><span>${a.icon} ${esc(a.name)}</span><div class="sbar"><i style="width:${cs.length?o/cs.length*100:0}%;background:${S.sets[a.id]?'#fbbf24':'#7c5cff'}"></i></div><small>${o}/${cs.length}</small></div>`}).join('')}<div class="mut" style="margin-top:6px">Completa la colección de una asignatura → 300 🪙 + ✨ Sobre Premium</div></div>
 <h3>🏅 Récords</h3><div class="grid2">${sbox('Supervivencia',S.rec.surv)}${sbox('Contrarreloj',S.rec.blitz)}${sbox('Mejor combo',S.bestCombo)}${sbox('Aciertos totales',S.totC)}</div>`};

/* ====== ESTADÍSTICAS ====== */
const pctTxt=(c,w)=>c+w?Math.round(c/(c+w)*100)+' %':'—';
const pctCol=(c,w)=>{const p=c+w?c/(c+w):0;return p>=.75?'#22c55e':p>=.5?'#facc15':'#ef4444'};
VIEWS.stats=()=>{const weak=[];let tc=0,tw=0;
 const blocks=ASIGS.map(a=>{const qs=S.qs.filter(q=>q.asig===a.id);if(!qs.length)return '';let c=0,w=0;
  const rows=temasOf(a.id).map(t=>{let x=0,y=0;qs.filter(q=>q.tk===t.tk).forEach(q=>{const s=S.st[q.id];if(s){x+=s.c;y+=s.w}});c+=x;w+=y;if(x+y>=5)weak.push({a,t,p:x/(x+y)});
   return `<button class="srow srb" onclick="startReview('${a.id}','${jsq(t.tk)}')" title="Repasar este tema"><span>${mastE(a.id,t.tk)} ${esc(t.name)}</span><div class="sbar"><i style="width:${x+y?x/(x+y)*100:0}%;background:${pctCol(x,y)}"></i></div><small>${pctTxt(x,y)}</small></button>`}).join('');tc+=c;tw+=w;
  return `<div class="card-box"><div class="rowb"><b>${a.icon} ${esc(a.name)}</b><span>${pctTxt(c,w)}</span></div>${rows}<div class="mut" style="font-size:11px;margin-top:4px">Toca un tema para repasarlo.</div></div>`}).join('');
 weak.sort((x,y)=>x.p-y.p);
 V.innerHTML=`${back}<h2>📈 Estadísticas</h2><div class="grid2" style="margin-bottom:12px">${sbox('Partidas',S.matches)}${sbox('Victorias',S.wins)}${sbox('Respuestas correctas',tc)}${sbox('Acierto total',pctTxt(tc,tw))}</div>
 <button class="btn green big" style="margin-bottom:12px" onclick="startSmartReview()">🩺 Repaso inteligente</button><div class="mut" style="margin:-4px 0 12px">Sin tiempo, con soluciones, centrado en tus 3 temas con peor porcentaje y en las preguntas que fallas.</div>
 ${weak.length?`<div class="card-box"><b>⚠️ Tus temas más flojos</b>${weak.slice(0,5).map(x=>`<div class="mrow"><span>${x.a.icon} ${esc(x.t.name)} · ${Math.round(x.p*100)} %</span><button class="btn sm" onclick="startReview('${x.a.id}','${jsq(x.t.tk)}')">🩺 Repasar</button></div>`).join('')}</div>`:''}
 ${blocks||'<div class="mut">Juega unas partidas para ver tus estadísticas.</div>'}`};

/* ====== CAMINO DE COPAS ====== */
const roadRw=m=>m%500===0?{t:'👑 Sobre ICON',k:'icon'}:m%200===0?{t:'✨ Sobre Premium',k:'premium'}:{t:'🪙 200 monedas',k:'coins'};
VIEWS.road=()=>{const ms=[];for(let m=100;m<=2000;m+=100)ms.push(m);
 V.innerHTML=`${back}<h2>🏆 Camino de copas</h2><div class="mut" style="margin-bottom:12px">Récord: ${S.maxTrophies} copas. Los premios se quedan aunque luego pierdas copas.</div>${ms.map(m=>{const rw=roadRw(m),got=S.road.includes(m),can=S.maxTrophies>=m;return `<div class="road ${got?'got':can?'can':''}"><b>🏆 ${m}</b><span>${rw.t}${m===LEAGUES.find(l=>l.min===m)?.min?` · ${LEAGUES.find(l=>l.min===m).e} liga`:''}</span>${got?'✅':can?`<button class="btn gold sm" onclick="claimRoad(${m})">Reclamar</button>`:'🔒'}</div>`}).join('')}`};
function claimRoad(m){if(S.road.includes(m)||S.maxTrophies<m)return;S.road.push(m);const rw=roadRw(m);
 if(rw.k==='coins'){S.coins+=200;save();toast('+200 🪙');sfx('gold');render()}else if(rw.k==='icon'){S.iconPacks++;save();toast('👑 Sobre ICON añadido a Sobres');sfx('icon');render()}else{save();openPack('premium',true)}}

/* ====== COPIA Y AJUSTES ====== */
VIEWS.backup=()=>{V.innerHTML=`${back}<h2>💾 Copia de seguridad</h2><div class="mut">Tu progreso se guarda solo en este navegador. Para pasarlo a otro dispositivo, copia el texto aquí y pégalo allí en "Restaurar".</div>
 <button class="btn" style="margin-top:12px" onclick="expBackup()">📤 Generar y copiar copia</button><textarea id="bk" rows="7" placeholder="Aquí aparece tu copia (o pega una para restaurar)"></textarea><button class="btn sec" onclick="impBackup()">📥 Restaurar desde el texto</button>`};
function expBackup(){const t=JSON.stringify(S),el=$('#bk');el.value=t;copyText(t,el)}
function impBackup(){try{const o=JSON.parse($('#bk').value);if(typeof o.coins!=='number'||!Array.isArray(o.qs))throw 0;S=Object.assign(defState(),o);refreshCards();save();toast('Progreso restaurado ✅');go('home')}catch(e){toast('Ese texto no es una copia válida')}}
VIEWS.settings=()=>{V.innerHTML=`${back}<h2>⚙️ Ajustes</h2>
 <label class="tog"><input type="checkbox" ${S.sound?'checked':''} onchange="S.sound=this.checked;save()"> Sonido</label>
 <label class="tog"><input type="checkbox" ${S.lvNoTimer?'checked':''} onchange="S.lvNoTimer=this.checked;save()"> Niveles y jefes sin tiempo</label>
 <div class="card-box"><b>Reiniciar progreso</b><div class="mut">Borra monedas, copas, cartas y estadísticas. Tus preguntas se quedan.</div><button class="del" style="margin-top:10px" onclick="resetAll(this,false)">Reiniciar progreso</button></div>
 <div class="card-box"><b>Borrar TODO</b><div class="mut">Incluidas las preguntas importadas.</div><button class="del" style="margin-top:10px" onclick="resetAll(this,true)">Borrar todo</button></div>`};
function resetAll(btn,all){if(!btn.dataset.c){btn.dataset.c=1;btn.textContent='Pulsa otra vez para confirmar';return}const qs=S.qs;S=defState();if(!all){S.qs=qs;S.seeded=true}save();init();toast('Hecho');go('home')}

let pwaInstallPrompt=null;
const TL_settingsPwa=VIEWS.settings;
VIEWS.settings=function(){TL_settingsPwa();const box=document.createElement('section');box.className='card-box';box.innerHTML=`<b>📲 Instalar y jugar sin conexión</b><div class="mut" style="margin-top:6px">En iPhone: sirve la carpeta desde HTTPS, abre esta página en Safari, toca Compartir y elige «Añadir a pantalla de inicio». En PC: usa «Instalar» cuando el navegador lo ofrezca. La primera visita requiere conexión; después se conserva la aplicación para abrirla sin red.</div><button class="btn sec" id="pwaInstall" style="margin-top:10px" ${pwaInstallPrompt?'':'hidden'} onclick="installPwa()">Instalar aplicación</button>`;V.appendChild(box)};
async function installPwa(){if(!pwaInstallPrompt){toast('En iPhone: Safari → Compartir → Añadir a pantalla de inicio.');return}const prompt=pwaInstallPrompt;pwaInstallPrompt=null;try{await prompt.prompt();const result=await prompt.userChoice;toast(result.outcome==='accepted'?'Instalación iniciada':'Puedes instalarla más tarde.')}catch(e){console.error('No se pudo iniciar la instalación PWA',e);toast('El navegador no pudo iniciar la instalación.')}const b=$('#pwaInstall');if(b)b.hidden=true}
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();pwaInstallPrompt=e;const b=$('#pwaInstall');if(b)b.hidden=false});
window.addEventListener('appinstalled',()=>{pwaInstallPrompt=null;const b=$('#pwaInstall');if(b)b.hidden=true;toast('Telecom Legends está instalada ✅')});
let hadServiceWorkerController=!!(navigator.serviceWorker&&navigator.serviceWorker.controller);
function showSwUpdate(){
 if(document.querySelector('.sw-update'))return;
 const button=document.createElement('button');button.type='button';button.className='sw-update';button.textContent='Nueva versión disponible · Actualizar';
 button.addEventListener('click',()=>location.reload());document.body.appendChild(button)
}
if('serviceWorker'in navigator)navigator.serviceWorker.addEventListener('controllerchange',()=>{
 if(hadServiceWorkerController)showSwUpdate();else hadServiceWorkerController=true
});
function registerPwa(){if(!('serviceWorker'in navigator)||!/^https?:$/.test(location.protocol))return;navigator.serviceWorker.register('./sw.js').catch(e=>{console.error('No se pudo registrar el service worker',e)})}
window.addEventListener('load',registerPwa,{once:true});

/* ====== CALCULADORA ====== */
let CT=[],ANS=0,cJust=false,cTab='sci';
const KEYS=[[['C','clr'],['⌫','del'],['(','open'],[')','close'],['ANS','const','ANS'],['÷','op','/']],
 [['7','num'],['8','num'],['9','num'],['xʸ','op','**','^'],['√','fn','Math.sqrt(','√('],['×','op','*']],
 [['4','num'],['5','num'],['6','num'],['ln','fn','Math.log(','ln('],['log','fn','Math.log10(','log('],['−','op','-']],
 [['1','num'],['2','num'],['3','num'],['eˣ','fn','Math.exp(','e^('],['10ˣ','fn','10**(','10^('],['+','op','+']],
 [['0','num'],['.','num'],['EXP','exp','*10**','ᴇ'],['π','const','Math.PI'],['n!','fn','fact(','fact('],['mod','op','%',' mod ']],
 [['p','pre','*1e-12'],['k','pre','*1e3'],['M','pre','*1e6'],['G','pre','*1e9'],['m','pre','*1e-3'],['µ','pre','*1e-6']],
 [['sin','fn','sin(','sin('],['cos','fn','cos(','cos('],['tan','fn','tan(','tan('],['e','const','Math.E'],['n','pre','*1e-9']]];
function fact(n){if(n<0||n%1||n>170)return NaN;let r=1;for(let i=2;i<=n;i++)r*=i;return r}
function cPress(i,j){const [lab,kind,js,disp]=KEYS[i][j];vib(12);
 if(kind==='clr'){CT=[];cJust=false;return cUpd()}if(kind==='del'){CT.pop();cJust=false;return cUpd()}
 if(cJust){CT=['op','pre','exp'].includes(kind)?[{k:'const',j:'ANS',d:'ANS'}]:[];cJust=false}
 const tok={k:kind,j:js??lab,d:disp??lab},prev=CT[CT.length-1];
 const ends=t=>t&&['num','close','const','pre'].includes(t.k),starts=t=>['num','open','fn','const'].includes(t.k);
 if(ends(prev)&&starts(tok)&&!(prev.k==='num'&&tok.k==='num'))CT.push({k:'op',j:'*',d:''});CT.push(tok);cUpd()}
function cEval(){try{const result=calcParse(CT.map(t=>t.d).join(''));return result?result.v:null}catch(e){return NaN}}
function fmtN(v){if(v===0)return '0';const a=Math.abs(v);if(a>=1e9||a<1e-4)return v.toExponential(6).replace(/\.?0+e/,'e').replace('e+','·10^').replace('e','·10^');return String(parseFloat(v.toPrecision(10)))}
function engStr(v){const a=Math.abs(v);if(!a||a>=1e12||a<1e-12||(a>=1&&a<1000))return '';const P=[[1e9,'G'],[1e6,'M'],[1e3,'k'],[1,''],[1e-3,'m'],[1e-6,'µ'],[1e-9,'n'],[1e-12,'p']];const p=P.find(x=>a>=x[0]);return p&&p[1]?`  (${parseFloat((v/p[0]).toPrecision(5))} ${p[1]})`:''}
function cEq(){const v=cEval();if(v==null)return;if(Number.isFinite(v)){ANS=v;cJust=true}cUpd(true)}
function cUpd(fin){const e=$('#c-expr'),r=$('#c-res');if(!e)return;e.textContent=CT.map(t=>t.d).join('')||'0';const v=cEval();r.className='cres'+(fin?'':' prev');r.textContent=v==null?'':Number.isFinite(v)?'= '+fmtN(v)+engStr(v):'Error'}
function openCalc(){calcOpen=true;if(M)M.calcI=M.i;$('#calc').classList.remove('hidden');drawCalc()}
function closeCalc(){calcOpen=false;const c=$('#calc');if(c)c.classList.add('hidden')}
const inp=(id,l,f,ph='')=>`<div><label class="mut" for="${id}">${l}</label><input id="${id}" inputmode="decimal" placeholder="${ph}" oninput="${f}"></div>`;
function drawCalc(){const kc={op:'k-op',fn:'k-fn',pre:'k-pre',clr:'k-clr',del:'k-clr',exp:'k-fn'};let body='';
 if(cTab==='sci')body=`<div class="cdisp"><div class="cexpr" id="c-expr"></div><div class="cres" id="c-res"></div></div><div class="ckeys">${KEYS.map((row,i)=>row.map((k,j)=>`<button class="${kc[k[1]]||''}" onclick="cPress(${i},${j})">${k[0]}</button>`).join('')).join('')}<button class="eq" onclick="cEq()">=</button></div><div class="mut" style="margin-top:6px">Ejemplo: 3 EXP −6 = 3·10⁻⁶. Prefijos: 5 µ = 5·10⁻⁶.</div>`;
 else if(cTab==='db')body=`<div class="conv">${inp('db-db','dB',"conv('db',this.value)",'30')}${inp('db-p','Veces (potencia) = 10^(dB/10)',"conv('p',this.value)")}${inp('db-v','Veces (tensión) = 10^(dB/20)',"conv('v',this.value)")}</div>`;
 else if(cTab==='bits')body=`<div class="conv">${inp('b-b','bits',"conv('bit',this.value)")}${inp('b-B','bytes',"conv('B',this.value)")}<div class="mut">1 byte = 8 bits. Ojo con k = 1000 o 1024 según tus apuntes.</div></div>`;
 else if(cTab==='base')body=`<div class="conv">${['dec','bin','hex','oct'].map(b=>`<div><label class="mut" for="bs-${b}">${{dec:'Decimal',bin:'Binario',hex:'Hexadecimal',oct:'Octal'}[b]}</label><input id="bs-${b}" autocapitalize="off" oninput="convBase('${b}',this.value)"></div>`).join('')}</div>`;
 else body=`<div class="conv"><div class="mut">Binómica a + jb</div><div class="row">${inp('c-a','a',"conv('ca')")}${inp('c-b','b',"conv('ca')")}</div><div class="mut">Polar r∠θ</div><div class="row">${inp('c-r','r (módulo)',"conv('cr')")}${inp('c-d','θ (grados)',"conv('cr')")}</div><div class="mut">θ en radianes: <b id="c-rad">—</b></div></div>`;
 $('#calc').innerHTML=`<div class="chead"><div class="ctabs">${[['sci','🧮 Científica'],['db','dB'],['bits','bits'],['base','BIN/HEX'],['cplx','Complejos']].map(([k,l])=>`<button class="${cTab===k?'on':''}" onclick="cTab='${k}';drawCalc()">${l}</button>`).join('')}</div><button class="cx" onclick="closeCalc()" aria-label="Cerrar">✕</button></div>${body}${M&&route==='play'&&!M.noTimer?'<div class="mut" style="text-align:center;margin-top:6px">⏳ El tiempo corre a la mitad con la calculadora abierta</div>':''}`;if(cTab==='sci')cUpd()}
function num(id){const e=$('#'+id);return e?parseFloat(String(e.value).replace(',','.')):NaN}
function conv(f,v){const x=parseFloat(String(v??'').replace(',','.'));const set=(id,val)=>{const e=$('#'+id);if(e&&document.activeElement!==e){if(e.tagName==='INPUT')e.value=val;else e.textContent=val}};const F=n=>Number.isFinite(n)?String(parseFloat(n.toPrecision(8))):'';
 if(f==='db'){set('db-p',F(10**(x/10)));set('db-v',F(10**(x/20)))}else if(f==='p'){set('db-db',F(10*Math.log10(x)));set('db-v',F(Math.sqrt(x)))}else if(f==='v'){set('db-db',F(20*Math.log10(x)));set('db-p',F(x*x))}
 else if(f==='bit')set('b-B',F(x/8));else if(f==='B')set('b-b',F(x*8));
 else if(f==='ca'){const a=num('c-a')||0,b=num('c-b')||0,t=Math.atan2(b,a);set('c-r',F(Math.hypot(a,b)));set('c-d',F(t*180/Math.PI));set('c-rad',F(t))}
 else if(f==='cr'){const r=num('c-r')||0,t=(num('c-d')||0)*Math.PI/180;set('c-a',F(r*Math.cos(t)));set('c-b',F(r*Math.sin(t)));set('c-rad',F(t))}}
function convBase(from,v){v=String(v).trim().toLowerCase();const set=(id,val)=>{const e=$('#'+id);if(e&&document.activeElement!==e)e.value=val};let n=null;
 try{if(v!==''){const neg=v.startsWith('-'),body=v.replace(/^-/,'').replace(/^0[bxo]/,'');n=BigInt(from==='dec'?body:{bin:'0b',hex:'0x',oct:'0o'}[from]+body);if(neg)n=-n}}catch(e){n=null}
 const others=['dec','bin','hex','oct'].filter(x=>x!==from);if(n===null){others.forEach(x=>set('bs-'+x,''));return}
 set('bs-dec',n.toString(10));set('bs-bin',n.toString(2));set('bs-hex',n.toString(16).toUpperCase());set('bs-oct',n.toString(8))}

/* ====== MODAL, TOAST, SONIDO, CONFETI ====== */
function modal(html,lock){const m=$('#modal');m.innerHTML=`<div class="mbox">${lock?'':'<button class="mx" onclick="closeModal()" aria-label="Cerrar">✕</button>'}${html}</div>`;m.classList.remove('hidden');m.onclick=e=>{if(!lock&&e.target===m)closeModal()};math(m)}
function closeModal(){const m=$('#modal');m.classList.add('hidden');m.innerHTML='';if(CQ.length)setTimeout(()=>{if($('#modal').classList.contains('hidden'))nextCele()},250)}
let TT;function toast(t){const e=$('#toast');e.textContent=t;e.classList.add('show');clearTimeout(TT);TT=setTimeout(()=>e.classList.remove('show'),2600)}
let AC=null;function ac(){const C=window.AudioContext||window.webkitAudioContext;if(!C)return null;if(!AC)AC=new C();if(AC.state==='suspended')AC.resume().catch(e=>console.warn('No se pudo reanudar el audio:',e));return AC}
function tone(f,d,t='sine',del=0,vol=.15){const a=ac();if(!a)return;const o=a.createOscillator(),g=a.createGain(),s=a.currentTime+del;o.type=t;o.frequency.value=f;g.gain.setValueAtTime(0,s);g.gain.linearRampToValueAtTime(vol,s+.01);g.gain.exponentialRampToValueAtTime(.0001,s+d);o.connect(g).connect(a.destination);o.start(s);o.stop(s+d+.03)}
const SFX={ok:(combo=0)=>{const f=660+Math.min(combo,14)*16;tone(f,.1,'triangle');tone(f+330,.16,'triangle',.09)},bad:()=>tone(170,.28,'sawtooth',0,.07),flip:()=>tone(520,.08,'square',0,.05),gold:()=>[523,784,1047].forEach((f,i)=>tone(f,.22,'triangle',i*.08)),icon:()=>[392,523,659,784,1047,1319].forEach((f,i)=>tone(f,.4,'triangle',i*.09,.17)),power:()=>{tone(400,.1,'square',0,.05);tone(800,.15,'square',.08,.05)},shield:()=>tone(300,.22,'triangle'),lvl:()=>[523,659,784,1047].forEach((f,i)=>tone(f,.25,'triangle',i*.1))};
SFX.click=()=>tone(800,.015,'sine',0,.045);
SFX.success=combo=>{const n=Math.min(10,Math.max(0,Number(combo)||0)),base=600+n*34;tone(base,.11,'triangle',0,.08);tone(base+220,.14,'sine',.075,.07)};
SFX.error=()=>{tone(220,.15,'sawtooth',0,.05);tone(145,.2,'triangle',.1,.07)};
SFX.overclock=()=>{const a=ac();if(!a)return;const o=a.createOscillator(),g=a.createGain(),t=a.currentTime;o.type='sawtooth';o.frequency.setValueAtTime(220,t);o.frequency.exponentialRampToValueAtTime(1320,t+.38);g.gain.setValueAtTime(.0001,t);g.gain.linearRampToValueAtTime(.07,t+.04);g.gain.exponentialRampToValueAtTime(.0001,t+.48);o.connect(g).connect(a.destination);o.start(t);o.stop(t+.5)};
SFX.cardFlip=rarity=>{const level={B:0,P:1,O:2,I:3,M:3,C:4,T:4}[rarity]||0,base=420+level*115;tone(base,.09,'triangle',0,.06);if(level>=2)tone(base*1.5,.16,'sine',.07,.08)};
function sfx(k,...args){if(!S.sound)return;const play=SFX[k];if(play)play(...args)}
function toggleSound(){S.sound=!S.sound;save();renderTop();if(S.sound)sfx('click');toast(S.sound?'Sonido activado 🔊':'Sonido silenciado 🔇')}
document.addEventListener('pointerdown',e=>{if(e.target.closest&&e.target.closest('button'))sfx('click')},{passive:true});
function vib(p){if(navigator.vibrate)navigator.vibrate(p)}
function confetti(n=60,cols=['#7c5cff','#22d3ee','#fbbf24','#22c55e','#ef4444','#ec4899']){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;for(let i=0;i<n;i++){const e=document.createElement('i');e.className='conf';e.style.left=Math.random()*100+'vw';e.style.background=rnd(cols);e.style.animationDuration=(1.6+Math.random()*1.6)+'s';e.style.animationDelay=Math.random()*.3+'s';document.body.appendChild(e);setTimeout(()=>e.remove(),3800)}}
function flash(){const e=document.createElement('div');e.className='flash';document.body.appendChild(e);setTimeout(()=>e.remove(),750)}

/* ====== TILT 3D ====== */
let TG=null;const RM_MOT=matchMedia('(prefers-reduced-motion: reduce)').matches;
function tiltReset(g){if(!g)return;g.style.setProperty('--rx','0deg');g.style.setProperty('--ry','0deg');g.style.setProperty('--go','0')}
function tiltMove(e){if(RM_MOT)return;const g=e.target&&e.target.closest?e.target.closest('.gcard:not(.locked)'):null;if(TG&&TG!==g)tiltReset(TG);TG=g;if(!g)return;const r=g.getBoundingClientRect(),x=Math.min(1,Math.max(0,(e.clientX-r.left)/r.width)),y=Math.min(1,Math.max(0,(e.clientY-r.top)/r.height)),k=g.classList.contains('r-I')||g.classList.contains('r-O')?18:10;
 g.style.setProperty('--ry',((x-.5)*k).toFixed(1)+'deg');g.style.setProperty('--rx',((.5-y)*k).toFixed(1)+'deg');g.style.setProperty('--mx',(x*100).toFixed(0)+'%');g.style.setProperty('--my',(y*100).toFixed(0)+'%');g.style.setProperty('--go',g.classList.contains('r-B')?'.45':'1')}
document.addEventListener('pointermove',tiltMove,{passive:true});document.addEventListener('pointerdown',tiltMove,{passive:true});
['pointerup','pointercancel'].forEach(ev=>document.addEventListener(ev,e=>{if(TG&&e.pointerType!=='mouse'){const g=TG;TG=null;setTimeout(()=>tiltReset(g),250)}},{passive:true}));

/* ====== ARRANQUE ====== */
document.addEventListener('keydown',e=>{if(route!=='play'||!M||calcOpen||e.ctrlKey||e.metaKey||e.altKey)return;const tag=e.target&&e.target.tagName;if(tag==='INPUT'||tag==='TEXTAREA'||tag==='SELECT')return;if(M.ans===null&&/^[1-4a-dA-D]$/.test(e.key)){const idx=/^[1-4]$/.test(e.key)?+e.key-1:e.key.toUpperCase().charCodeAt(0)-65;const k=M.qs[M.i].order[idx];if(k!=null&&!M.hidden.has(k))answer(k)}else if(M.ans!==null&&e.key==='Enter'){const b=$('#fb .btn');if(b)b.click()}});
function mergeBank(){if((S.bankV||0)<BANK_V){const ids=new Set(S.qs.map(q=>q.id));let n=0;BANK.concat(BANK_EXTRA).forEach(o=>{try{const q=normQ(o);if(!ids.has(q.id)){ids.add(q.id);S.qs.push(q);n++}}catch(e){console.error('No se pudo añadir una pregunta del banco',e,o)}});S.bankV=BANK_V;save();if(n)setTimeout(()=>toast(`📚 ${n} preguntas nuevas de tus temarios`),2500)}}
