 if(ask==='d2h'){const {ops,why}=mk(h,[[h.split('').reverse().join(''),'dígitos al revés'],[n.toString(8),'eso es octal'],[(n+16).toString(16).toUpperCase(),'cociente mal'],[String(n%16)+String(Math.floor(n/16)),'orden de cociente y resto cambiado']],x=>x);return{q:`${n} en hexadecimal:`,ops,chk:[true],sol:`${n} = ${Math.floor(n/16)}·16 + ${n%16} → ${h}.`+whyTxt(why)}}
 const {ops,why}=mk(n,[[parseInt(h.split('').reverse().join(''),16),'lees las cifras al revés'],[parseInt(h,8)||null,'interpretas los dígitos en base 8'],[Math.floor(n/16)*10+n%16,'interpretas el número como si fuera decimal'],[n+16,'error de peso']],x=>String(x));
