/* =====================================================================
   v5 · UTILIDADES: semillas reproducibles y muestreo ponderado
   ===================================================================== */
function mulberry32(a){return function(){a|=0;a=a+0x6D2B79F5|0;let t=Math.imul(a^a>>>15,1|a);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296}}
function hashStr(s){let h=1779033703^s.length;for(let i=0;i<s.length;i++){h=Math.imul(h^s.charCodeAt(i),3432918353);h=h<<13|h>>>19}return h>>>0}
/* Ejecuta fn con Math.random sustituido por un generador sembrado: misma semilla + misma clave = mismo resultado */
function seeded(key,fn){const r=S.run;if(!r||!r.seed)return fn();const R=Math.random;Math.random=mulberry32(hashStr(r.seed+'|'+key));try{return fn()}finally{Math.random=R}}
const SEED_AB='ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
const newSeed=()=>Array.from({length:8},()=>SEED_AB[Math.floor(Math.random()*SEED_AB.length)]).join('');
const normSeed=s=>String(s||'').toUpperCase().replace(/[^A-Z0-9]/g,'').slice(0,16);
function wsample(arr,wf,n){const pool=arr.slice(),out=[];while(pool.length&&out.length<n){const ws=pool.map(wf),tot=ws.reduce((a,b)=>a+Math.max(0,b),0);let x=Math.random()*tot,i=0;for(;i<pool.length-1;i++){x-=Math.max(0,ws[i]);if(x<=0)break}out.push(pool.splice(i,1)[0])}return out}
function copyTxt(t){const ok=()=>toast('📋 Copiado: '+t);if(navigator.clipboard&&navigator.clipboard.writeText)navigator.clipboard.writeText(t).then(ok).catch(()=>window.prompt('Copia la semilla:',t));else window.prompt('Copia la semilla:',t)}
const cutTxt=(s,n)=>{s=String(s||'');if(s.length<=n)return s;let c=s.slice(0,n);if((c.match(/\$/g)||[]).length%2)c=c.slice(0,c.lastIndexOf('$'));if((c.match(/```/g)||[]).length%2)c=c.slice(0,c.lastIndexOf('```'));return c+'…'};

/* =====================================================================
   v5 · 5) DIRECTOR DE ESTUDIO: formatos, debilidades y selector ponderado
   ===================================================================== */
const FMTS=['concept','calc','tabla','code'],FMT_N={concept:'Concepto',calc:'Cálculo',tabla:'Tabla',code:'Código'},FMT_E={concept:'💡',calc:'🧮',tabla:'📊',code:'💻'},FMT_T={concept:.4,calc:.3,tabla:.15,code:.15};
const fmtOf=q=>q.tabla?'tabla':isCode(q)?'code':q.calc?'calc':'concept';
function fmtPush(q){const h=S.fmtH||(S.fmtH=[]);h.push(fmtOf(q));if(h.length>30)h.splice(0,h.length-30)}
function fmtShare(){const h=S.fmtH||[],c={concept:0,calc:0,tabla:0,code:0};h.forEach(f=>{if(f in c)c[f]++});const n=h.length||1;FMTS.forEach(f=>c[f]/=n);return c}
function fstBump(q,good){const f=fmtOf(q),s=S.fst||(S.fst={}),x=s[f]||(s[f]={c:0,w:0});good?x.c++:x.w++}
/* debilidad de un tema: acierto suavizado + maestría (más alto = más flojo) */
function weakOf(a,tk){const [c,w]=temaCW(a,tk),p=(c+1)/(c+w+2);return (1-p)*4+(3-(S.mast[a+'|'+tk]||0))*.5+(c+w===0?.6:0)}
function weakList(asig){const out=[];ASIGS.forEach(A=>{if(asig&&asig!=='ALL'&&A.id!==asig)return;temasOf(A.id).forEach(t=>{const [c,w]=temaCW(A.id,t.tk);out.push({a:A.id,tk:t.tk,name:t.name,c,w,p:c+w?c/(c+w):null,wk:weakOf(A.id,t.tk)})})});return out.sort((x,y)=>y.wk-x.wk)}
function weakKey(asig){const l=weakList(asig).filter(x=>x.c+x.w>0);const src=l.length?l.slice(0,3):weakList(asig);const x=src.length?pk(src):null;return x?x.a+'|'+x.tk:null}
/* Selector ponderado: menor puntuación = sale antes */
pickQs=function(pred,n,difs){const base=S.qs.filter(pred),qc=S.qc||0,ls=S.ls||{},sh=fmtShare(),cache=new Map(),fm=new Set(base.map(fmtOf));
 const W=(a,tk)=>{const k=a+'|'+tk;if(!cache.has(k))cache.set(k,weakOf(a,tk));return cache.get(k)};
 const w=q=>{const s=S.st[q.id]||{c:0,w:0},rec=qc-(ls[q.id]??-1e9);let v=s.c-2*s.w+(s.l===0?-2:0)-W(q.asig,q.tk)*1.1+Math.random()*2.5+(rec<60?8-rec/10:0);if(fm.size>1){const f=fmtOf(q);v-=(FMT_T[f]-sh[f])*6}return v};
 const prim=base.filter(q=>difs.includes(q.dif)).map(q=>[w(q),q]).sort((a,b)=>a[0]-b[0]).map(x=>x[1]);
 const dist=d=>Math.min(...difs.map(x=>Math.abs(x-d)));
 const sec=shuffle(base.filter(q=>!difs.includes(q.dif))).sort((a,b)=>dist(a.dif)-dist(b.dif));
 let res=prim.concat(sec).slice(0,n);const gc=genCands(pred,difs.length?difs:[1,2,3,4]);
 if(gc.length){const pg=()=>wsample(gc,g=>1+W(g.a,temaKey(g.t))+(g.gx?.6:0),1)[0];const fresh=base.filter(q=>difs.includes(q.dif)&&(qc-(ls[q.id]??-1e9))>=60).length,gp=fresh>=n*2?.25:.5;
  res=res.map(q=>Math.random()<gp?(makeGen(pg())||q):q);let g=0;while(res.length<n&&g++<n*3){const x=makeGen(pg());if(x)res.push(x)}}
 return shuffle(res)};
trackGood=function(q){const nc=q.calc&&M.calcI!==M.i;if(nc){trk('nocalc');prog('nocalc',1)}if(q.tabla){trk('tabla');prog('tabla',1)}if(isCode(q)){trk('code');prog('code',1)}
 if(q.dif>=4)trk('d4');if((M.mode==='fails'||M.mode==='review')&&!M.directed){trk('fix');prog('fixfail',1)}if(q.asig===weekAsig())prog('wasig',1);if(q.gx){trk('gx');prog('gx',1)}fstBump(q,true)};
function trackBad(q){fstBump(q,false);const rf=S.rf||(S.rf=[]);rf.push({a:q.asig,tk:q.tk,tema:q.tema,q:cutTxt(q.q,150),ok:cutTxt(q.ops[q.ok],90),sol:cutTxt(String(q.sol||'').split('\n')[0],220),t:Date.now()});if(rf.length>30)rf.splice(0,rf.length-30)}
function startDirected(){const qs=pickQs(()=>true,12,[1,2,3,4]);if(!qs.length){toast('No hay preguntas todavía');return}startMatch({mode:'review',directed:true,asig:'ALL',qs,noTimer:true});toast('🧭 Sesión dirigida: tus temas flojos y formatos que te faltan')}
function v5End(){if(!M)return;if(M.directed){trk('dir');prog('dir',1)}if(M.bonus&&M.bonus.syn&&M.bonus.syn.length>=2&&M.correct>0)prog('syn',1)}

/* ---------- Panel «Diagnóstico de estudio» (SVG puro) ---------- */
function radarSVG(vals){const n=vals.length,cx=150,cy=135,R=100,pt=(i,r)=>{const a=-Math.PI/2+i*2*Math.PI/n;return [cx+r*Math.cos(a),cy+r*Math.sin(a)]};
 const grid=[.25,.5,.75,1].map(k=>`<polygon points="${vals.map((_,i)=>pt(i,R*k).join(',')).join(' ')}" class="rg"/>`).join('');
 const axes=vals.map((v,i)=>{const [x,y]=pt(i,R),[lx,ly]=pt(i,R+20);return `<line x1="${cx}" y1="${cy}" x2="${x}" y2="${y}" class="ra"/><text x="${lx}" y="${ly}" class="rl" dy=".35em">${v.icon}</text>`}).join('');
 const poly=vals.map((v,i)=>pt(i,R*(v.p==null?0:Math.max(.04,v.p))).join(',')).join(' ');
 const dots=vals.map((v,i)=>v.p==null?'':`<circle cx="${pt(i,R*Math.max(.04,v.p))[0]}" cy="${pt(i,R*Math.max(.04,v.p))[1]}" r="4" fill="${v.col}"><title>${esc(v.name)}: ${Math.round(v.p*100)} %</title></circle>`).join('');
 return `<svg viewBox="0 0 300 270" class="radar" role="img" aria-label="Acierto por asignatura">${grid}${axes}<polygon points="${poly}" class="rp"/>${dots}</svg>`}
VIEWS.diag=()=>{const vals=ASIGS.map(A=>{let c=0,w=0;temasOf(A.id).forEach(t=>{const x=temaCW(A.id,t.tk);c+=x[0];w+=x[1]});return {icon:A.icon,name:A.name,col:A.color,c,w,p:c+w?c/(c+w):null}});
 const sh=fmtShare(),fs=S.fst||{},weak=weakList('ALL').filter(x=>x.c+x.w>0).slice(0,6),rf=(S.rf||[]).slice(-6).reverse();
 const under=FMTS.slice().sort((a,b)=>(sh[a]-FMT_T[a])-(sh[b]-FMT_T[b]))[0],top=weakList('ALL')[0];
 V.innerHTML=`<button class="lnk" onclick="go('home')">← Inicio</button><h2>🧭 Diagnóstico de estudio</h2>
 <div class="card-box"><b>Acierto por asignatura</b><div class="radw">${radarSVG(vals)}</div><div class="leg">${vals.map(v=>`<span><i style="background:${v.col}"></i>${v.icon} ${esc(v.name)} <b>${v.p==null?'—':Math.round(v.p*100)+' %'}</b></span>`).join('')}</div></div>
 <div class="card-box"><b>Formatos de pregunta</b><div class="mut" style="margin:4px 0 8px">Barra: tu acierto. Marca blanca: cuánto te ha salido en las últimas 30 (objetivo del director: ${FMTS.map(f=>FMT_E[f]+' '+Math.round(FMT_T[f]*100)+' %').join(' · ')}).</div>
  ${FMTS.map(f=>{const x=fs[f]||{c:0,w:0},n=x.c+x.w,p=n?x.c/n:0;return `<div class="fmtrow"><span>${FMT_E[f]} ${FMT_N[f]}</span><div class="fbar"><i style="width:${p*100}%;background:${pctCol(x.c,x.w)}"></i><em style="left:${Math.min(98,sh[f]*100)}%"></em></div><small>${n?Math.round(p*100)+' %':'—'} <span class="mut">(${n})</span></small></div>`}).join('')}</div>
 <div class="card-box"><b>Temas que más te cuestan</b>${weak.length?weak.map(x=>`<div class="wrow"><span>${ASIG[x.a].icon} <b>${esc(x.tk)}</b> ${esc(cutTxt(x.name.replace(/^T\d+\s*/,''),34))} ${mastE(x.a,x.tk)}</span><div class="fbar"><i style="width:${x.p*100}%;background:${pctCol(x.c,x.w)}"></i></div><button class="btn sm sec" onclick="startReview('${x.a}','${jsq(x.tk)}')">Repasar</button></div>`).join(''):'<div class="mut">Juega unas partidas y aquí aparecerán.</div>'}</div>
 ${rf.length?`<div class="card-box"><b>Últimos conceptos fallados</b>${rf.map(x=>`<details class="rfd"><summary>${ASIG[x.a]?ASIG[x.a].icon:''} ${esc(x.tema||x.tk)}</summary><div class="qtext sm">${fmt(x.q)}</div><div class="okans">✅ ${fmt(x.ok)}</div>${x.sol?`<div class="sol">${fmt(x.sol)}</div>`:''}</details>`).join('')}</div>`:''}
 <div class="card-box glow"><b>🧭 Lo que te pondrá el director</b><div class="mut" style="margin:6px 0 10px">Prioriza ${top?`<b>${ASIG[top.a].icon} ${esc(top.tk)}</b> y tus otros temas flojos`:'tus temas flojos'}, los fallos recientes y el formato que menos te ha salido (<b>${FMT_E[under]} ${FMT_N[under]}</b>). Mezcla preguntas fijas y generadas.</div><button class="btn big" onclick="startDirected()">🧭 Sesión dirigida (12 preguntas)</button></div>`};

/* =====================================================================
   v5 · 2) REDISEÑO DE CARTAS
   ===================================================================== */
const STAT_S=['SEÑ','VEL','AB','ROB'],STAT_C=['#22d3ee','#fbbf24','#a78bfa','#34d399'];
const ROLES=[{n:'Emisora',e:'📡',d:'+2 s por pregunta'},{n:'Veloz',e:'⚡',d:'+10 % 🪙'},{n:'Banda ancha',e:'📶',d:'+10 % XP'},{n:'Blindada',e:'🛡️',d:'+1 escudo'}];
const roleOf=c=>c.s.indexOf(Math.max(...c.s));
cardHTML=function(c,o={}){const A=c.a==='ALL'?null:ASIG[c.a],ac=A?A.color:'#e879f9';
 if(o.locked)return `<div class="gcard tc r-${c.r} locked" style="--ac:${ac}"><div class="tc-in"><div class="tc-h"><span class="tc-rar">${RN[c.r]}</span><span class="tc-as">${A?A.icon:'🌍'}</span></div><div class="tc-art"><span class="e">❔</span></div><div class="tc-nm">???</div></div></div>`;
 const own=S.cards[c.id],lv=own?own.l:1,st=[0,1,2,3].map(i=>stat(c,i)),ovr=Math.round(st.reduce((a,b)=>a+b,0)/4),R=ROLES[roleOf(c)],fl=(own&&own.aw?'⭐':'')+(own&&own.sh?'✨':'')+(c.custom?'✏️':'');
 return `<div class="gcard tc r-${c.r}${own&&own.sh?' shiny':''}${own&&own.aw?' awk':''}" style="--ac:${ac}"><div class="tc-in">
 <div class="tc-h"><b class="tc-ovr">${ovr}</b><span class="tc-rar">${RN[c.r]}</span><span class="tc-as" title="${A?esc(A.name):'Todas'}">${A?A.icon:'🌍'}</span></div>
 <div class="tc-art">${c.r==='I'?embSVG(c).replace('class="emb"','class="tc-emb"'):''}<span class="e">${esc(c.e)}</span>${fl?`<i class="tc-fl">${fl}</i>`:''}${lv>1?`<i class="tc-lv">Nv${lv}</i>`:''}${o.count&&own&&own.n>1?`<i class="tc-cnt">x${own.n}</i>`:''}</div>
 <div class="tc-nm">${esc(c.n)}</div><div class="tc-role">${R.e} ${R.n}${c.ab?`<span class="tc-abl"> · ✨ ${AB[c.ab].s}</span>`:''}</div>
 <div class="tc-bars">${st.map((v,i)=>`<div class="tc-bar"><span>${STAT_S[i]}</span><i><b style="width:${Math.round(Math.max(4,(v-40)/59*100))}%;background:${STAT_C[i]}"></b></i><em>${v}</em></div>`).join('')}</div>
 <div class="tc-ds">${fmt(c.b)}</div></div></div>`};

/* =====================================================================
   v5 · 4) SINERGIAS DE ROL + badges
   ===================================================================== */
synergies=(old=>cs=>{const out=old(cs).map(x=>Object.assign({e:x.n.includes('total')||x.n.includes('troncal')?'🔗':x.n.includes('fama')?'👑':x.n.includes('Multiplex')?'🧵':x.n.includes('Jerarqu')?'🏗️':'🔗'},x)),rc={};
 cs.forEach(c=>{const k=roleOf(c);rc[k]=(rc[k]||0)+1});
 Object.entries(rc).forEach(([k,n])=>{if(n<2)return;const R=ROLES[k],x=n>=3?2:1,b=k==0?{tb:2*x}:k==1?{cm:.1*x}:k==2?{xm:.1*x}:{sh:x};out.push(Object.assign({e:R.e,n:`Rol ${R.n}${n>=3?' total':''}`,d:`${n} cartas ${R.n.toLowerCase()}s: ${k==0?'+'+2*x+' s':k==1?'+'+10*x+' % 🪙':k==2?'+'+10*x+' % XP':'+'+x+' 🛡️'}`},b))});
 return out})(synergies);
function synBadges(ids){const cs=(ids||S.deck).map(id=>CARD[id]).filter(Boolean),sy=synergies(cs);if(!cs.length)return '';return `<div class="sbadges">${sy.length?sy.map(x=>`<span class="sbadge" title="${esc(x.d)}" onclick="toast('${x.e} ${jsq(x.n)}: ${jsq(x.d)}')">${x.e} ${esc(x.n)}</span>`).join(''):'<span class="sbadge off">Sin sinergias: junta 2 de una asignatura o del mismo rol</span>'}</div>`}
deckHTML=function(asig,mode){const cells=[0,1,2].map(i=>{const c=CARD[S.deck[i]];return c?`<div onclick="pickDeck()">${cardHTML(c)}</div>`:`<div class="slot" onclick="pickDeck()">+</div>`}).join('');
 return `<div class="grid3" style="margin-top:8px">${cells}</div>${synBadges()}<div class="mut" style="margin-top:8px">${bonusText(deckBonus(asig,S.deck,mode))}${asig&&asig!=='ALL'?' (incluye +10% por cartas de la asignatura)':''}</div>`};
const deckPow=()=>{const cs=S.deck.map(id=>CARD[id]).filter(Boolean);return cs.length?cs.reduce((a,c)=>a+[0,1,2,3].reduce((x,i)=>x+stat(c,i),0)/4,0)/cs.length:50};
const deckFactor=()=>Math.max(.92,Math.min(1.15,1+(deckPow()-65)/250));

/* =====================================================================
   v5 · 3) EXPEDICIÓN: rasgos, mapa ramificado, eventos técnicos
   ===================================================================== */
Object.assign(TRAITS,{calculo:{e:'🧮',n:'Calculista',d:'Solo te lanza preguntas de cálculo'},tabular:{e:'📊',n:'Tabulador',d:'Te ataca con preguntas con tabla'},codigo:{e:'💻',n:'Compilador',d:'Te ataca con preguntas de código'},drena:{e:'🔋',n:'Drenaje',d:'Te quita 1 PV al empezar cada pregunta'},acecho:{e:'🎯',n:'Acechador',d:'Te pregunta de tus temas más flojos'}});
const FMT_TR={calculo:'calc',tabular:'tabla',codigo:'code'};
const ROUTE_CHALLENGES=['calc','tables','code','speed'];
function fmtCount(asig,f){return S.qs.filter(q=>(asig==='ALL'||q.asig===asig)&&fmtOf(q)===f).length}
genEnemy=function(kind){const r=S.run,A=ACTS[r.act-1],sc=(1+.1*r.asc)*(1+(r.floor-1)*.07),ac=1+.08*r.asc;let t,traits=[],hp,atk;
 const pool=Object.keys(TRAITS).filter(k=>!FMT_TR[k]||fmtCount(r.asig,FMT_TR[k])>=6);
 if(kind==='boss'){t=A.boss;traits=[...A.boss[2]];hp=120+60*(r.act-1);atk=9+3*(r.act-1);if(r.asc>=2)traits.push(pk(['acecho','drena'].filter(x=>!traits.includes(x))))}
 else{t=pk(kind==='elite'?A.el:A.en);hp=30+22*(r.act-1);atk=6+3*(r.act-1);const nt=kind==='elite'?1+(r.act>1?1:0)+(r.asc>=2?1:0):(Math.random()<.3+.3*r.act+.05*r.asc?1:0);if(kind==='elite'){hp*=1.7;atk*=1.3}traits=shuffle(pool.filter(x=>kind==='elite'||x!=='escudo')).slice(0,nt)}
 let f=false;traits=traits.filter(x=>{if(!FMT_TR[x])return true;if(f)return false;f=true;return true});
 hp=Math.round(hp*sc);return {n:t[0],e:t[1],hp,maxhp:hp,atk:Math.round(atk*ac),traits,boss:kind==='boss',elite:kind==='elite',shieldUp:traits.includes('escudo'),wt:traits.includes('acecho')?weakKey(r.asig):null}};
runFight=function(kind){const r=S.run;if(!r.enemy)r.enemy=genEnemy(kind);const E=r.enemy;E.kind=kind;save();const difs=runDifs(kind),p0=runPred();let p=p0;
 const ft=E.traits.find(x=>FMT_TR[x]);if(ft){const p1=q=>p0(q)&&fmtOf(q)===FMT_TR[ft];if(S.qs.filter(p1).length>=6)p=p1}
 if(E.wt){const ws=new Set(weakList(r.asig).slice(0,3).map(x=>x.a+'|'+x.tk).concat([E.wt]));const pp=p,p2=q=>pp(q)&&ws.has(q.asig+'|'+q.tk);if(S.qs.filter(p2).length>=6)p=p2}
 const count=kind==='boss'?3:1,qs=pickQs(p,count,difs).map((q,i)=>kind==='boss'?Object.assign({},q,{q:`CUELLO DE BOTELLA · ETAPA ${i+1}/3\n${q.q}`}):q);
 startMatch({mode:'run',runNode:kind,asig:r.asig,pred:p,runDifs:difs,qs,endless:kind!=='boss',noTimer:false});if(M)M.buffOn=!!r.buff;
 setTimeout(()=>floatTxt(`${E.e} ${E.n}${E.wt?' · 🎯 '+E.wt.split('|')[1]:''}`,'#fca5a5'),350)};
runOnShow=(old=>function(){old();const r=S.run;if(r&&r.enemy&&hasTr('drena')&&r.hp>1){r.hp--;setTimeout(()=>{floatTxt('🔋 −1 PV','#f87171');if(typeof updRunUI==='function')updRunUI()},120)}})(runOnShow);
runDmg=(old=>function(){let d=old();if(M&&M.buffOn)d=Math.round(d*1.3);return d})(runDmg);

/* ---------- Mapa ramificado por acto ---------- */
const MAPW=4;
function genMap(act){return seeded('map'+act,()=>{const F=RUN_F,nodes=[],at={},E=new Set();const nid=(f,l)=>{const k=f+'_'+l;if(at[k]==null){at[k]=nodes.length;nodes.push({id:nodes.length,f,l,k:null})}return at[k]};
 const starts=shuffle([0,1,2,3]);const boss=nid(F,1.5);
 for(let p=0;p<4;p++){let l=p<3?starts[p]:ri(0,MAPW-1),prev=nid(1,l);for(let f=2;f<F;f++){let nl=Math.max(0,Math.min(MAPW-1,l+ri(-1,1)));if(nl!==l&&at[(f-1)+'_'+nl]!=null&&at[f+'_'+l]!=null&&E.has(at[(f-1)+'_'+nl]+'>'+at[f+'_'+l]))nl=l;const cur=nid(f,nl);E.add(prev+'>'+cur);prev=cur;l=nl}E.add(prev+'>'+boss)}
 const e=[...E].map(s=>s.split('>').map(Number)),par=id=>e.filter(x=>x[1]===id).map(x=>nodes[x[0]]);
 nodes.slice().sort((a,b)=>a.f-b.f).forEach(n=>{if(n.f===F){n.k='boss';return}if(n.f===1){n.k='combat';return}if(n.f===F-1){n.k='rest';return}if(n.f===5&&Math.random()<.6){n.k='treasure';return}
  const routes=ROUTE_CHALLENGES.filter(k=>S.qs.filter(q=>(S.run.asig==='ALL'||q.asig===S.run.asig)&&routeQuestionMatches(k,q)).length+GENS.filter(g=>(S.run.asig==='ALL'||g.a===S.run.asig)&&routeQuestionMatches(k,{calc:!!g.c,route:g.route||null,dif:g.d,q:''})).length*6>=6);
  for(let t=0;t<6;t++){const choices=['combat','event','elite','shop','rest','treasure',...routes],k=wsample(choices,x=>({combat:4.5,event:2.2,elite:n.f>=3?1.4+.2*act:0,shop:n.f>=3?1:0,rest:n.f>=4?.9:0,treasure:.4,calc:1.5,tables:1.3,code:1.3,speed:1.3})[x],1)[0];if(['elite','rest','shop',...ROUTE_CHALLENGES].includes(k)&&par(n.id).some(p=>p.k===k))continue;n.k=k;break}if(!n.k)n.k='combat'});
 const r=S.run,f0=r.floor;nodes.forEach(n=>{if(['combat','elite','boss',...ROUTE_CHALLENGES].includes(n.k)){r.floor=n.f;const kind=ROUTE_CHALLENGES.includes(n.k)?'combat':n.k;n.en=seeded('en'+act+'_'+n.id,()=>genEnemy(kind))}});r.floor=f0;
 return {nodes,e}})}
function runAvail(){const r=S.run,m=r&&r.map;if(!m)return [];if(r.pos!=null){const n=m.nodes[r.pos];if(n&&n.f===r.floor-1)return m.e.filter(x=>x[0]===r.pos).map(x=>x[1])}return m.nodes.filter(n=>n.f===r.floor).map(n=>n.id)}
function nodeRisk(n){const r=S.run;if(!n.en)return null;const E=n.en,df=deckFactor(),hp=Math.round(E.maxhp*df);let c=0,w=0;(r.asig==='ALL'?ASIGS:[ASIG[r.asig]]).forEach(A=>temasOf(A.id).forEach(t=>{const x=temaCW(A.id,t.tk);c+=x[0];w+=x[1]}));
 const acc=Math.max(.35,Math.min(.95,(c+3)/(c+w+4))),dmg=10+deckPow()/8+4*(r.act-1),hits=Math.ceil(hp/dmg),fails=hits*(1-acc)/acc,exp=Math.round(fails*E.atk*(E.traits.includes('furia')?1.4:1)+(E.traits.includes('drena')?hits/acc:0)),ratio=exp/Math.max(1,r.hp);
 return {hp,exp,lv:ratio<.25?0:ratio<.6?1:2}}
const RISK=[{n:'Bajo',c:'#22c55e',e:'🟢'},{n:'Medio',c:'#facc15',e:'🟡'},{n:'Alto',c:'#ef4444',e:'🔴'}];
function runMapSVG(){const r=S.run,m=r.map,F=RUN_F,RH=60,H=F*RH+16,X=l=>38+l*(264/(MAPW-1)),Y=f=>(F-f)*RH+36,av=new Set(runAvail()),vis=new Set(r.visited||[]);
 const lines=m.e.map(([a,b])=>{const A=m.nodes[a],B=m.nodes[b],on=vis.has(a)&&vis.has(b),nx=a===r.pos&&av.has(b);return `<line x1="${X(A.l)}" y1="${Y(A.f)}" x2="${X(B.l)}" y2="${Y(B.f)}" class="me${on?' on':''}${nx?' nx':''}"/>`}).join('');
 const circ=m.nodes.map(n=>{const N=NODES2[n.k],cls=`mn k-${n.k}${vis.has(n.id)?' done':''}${av.has(n.id)?' av':''}${r.pos===n.id?' cur':''}${r.sel===n.id?' sel':''}`,rk=nodeRisk(n),rr=n.k==='boss'?24:17;
  return `<g class="${cls}" onclick="runSel(${n.id})" role="button" tabindex="0" aria-label="${N.n} piso ${n.f}"><circle cx="${X(n.l)}" cy="${Y(n.f)}" r="${rr}"/>${rk&&av.has(n.id)?`<circle class="rk" cx="${X(n.l)+rr*.75}" cy="${Y(n.f)-rr*.75}" r="5" fill="${RISK[rk.lv].c}"/>`:''}<text x="${X(n.l)}" y="${Y(n.f)}" dy=".36em">${N.e}</text></g>`}).join('');
 const lbl=Array.from({length:F},(_,i)=>`<text x="6" y="${Y(i+1)}" dy=".35em" class="mfl">${i+1}</text>`).join('');
 return `<svg viewBox="0 0 340 ${H}" class="rmsvg" role="img" aria-label="Mapa del acto">${lbl}${lines}${circ}</svg>`}
function runSel(id){const r=S.run;if(!r||!r.map)return;r.sel=r.sel===id?null:id;render()}
function nodePreview(id){const r=S.run,n=r.map.nodes[id];if(!n)return '';const N=NODES2[n.k],av=runAvail().includes(id),rk=nodeRisk(n),E=n.en;
 let body=`<div class="mut">${N.d}${N.profile?` · Perfil: ${N.profile}`:''}</div>`;
 if(E){const d=(()=>{const f0=r.floor;r.floor=n.f;const x=runDifs(n.k);r.floor=f0;return x})();body=`<div class="pv-en"><span class="pv-e">${E.e}</span><div><b>${esc(E.n)}</b><div class="mut">❤️ ≈${rk.hp} PV · ⚔️ ${E.atk} por fallo · preguntas ${d.map(x=>DIFS[x].n).join('/')}</div></div></div>
  <div class="en-tr">${E.traits.length?E.traits.map(t=>`<i title="${esc(TRAITS[t].d)}">${TRAITS[t].e} ${TRAITS[t].n}</i>`).join(''):'<i>Sin rasgos</i>'}</div>${E.traits.map(t=>`<div class="mut sm">${TRAITS[t].e} ${TRAITS[t].d}${t==='acecho'&&E.wt?` (${esc(E.wt.split('|')[1])} de ${ASIG[E.wt.split('|')[0]].name})`:''}</div>`).join('')}
  <div class="mut sm">Perfil de ruta: ${N.profile||'MIXTO'}${ROUTE_CHALLENGES.includes(n.k)?` · ${N.d}`:''}</div><div class="risk" style="--rc:${RISK[rk.lv].c}">${RISK[rk.lv].e} Riesgo ${RISK[rk.lv].n} · ≈ −${rk.exp} PV esperados (tienes ${r.hp})</div>`}
 return `<div class="card-box pv"><div class="rowb"><b>${N.e} ${N.n} · piso ${n.f}</b><button class="lnk" onclick="runSel(${id})">✕</button></div>${body}${av?`<button class="btn" style="margin-top:10px" onclick="runGo(${id})">Ir aquí ›</button>`:`<div class="mut sm" style="margin-top:6px">${(r.visited||[]).includes(id)?'Ya has pasado por aquí.':'No está conectado con tu posición.'}</div>`}</div>`}
function runGo(id){const r=S.run;if(!r||r.enemy||r.reward||r.ev||r.shop||r.rest||(r.choice&&r.choice.length))return;if(!runAvail().includes(id))return;const n=r.map.nodes[id];
 r.pos=id;r.sel=null;r.floor=n.f;(r.visited||(r.visited=[])).push(id);trk('nodes');prog('node',1);
 if(n.en){r.path.push(n.k);r.challenge=ROUTE_CHALLENGES.includes(n.k)?n.k:null;const E=JSON.parse(JSON.stringify(n.en));E.hp=E.maxhp=Math.round(E.maxhp*deckFactor());if(r.curse&&n.k!=='boss'){E.hp=E.maxhp=Math.round(E.maxhp*1.3);r.curse=0}r.enemy=E;runFight(r.challenge?'combat':n.k);return}
 r.challenge=null;
 seeded('node'+r.act+'_'+id,()=>runNode(n.k))}

