function applyFx(fx){const r=S.run,m=[];if(!fx)return '';
 if(fx.chance!=null){const ok=Math.random()<fx.chance;return (ok?'✅ ':'❌ ')+applyFx(ok?fx.win:fx.lose)}
 if(fx.gems){if(fx.gems<0&&r.gems<-fx.gems){return 'No tienes gemas suficientes: no pasa nada.'}r.gems+=fx.gems;m.push((fx.gems>0?'+':'')+fx.gems+' 💎')}
 if(fx.hp){r.hp=Math.max(1,Math.min(r.maxhp,r.hp+fx.hp));m.push((fx.hp>0?'+':'')+fx.hp+' PV')}
 if(fx.maxhp){r.maxhp=Math.max(10,r.maxhp+fx.maxhp);r.hp=Math.min(r.maxhp,fx.maxhp>0?r.hp+fx.maxhp:r.hp);m.push((fx.maxhp>0?'+':'')+fx.maxhp+' PV máx.')}
 if(fx.pot)for(let i=0;i<fx.pot;i++)if(addPot(fx.potk))m.push('+1 poción');
 if(fx.relic){const k=relicChoices()[0];if(k){addRelic(k);m.push(`${RELICS[k].e} ${RELICS[k].n}`)}}
 if(fx.xp){giveDeckXP(fx.xp);m.push(`+${fx.xp} XP a tus cartas`)}
 if(fx.buff){r.buff=1;m.push('+30 % de daño en el próximo combate')}
 return m.join(' · ')||'Nada cambia.'}
runEvent=(old=>function(){const r=S.run;seeded('ev'+r.act+'_'+r.pos,()=>{if(Math.random()<.35)return old();
 const asigs=r.asig==='ALL'?[...new Set(PEV.map(f=>f().a))]:[r.asig];const wk=weakKey(r.asig),pref=wk?wk.split('|')[0]:null;const cand=PEV.map(f=>f()).filter(x=>asigs.includes(x.a));if(!cand.length)return old();
 const ev=wsample(cand,x=>x.a===pref?3:1,1)[0];r.ev={pe:1,a:ev.a,tk:ev.tk,e:ev.e,t:ev.t,d:ev.d,o:ev.o.map(x=>x.l),fx:ev.o.map(x=>x.fx)};save();render()})})(runEvent);
let EVQ=null;
runEvChoose=(old=>function(j){const r=S.run;if(!r||!r.ev)return;if(!r.ev.pe)return old(j);const ev=r.ev,fx=ev.fx[j];trk('evts');
 const done=res=>{r.ev=null;save();modal(`<div class="cele"><div class="ce">${ev.e}</div><h2>${esc(ev.t)}</h2><div class="mut" style="font-size:15px">${res}</div><button class="btn gold" style="margin-top:16px" onclick="closeModal();runAdvance()">Seguir</button></div>`,true)};
 if(fx.quiz){r.ev=null;save();return evQuiz(ev.a,fx.quiz,good=>{if(good){trk('pevOk');prog('pev',1)}done((good?'✅ ¡Bien resuelto! ':'❌ No era esa. ')+seeded('evq'+r.act+'_'+r.pos,()=>applyFx(good?fx.win:fx.lose)))})}
 done(seeded('evr'+r.act+'_'+r.pos,()=>applyFx(fx)))})(runEvChoose);
function statBump(q,good){const st=q.gen?((S.gst||(S.gst={}))[q.asig+'|'+q.tk]||(S.gst[q.asig+'|'+q.tk]={c:0,w:0,l:0})):(S.st[q.id]||(S.st[q.id]={c:0,w:0,l:0}));if(good){st.c++;st.l=1;S.totC=(S.totC||0)+1}else{st.w++;st.l=0}fstBump(q,good);if(!good){const rf=S.rf||(S.rf=[]);rf.push({a:q.asig,tk:q.tk,tema:q.tema,q:cutTxt(q.q,150),ok:cutTxt(q.ops[q.ok],90),sol:cutTxt(String(q.sol||'').split('\n')[0],220),t:Date.now()})}}
function evQuiz(a,tk,cb){const r=S.run,d=Math.max(1,Math.min(4,r.act+1));let qs=pickQs(q=>q.asig===a&&q.tk===tk,1,[d]);if(!qs.length)qs=pickQs(q=>q.asig===a,1,[1,2,3,4]);const q=qs[0];if(!q){cb(true);return}
 const order=q.ops.length>2?shuffle(q.ops.map((_,k)=>k)):q.ops.map((_,k)=>k);EVQ={q,cb,done:false};
 modal(`<div class="evq"><div class="mut">${ASIG[a].icon} ${esc(q.tema)} · ${DIFS[q.dif].n}</div><div class="qtext sm">${fmt(q.q)}</div>${q.tabla?tableHTML(q.tabla):''}<div id="evo">${order.map((k,i)=>`<button class="opt" data-k="${k}" onclick="evAns(${k})"><b class="ol">${LET[i]}</b><span>${fmt(q.ops[k])}</span></button>`).join('')}</div><div id="evr"></div></div>`,true)}
function evAns(k){const E=EVQ;if(!E||E.done)return;E.done=true;const q=E.q,good=k===q.ok;statBump(q,good);sfx(good?'ok':'bad');
 document.querySelectorAll('#evo .opt').forEach(b=>{const kk=+b.dataset.k;b.disabled=true;if(kk===q.ok)b.classList.add('ok');else if(kk===k)b.classList.add('bad')});
 const el=$('#evr');if(el){el.innerHTML=`${q.sol?`<div class="sol">${fmt(q.sol)}</div>`:''}<button class="btn" style="margin-top:10px" id="evgo">Seguir</button>`;math(el);$('#evgo').onclick=()=>{closeModal();EVQ=null;E.cb(good)}}save()}

/* =====================================================================
   v5 · 4) RECOMPENSAS: reliquias, pociones y cartas según acto, Ascensión, mazo y temas flojos
   ===================================================================== */
const RCAT={def:['tir','dis','bat','vam','tre','ext','ven'],off:['amp','tes','cua','rul','fib','las'],uti:['osc','pri','ant','chip','mod','rel']};
relicChoices=function(){const r=S.run;if(!r)return [];const pool=Object.keys(RELICS).filter(k=>!r.relics.includes(k)),low=r.hp/r.maxhp<.5,pw=deckPow();
 return wsample(pool,k=>RCAT.def.includes(k)?(low?2.2:1)+(r.asc>=3?.5:0):RCAT.off.includes(k)?(pw>70?1.8:1)+(r.act>=2?.3:0):1,3)};
function cardOffer(big){const r=S.run,wts=big==='boss'?{B:0,P:.25,O:.6,I:.15}:big?{B:.1,P:.45,O:.45,I:0}:[{B:.6,P:.35,O:.05,I:0},{B:.3,P:.5,O:.2,I:0},{B:.1,P:.5,O:.4,I:0}][r.act-1];
 const rar=wsample(['B','P','O','I'],x=>wts[x]||0,1)[0],wk=weakKey(r.asig),dk=S.deck.map(id=>CARD[id]).filter(Boolean).map(c=>c.a),x=Math.random();
 const asig=x<.55&&wk?wk.split('|')[0]:x<.85&&dk.length?pk(dk):(r.asig==='ALL'?pk(ASIGS).id:r.asig);
 let pool=CARDS.filter(c=>c.r===rar&&c.a===asig);if(!pool.length)pool=CARDS.filter(c=>c.r===rar);if(!pool.length)pool=CARDS.filter(c=>c.r!=='I');return pool.length?pk(pool).id:null}
function giveRunCard(id){const c=CARD[id];if(!c)return;const o=S.cards[id];if(o)o.n++;else S.cards[id]={n:1,l:1};trk('runCards');toast(`🃏 ${c.e} ${c.n} (${RN[c.r]})${o?' · copia extra':' · ¡nueva!'}`);if(typeof checkSets==='function')checkSets()}
const REWN2={card:'🃏 Carta',heal:'❤️ Curar 30 % de la vida'};
function buildReward(R,E){const r=S.run;R.card=cardOffer(E.boss?'boss':E.elite?'elite':null);
 if(R.type==='pick'){const low=r.hp/r.maxhp<.5,lowLv=S.deck.some(id=>(S.cards[id]||{}).l<3);R.opts=wsample(['pot','gems','xp','maxhp','heal','card'],k=>({pot:r.pots.length>=potMax()?.1:1,gems:1,xp:lowLv?1.6:.8,maxhp:1,heal:low?2.6:.3,card:R.card?1.3:0})[k],3)}}
runAfterMatch=(old=>function(){const r=S.run,E=r&&r.enemy?JSON.parse(JSON.stringify(r.enemy)):null,win=!!(M&&M.runWin);
 if(r&&M){const fl=M.res.filter(x=>!x.ok).map(x=>findQ(x.id)).filter(Boolean).slice(0,5).map(q=>({id:q.id,a:q.asig,tema:q.tema,q:cutTxt(q.q,140),ok:cutTxt(q.ops[q.ok],90),sol:cutTxt(String(q.sol||'').split('\n')[0],200)}));r.lastFails=fl.length?{n:M.res.filter(x=>!x.ok).length,tot:M.res.length,list:fl}:null;if(M.buffOn)r.buff=0}
 old();const r2=S.run;if(!r2||!E||!win)return;
 const T=S.trs||(S.trs={});(E.traits||[]).forEach(t=>T[t]=1);if((E.traits||[]).includes('acecho')){trk('acechoK');prog('acecho',1)}
 if(r2.reward){seeded('rw'+r2.act+'_'+r2.pos,()=>buildReward(r2.reward,E));save();render()}})(runAfterMatch);
runReward=(old=>function(k){const r=S.run,R=r&&r.reward;if(!R)return;const act0=r.act;
 if(k==='card'){giveRunCard(R.card);k=R.type==='relic'?'none':'card'}else if(k==='heal'){const h=Math.round(r.maxhp*.3);r.hp=Math.min(r.maxhp,r.hp+h);toast(`❤️ +${h} PV`)}
 old(k);const r2=S.run;if(r2&&r2.act!==act0){r2.map=genMap(r2.act);r2.pos=null;r2.sel=null;r2.visited=[];r2.floor=1;save();render()}})(runReward);
runShopGen=(old=>function(){old();const r=S.run,id=cardOffer(null);if(id){const c=CARD[id];r.shop.push({k:'card:'+id,c:{B:12,P:20,O:34,I:60}[c.r]})}})(runShopGen);
runBuy=(old=>function(i){const r=S.run,it=r.shop&&r.shop[i];if(it&&it.k.startsWith('card:')){if(it.sold||r.gems<it.c)return;r.gems-=it.c;it.sold=true;giveRunCard(it.k.slice(5));sfx('gold');save();render();return}old(i)})(runBuy);
shopLabel=(old=>function(it){if(it.k.startsWith('card:')){const c=CARD[it.k.slice(5)];return c?`🃏 ${c.e} ${esc(c.n)} <small>${RN[c.r]} · ${c.a==='ALL'?'Todas':esc(ASIG[c.a].name)}</small>`:'🃏 Carta'}return old(it)})(shopLabel);

/* ---------- Inicio y fin de expedición con semilla ---------- */
FLR.seed='';
startRun=function(){const own=normSeed(FLR.seed),seed=own||newSeed();S.run={v:2,mv:1,seed,seedSet:!!own,asig:FLR.asig,asc:FLR.asc,act:1,floor:1,hp:60,maxhp:60,gems:0,relics:[],pots:['botiquin'],nodes:[],path:[],kills:0,dmg:0,enemy:null,reward:null,shop:null,rest:null,ev:null,curse:0,pos:null,sel:null,visited:[],buff:0,lastFails:null};
 S.run.map=genMap(1);S.run.choice=seeded('start',()=>relicChoices());trk('runs');save();go('run')};
runEnd=(old=>function(win){const r=S.run;if(win&&r&&r.seedSet)trk('seedWin');old(win)})(runEnd);
runAdvance=function(){const r=S.run;if(!r)return;r.shop=null;r.rest=null;r.ev=null;r.challenge=null;r.floor++;save();go('run')};
function runMigrate(r){if(r&&r.v===2&&!r.map){r.seed=r.seed||newSeed();r.map=genMap(r.act);r.pos=null;r.visited=r.visited||[];r.mv=1}}

VIEWS.run=()=>{let r=S.run;if(r&&r.v!==2){S.run=null;r=null;save()}runMigrate(r);
 if(!r){const asigs=ASIGS.filter(a=>S.qs.some(q=>q.asig===a.id)),am=S.ascMax||0;if(FLR.asc>am)FLR.asc=am;
  V.innerHTML=`<button class="lnk" onclick="go('home')">← Inicio</button><h2>🏰 Expedición</h2>
  <div class="acts">${ACTS.map((A,i)=>`<div class="actc" style="--ac:${A.c}"><span>${A.e}</span><b>Acto ${i+1}</b><small>${A.n}</small><small>${A.boss[1]} ${A.boss[0]}</small></div>`).join('')}</div>
  <div class="card-box"><b>Roguelike de estudio</b><div class="mut" style="margin-top:6px">3 actos con un <b>mapa ramificado</b> de ${RUN_F} pisos: tú eliges la ruta mirando el riesgo de cada nodo. Cada acierto hace daño al enemigo y cada fallo te quita vida. Hay enemigos con rasgos (algunos te atacan con cálculo, tablas, código o tus temas flojos), élites, jefes de 2 fases, tiendas con cartas, hogueras, tesoros y <b>eventos técnicos</b> de cada asignatura donde puedes resolver tú el problema. Las recompensas se adaptan a tu acto, tu mazo y lo que te cuesta.</div></div>
  <div class="mut">Asignatura</div><div class="chips">${chip('🔀 Todo mezclado',FLR.asig==='ALL',"FLR.asig='ALL';render()")}${asigs.map(a=>chip(a.icon+' '+esc(a.name),FLR.asig===a.id,`FLR.asig='${a.id}';render()`)).join('')}</div>
  <div class="mut">Ascensión (enemigos +10 % de vida y +8 % de daño por nivel; desde A2 más rasgos; premios +15 % por nivel)</div><div class="chips">${Array.from({length:am+1},(_,i)=>chip(i?'A'+i:'Normal',FLR.asc===i,`FLR.asc=${i};render()`)).join('')}${am<10?`<span class="chip" style="opacity:.5">🔒 A${am+1}</span>`:''}</div>
  <label class="mut" for="seedin">🌱 Semilla (opcional: la misma semilla genera el mismo mapa, enemigos, eventos y tiendas)</label><div class="seedrow"><input id="seedin" maxlength="16" placeholder="Vacío = aleatoria" value="${esc(FLR.seed)}" oninput="FLR.seed=this.value"><button class="btn sm sec" onclick="FLR.seed=newSeed();render()">🎲</button></div>
  <div class="mut" style="margin:8px 0 10px">Récord: ${S.runBest>RUN_ACTS*RUN_F?'🏆 completada':S.runBest?'piso '+S.runBest+' de '+RUN_ACTS*RUN_F:'ninguno todavía'} · Ganadas: ${S.runWins||0} · Enemigos derrotados: ${S.runKills||0}</div>
  <button class="btn big" onclick="startRun()">🏰 EMPEZAR EXPEDICIÓN</button>`;return}
 const A=ACTS[r.act-1];let body='';
 const fails=r.lastFails?`<details class="card-box fsum" open><summary><b>📋 Resumen del combate</b> · ${r.lastFails.n} fallo${r.lastFails.n===1?'':'s'} de ${r.lastFails.tot}</summary>${r.lastFails.list.map(x=>`<div class="fitem"><div class="mut sm">${ASIG[x.a]?ASIG[x.a].icon:''} ${esc(x.tema)}</div><div class="qtext sm">${fmt(x.q)}</div><div class="okans">✅ ${fmt(x.ok)}</div>${x.sol?`<div class="sol">${fmt(x.sol)}</div>`:''}${x.id?`<button class="btn sec sm xbtn" onclick="explainId('${x.id}')">🦉 Explícamelo</button>`:''}</div>`).join('')}<button class="btn sm sec" onclick="S.run.lastFails=null;save();render()">Entendido</button></details>`:'';
 if(r.choice&&r.choice.length)body=`<h3>✨ Bendición inicial: elige una reliquia</h3>${r.choice.map(k=>`<button class="menu" onclick="runStartPick('${k}')"><span>${RELICS[k].e}</span><div><b>${RELICS[k].n}</b><small>${RELICS[k].d}</small></div><i>›</i></button>`).join('')}`;
 else if(r.enemy)body=`<div class="card-box"><b>${r.enemy.e} Combate en curso contra ${esc(r.enemy.n)}</b><div class="mut">Le quedan ${r.enemy.hp}/${r.enemy.maxhp} PV.</div><button class="btn" style="margin-top:10px" onclick="runFight('${r.enemy.kind||'combat'}')">⚔️ Volver al combate</button></div>`;
 else if(r.reward){const R=r.reward,cc=R.card&&CARD[R.card];
  const cardBtn=cc?`<button class="menu rwcard" onclick="runReward('card')"><span class="rwe rw-${cc.r}">${esc(cc.e)}<i>${Math.round([0,1,2,3].reduce((x,i)=>x+stat(cc,i),0)/4)}</i></span><div><b>🃏 ${esc(cc.n)}</b><small>${RN[cc.r]} · ${cc.a==='ALL'?'Todas':esc(ASIG[cc.a].name)}${S.cards[cc.id]?' · copia para subirla de nivel':' · ¡nueva!'}</small></div><i>›</i></button>`:'';
  body=`${fails}<h3>${R.boss?'👑 ¡Jefe derrotado!':'☠️ ¡Enemigo derrotado!'} +${R.gem} 💎${R.pot?' y una poción':''}</h3><div class="mut" style="margin-bottom:8px">${R.type==='relic'?'Elige una reliquia (o la carta):':'Elige tu recompensa:'}</div>
  ${R.type==='relic'?(R.opts.length?R.opts.map(k=>`<button class="menu" onclick="runReward('${k}')"><span>${RELICS[k].e}</span><div><b>${RELICS[k].n}</b><small>${RELICS[k].d}</small></div><i>›</i></button>`).join(''):`<button class="btn" onclick="runReward('none')">Seguir</button>`)+cardBtn
   :R.opts.map(k=>k==='card'?cardBtn:`<button class="menu" onclick="runReward('${k}')"><span>${(REWN2[k]||REWN[k]).split(' ')[0]}</span><div><b>${(REWN2[k]||REWN[k]).split(' ').slice(1).join(' ')}</b></div><i>›</i></button>`).join('')}`}
 else if(r.ev)body=`<div class="card-box evbox"><div class="ce" style="font-size:44px;text-align:center">${r.ev.e}</div><h3 style="text-align:center">${esc(r.ev.t)}</h3>${r.ev.pe?`<div class="evtag">${ASIG[r.ev.a].icon} Evento técnico · ${esc(ASIG[r.ev.a].name)}</div>`:''}<div class="mut evd">${r.ev.pe?fmt(r.ev.d):r.ev.d}</div>${r.ev.o.map((o,j)=>`<button class="btn sec evo" onclick="runEvChoose(${j})">${r.ev.pe?fmt(o):o}</button>`).join('')}</div>`;
 else if(r.shop)body=`<h3>🛒 Tienda del laboratorio</h3>${r.shop.map((it,i)=>`<div class="mrow"><span>${shopLabel(it)}</span><button class="btn sm ${it.sold||r.gems<it.c?'sec':'gold'}" ${it.sold||r.gems<it.c?'disabled':''} onclick="runBuy(${i})">${it.sold?'Vendido':it.c+' 💎'}</button></div>`).join('')}<button class="btn" style="margin-top:12px" onclick="runAdvance()">Seguir subiendo ›</button>`;
 else if(r.rest)body=`<h3>🔥 Hoguera</h3><button class="menu" onclick="runRest('heal')"><span>😴</span><div><b>Descansar</b><small>Recuperas el 35 % de la vida (${Math.round(r.maxhp*.35)} PV)</small></div><i>›</i></button><button class="menu" onclick="runRest('xp')"><span>📚</span><div><b>Estudiar</b><small>+60 XP para las cartas de tu mazo</small></div><i>›</i></button><button class="menu" onclick="runRest('pot')"><span>⚗️</span><div><b>Destilar</b><small>Fabricas una poción al azar</small></div><i>›</i></button>`;
 else{const av=runAvail();body=`${fails}<h3 style="margin:0">Piso ${r.floor}: elige camino</h3><div class="mut sm">Toca un nodo del mapa para ver su riesgo, o elige abajo.</div>
  <div class="rmap" id="rmap">${runMapSVG()}</div>${r.sel!=null?nodePreview(r.sel):''}
  <div class="avl">${av.map(id=>{const n=r.map.nodes[id],N=NODES2[n.k],rk=nodeRisk(n);return `<button class="node n-${n.k}" onclick="runGo(${id})"><span>${N.e}</span><div><b>${N.n}${n.en?' · '+esc(n.en.n):''}</b><small>${n.en?`${n.en.traits.map(t=>TRAITS[t].e).join('')||'Sin rasgos'} · ⚔️ ${n.en.atk} · ${RISK[rk.lv].e} riesgo ${RISK[rk.lv].n.toLowerCase()}`:N.d}</small></div></button>`}).join('')}</div>`;
  setTimeout(()=>{const c=$('#rmap');if(c){const k=((RUN_F-r.floor)*60+36)/(RUN_F*60+16);c.scrollTop=Math.max(0,c.scrollHeight*k-c.clientHeight/2)}},30)}
 V.innerHTML=`<div class="actban" style="--ac:${A.c}"><span>${A.e}</span><div><b>Acto ${r.act}/${RUN_ACTS}: ${A.n}</b><small>${r.asig==='ALL'?'Todo mezclado':esc(ASIG[r.asig].name)}${r.asc?' · Ascensión '+r.asc:''}</small></div></div>
 <div class="seedbar">🌱 Semilla <b>${esc(r.seed||'—')}</b><button class="lnk" onclick="copyTxt('${r.seed}')">Copiar</button>${r.buff?'<span class="sbadge">💪 +30 % daño próximo combate</span>':''}</div>
 <div class="hpb me big"><i style="width:${r.hp/r.maxhp*100}%"></i><span>❤️ ${r.hp}/${r.maxhp} PV</span></div>
 <div class="runstat"><span>💎 <b>${r.gems}</b></span><span>☠️ ${r.kills||0}</span><span>🧪 ${r.pots.map(k=>`<i class="potv" onclick="toast('${POTS[k].e} ${POTS[k].n}: ${POTS[k].d}')">${POTS[k].e}</i>`).join('')||'—'} <small class="mut">(${r.pots.length}/${potMax()})</small></span></div>
 <div class="relics">${r.relics.length?r.relics.map(k=>`<span onclick="toast('${RELICS[k].e} ${RELICS[k].n}: ${RELICS[k].d}')">${RELICS[k].e}</span>`).join(''):'<small class="mut">Sin reliquias todavía</small>'}</div>
 ${synBadges()}${body}<button class="del" style="margin-top:16px" onclick="abandonRun(this)">Abandonar expedición</button>`};
NODES2.event.d='Evento técnico o decisión arriesgada';

