MT.push({k:'gx',t:'Acierta {g} preguntas generadas avanzadas ⚙️',g:[4,6],rw:g=>30+g*12},{k:'node',t:'Avanza {g} nodos en el mapa de la Expedición',g:[3,5],rw:g=>30+g*12},{k:'pev',t:'Resuelve {g} evento técnico acertando su pregunta',g:[1,1],rw:()=>90},{k:'dir',t:'Completa {g} sesión dirigida del Director 🧭',g:[1,1],rw:()=>80},{k:'syn',t:'Termina {g} partidas con 2 o más sinergias activas',g:[2,3],rw:g=>30+g*20});
WMT.push({k:'gx',t:'Acierta {g} preguntas generadas avanzadas',g:[25,40],rw:g=>g*14},{k:'node',t:'Avanza {g} nodos del mapa',g:[15,25],rw:g=>g*16},{k:'pev',t:'Resuelve {g} eventos técnicos',g:[3,5],rw:g=>g*90},{k:'dir',t:'Completa {g} sesiones dirigidas',g:[3,5],rw:g=>g*80},{k:'syn',t:'Termina {g} partidas con 2+ sinergias',g:[6,10],rw:g=>g*35},{k:'acecho',t:'Derrota a {g} enemigos Acechadores 🎯',g:[3,5],rw:g=>g*70});
ACH.push(
 ['gx50','⚙️','Ingeniería procedural','Acierta 50 preguntas de generadores avanzados',()=>tr('gx')>=50,400],
 ['gx200','🏭','Fábrica de problemas','Acierta 200 preguntas de generadores avanzados',()=>tr('gx')>=200,1200],
 ['nd50','🗺️','Cartógrafo','Avanza 50 nodos en el mapa de la Expedición',()=>tr('nodes')>=50,300],
 ['pev5','🧪','Ingeniero de guardia','Resuelve 5 eventos técnicos acertando su pregunta',()=>tr('pevOk')>=5,400],
 ['pev25','🛠️','Jefe de mantenimiento','Resuelve 25 eventos técnicos acertando su pregunta',()=>tr('pevOk')>=25,1000],
 ['ack10','🎯','Sin puntos débiles','Derrota a 10 enemigos Acechadores',()=>tr('acechoK')>=10,500],
 ['bst','📖','Bestiario completo','Derrota a enemigos con todos los rasgos',()=>Object.keys(TRAITS).every(k=>(S.trs||{})[k]),1200],
 ['seed1','🌱','Sembrador','Gana una expedición con una semilla elegida por ti',()=>tr('seedWin')>=1,600],
 ['syn3','🔗','Sinergia total','Ten 3 sinergias activas en el mazo a la vez',()=>synergies(S.deck.map(id=>CARD[id]).filter(Boolean)).length>=3,300],
 ['role3','🎭','Mazo temático','Juega con 3 cartas del mismo rol',()=>{const cs=S.deck.map(id=>CARD[id]).filter(Boolean);return cs.length===3&&new Set(cs.map(roleOf)).size===1},250],
 ['dir5','🧭','Alumno dirigido','Completa 5 sesiones dirigidas del Director',()=>tr('dir')>=5,400],
 ['fmt10','🎛️','Todos los formatos','Acierta 10 preguntas de cada formato: concepto, cálculo, tabla y código',()=>FMTS.every(f=>((S.fst||{})[f]||{c:0}).c>=10),500],
 ['card5','🃏','Botín de expedición','Consigue 5 cartas en expediciones',()=>tr('runCards')>=5,300]);

