WMT.push({k:'xpl',t:'Pide {g} explicaciones con 🦉',g:[5,8],rw:g=>g*40},{k:'petxp',t:'Tu compi gana {g} XP',g:[80,120],rw:g=>g*5},{k:'pet',t:'Dale mimos a tu compi {g} días',g:[4,6],rw:g=>g*60});
