const TL_normQ=normQ;
normQ=function(o){const q=TL_normQ(o);q.reason=String(o.reason||o.explicacion||q.sol||'');q.trap=String(o.trap||o.trampa||'');q.extraTime=Math.max(0,Number(o.extraTime)||0);return q};
const TL_makeGen=makeGen;
makeGen=function(g){const f=g.f;let data=null;g.f=function(){data=f();return data};try{const q=TL_makeGen(g);if(q){q.reason=String(data&&data.reason||q.sol||'');q.trap=String(data&&data.trap||g.trap||'');q.extraTime=Math.max(0,Number(data&&data.extraTime)||Number(g.extraTime)||0);if(g.dg)q.dg=1}return q}finally{g.f=f}};
function tlAddQuestions(){if(S.tlPlusQ>=1)return;const ids=new Set(S.qs.map(q=>q.id));let n=0;TL_MORE_QS.forEach(o=>{const q=normQ(o.ok==null?Object.assign({ok:0},o):o);if(!ids.has(q.id)){S.qs.push(q);ids.add(q.id);n++}});S.tlPlusQ=1;save();if(n)setTimeout(()=>toast(`📚 +${n} preguntas Telecom Legends`),1800)}
mergeBank=(old=>function(){tlAddQuestions();return old()})(mergeBank);
function tlIsCode(q){return /```/.test(q.q||'')}
function tlTrap(q){if(q.trap)return q.trap;const m=String(q.sol||'').match(/(?:error típico|trampa típica|ojo con|no confundas)\s*[:：]?\s*([^\n]+)/i);if(m)return m[1].trim();if(q.tabla)return 'Lee los encabezados y las unidades antes de operar; no mezcles magnitudes de filas distintas.';if(tlIsCode(q))return 'Traza el estado inicial, cada iteración y el efecto real de cada operador antes de leer la salida.';if(q.calc)return 'Comprueba prefijos, unidades y la magnitud que se pide antes de sustituir en la fórmula.';return 'Contrasta la definición con el concepto cercano y verifica qué condición concreta pide el enunciado.'}
const tlStyle=document.createElement('style');
tlStyle.textContent='.tl-time{font-size:12px;color:#c4b5fd;text-align:center;margin:3px 0 8px}#fb .sol:before{content:"💡 Explicación: ";font-weight:800}.tl-learn{margin-top:8px;padding:8px 10px;border:1px solid #a1620755;border-radius:9px;background:#2a2008;color:#fde68a;font-size:13px;line-height:1.45}.tl-tools{margin:8px 0}.tl-anomaly{margin:8px 0;padding:9px 11px;border:1px solid #38bdf866;border-radius:10px;background:#0c2438;color:#bae6fd}.tl-study{margin:8px 0}.exbar{display:flex;justify-content:space-between;gap:8px;align-items:center;background:linear-gradient(90deg,#172554,#1e1b4b);border:1px solid #60a5fa;border-radius:12px;padding:8px 12px;font-weight:800;margin-bottom:8px}.nota{font-family:"Russo One",sans-serif;font-size:46px;line-height:1.1;color:#fde047;text-shadow:0 0 18px rgba(250,204,21,.45)}.nota small{font-size:18px;color:#fde68a}';
document.head.appendChild(tlStyle);
const TL_play=VIEWS.play;
VIEWS.play=function(){TL_play();if(!M||route!=='play')return;const q=M.qs[M.i].q;let extra=Math.max(0,Number(q.extraTime)||0);if(!q.calc){if(q.tabla)extra+=6;if(tlIsCode(q))extra+=7;if((q.q||'').length>240)extra+=5;else if((q.q||'').length>150)extra+=3}extra=Math.min(18,extra);
 const original=M.tMax||0;if(!M.noTimer&&M.mode!=='blitz'&&M.mode!=='exam'&&extra){M.tMax+=extra;M.t+=extra}
 const base=DIFS[M.mode==='quick'?M.dif:q.dif].t;M.timeBase=base;M.timeExtra=M.tMax-base;const total=Math.ceil(M.tMax),change=total-base;
 const hint=document.createElement('div');hint.className='tl-time';hint.textContent=M.mode==='exam'?`Reloj de examen: ${clock(M.gt)} · se para al ver la corrección · sin escudos ni habilidades`:M.noTimer?'Estudio sin cronómetro · tómate el tiempo que necesites':M.mode==='blitz'?`Cronómetro global: ${Math.ceil(M.gt)} s · sin límite individual por pregunta`:`Tiempo base ${base} s ${change>=0?`+ ${change} s extra`:`− ${Math.abs(change)} s por efectos`} = ${total} s disponibles`;
 const timer=V.querySelector('.timer'),tag=V.querySelector('.tagq');if(timer)timer.insertAdjacentElement('afterend',hint);else if(tag)tag.insertAdjacentElement('afterend',hint);if(!M.noTimer&&M.mode!=='blitz'&&M.tMax!==original)updTimer()};
const TL_answer=answer;
answer=function(k){if(!M||M.ans!==null)return;if(M.mode==='exam')M.shields=0;const match=M,q=match.qs[match.i].q,before=match.res.length,started=match.t0;TL_answer(k);if(M&&M.mode==='exam')M.shields=0;if(M!==match||match.res.length===before)return;
 const result=match.res[match.res.length-1],fb=$('#fb');if(fb){const why=document.createElement('div');why.className='tl-learn';why.innerHTML=`<b>⚠️ Trampa típica:</b> ${fmt(tlTrap(q))}`;fb.insertBefore(why,fb.querySelector('.btn'))}
 if(result.ok&&!match.noTimer&&match.mode!=='blitz'&&match.tMax>0&&(Date.now()-started)/1000>=match.tMax*.75){const key=q.gen?'g|'+q.asig+'|'+q.tk:q.id,frag=S.tlFrag||(S.tlFrag={}),x=frag[key]||(frag[key]={n:0,d:0});x.n++;x.d=DAYN();x.last=q.q.slice(0,90);prog('fragile',1)}
 save()};
function tlFilter(q,status){if(status==='all')return true;const k=q.gen?'g|'+q.asig+'|'+q.tk:q.id,st=q.gen?(S.gst||{})[q.asig+'|'+q.tk]:(S.st||{})[q.id],sr=(S.sr||{})[k],frag=(S.tlFrag||{})[k];
 if(status==='failed')return !!(st&&(st.l===0||st.w>st.c));if(status==='pending')return !sr||sr.d<=DAYN();if(status==='fragile')return !!(frag&&frag.n>0&&frag.d>=DAYN()-14);return true}
function tlFilterQs(status,asig,tk){return S.qs.filter(q=>(!asig||asig==='ALL'||q.asig===asig)&&(!tk||q.tk===tk)&&tlFilter(q,status))}
FL.status=FL.status||'all';
flashNext=function(){const status=FL.status||'all',arr=tlFilterQs(status,FL.asig,FL.tk).filter(q=>!FL.q||q.id!==FL.q.id);const sc=q=>{const st=q.gen?(S.gst||{})[q.asig+'|'+q.tk]:(S.st||{})[q.id],sr=(S.sr||{})[q.gen?'g|'+q.asig+'|'+q.tk:q.id];return (st&&st.l===0?-10:0)+(sr&&sr.d<=DAYN()?-5:0)+(st?st.c-2*st.w:0)+Math.random()*.7};FL.q=arr.length?arr.map(q=>[sc(q),q]).sort((a,b)=>a[0]-b[0])[0][1]:null;FL.show=false};
function tlStartStudy(status){const qs=shuffle(tlFilterQs(status,FL.asig,FL.tk)).slice(0,12);if(!qs.length){toast('No hay preguntas con ese filtro y asignatura');return}startMatch({mode:'review',directed:true,srs:status==='pending',studyStatus:status,asig:FL.asig,qs,noTimer:true});toast(`📚 Práctica libre: ${qs.length} preguntas · sin cronómetro`)}
const TL_flash=VIEWS.flash;
VIEWS.flash=function(){TL_flash();const h=V.querySelector('h2');if(!h)return;const labels=[['all','Todas'],['failed','Falladas'],['pending','Pendientes'],['fragile','Frágiles']];const box=document.createElement('div');box.className='card-box tl-study';box.innerHTML=`<b>🎯 Filtro de práctica</b><div class=\"chips\">${labels.map(([k,n])=>`<button class=\"chip ${(FL.status||'all')===k?'on':''}\" onclick=\"FL.status='${k}';FL.q=null;render()\">${n} · ${tlFilterQs(k,FL.asig,FL.tk).length}</button>`).join('')}</div><button class=\"btn sec sm\" onclick=\"tlStartStudy('${FL.status||'all'}')\">Practicar este filtro sin reloj</button>`;h.insertAdjacentElement('afterend',box);
 const card=V.querySelector('.fcard');if(!FL.q&&card)card.innerHTML='<div class=\"mut\">No hay tarjetas que coincidan. Prueba otro filtro o asignatura.</div>';
 if(FL.q&&FL.show){const sol=card&&card.querySelector('.sol');if(sol){const t=document.createElement('div');t.className='tl-learn';t.innerHTML=`<b>⚠️ Trampa típica:</b> ${fmt(tlTrap(FL.q))}`;sol.insertAdjacentElement('afterend',t)}}};
const TL_diag=VIEWS.diag;
VIEWS.diag=function(){TL_diag();const h=V.querySelector('h2');if(!h)return;const ts=temaStats().filter(x=>x.c+x.w>=3).map(x=>({a:x.a.id,tk:x.t.tk,n:x.t.name,p:x.p,nq:x.c+x.w})),weak=ts.filter(x=>x.p<.6).sort((a,b)=>a.p-b.p).slice(0,4),strong=ts.filter(x=>x.p>=.8).sort((a,b)=>b.p-a.p).slice(0,4),frag=Object.values(S.tlFrag||{}).filter(x=>x.n&&x.d>=DAYN()-14).reduce((a,x)=>a+x.n,0);
 const card=document.createElement('div');card.className='card-box tl-study';card.innerHTML=`<b>🧠 Diagnóstico accionable</b><div class=\"mut\" style=\"margin-top:6px\">${frag?`${frag} aciertos recientes llegaron con menos del 25 % del tiempo: son conceptos frágiles.`:'Aún no hay aciertos registrados bajo presión; el filtro «Frágiles» aparecerá al practicar con reloj.'}</div><div class=\"grid2\" style=\"margin-top:8px\"><div><b style=\"color:#fca5a5\">Reforzar</b>${weak.length?weak.map(x=>`<div class=\"mut\">${ASIG[x.a].icon} ${esc(x.tk)} · ${Math.round(x.p*100)} % (${x.nq})</div>`).join(''):'<div class=\"mut\">Sin muestra débil suficiente.</div>'}</div><div><b style=\"color:#86efac\">Consolidado</b>${strong.length?strong.map(x=>`<div class=\"mut\">${ASIG[x.a].icon} ${esc(x.tk)} · ${Math.round(x.p*100)} % (${x.nq})</div>`).join(''):'<div class=\"mut\">Responde más preguntas para medir fortalezas.</div>'}</div></div><div class=\"row\" style=\"margin-top:8px\"><button class=\"btn sm sec\" onclick=\"FL.status='failed';FL.q=null;go('flash')\">Practicar falladas</button><button class=\"btn sm sec\" onclick=\"FL.status='fragile';FL.q=null;go('flash')\">Practicar frágiles</button></div>`;h.insertAdjacentElement('afterend',card)};
function tlSetAnomaly(r){if(!r)return;const all=[['fast','Reloj acelerado','−18 % tiempo · +30 % gemas al vencer'],['slow','Ventana extendida','+20 % tiempo · −10 % gemas al vencer'],['synced','Canal sincronizado','+20 XP de cartas al vencer']];const x=seeded('anomaly'+r.act+'_'+r.floor,()=>pk(all));r.anomaly={act:r.act,floor:r.floor,k:x[0],n:x[1],d:x[2],turns:2}}
const TL_runTime=runTime;
runTime=function(t){let x=TL_runTime(t),a=S.run&&S.run.anomaly;if(a&&a.turns>0&&a.act===S.run.act&&a.floor===S.run.floor){if(a.k==='fast')x*=.82;if(a.k==='slow')x*=1.2}return x};
startRun=(old=>function(){old();if(S.run){tlSetAnomaly(S.run);save();render()}})(startRun);
runAdvance=(old=>function(){const r=S.run,f=r&&r.floor;old();if(S.run&&S.run.floor!==f){tlSetAnomaly(S.run);save();render()}})(runAdvance);
runReward=(old=>function(k){const r=S.run,a=r&&r.act;old(k);if(S.run&&S.run.act!==a){tlSetAnomaly(S.run);save();render()}})(runReward);
const TL_runFight=runFight;
runFight=function(kind){TL_runFight(kind);if(M&&M.mode==='run'){M.overclockUsed=false;M.overclock=false}};
function tlOverclock(){if(!M||M.mode!=='run'||M.ans!==null||M.overclockUsed)return;const r=S.run;if(!r)return;if(M.shields>0){M.shields--;toast('🛡️ Gastas 1 escudo para sobrecargar.')}else if(r.hp>6){r.hp-=6;toast('⚠️ Sobrecarga: −6 PV de riesgo.')}else{toast('No puedes arriesgar más vida: busca un escudo.');return}M.overclockUsed=true;M.overclock=true;M.tacticalReward=true;save();drawQ()}
const TL_dmg=runDmg;
runDmg=function(){let d=TL_dmg();if(M&&M.overclock){M.overclock=false;return Math.round(d*1.7)}return d};
const TL_runAfter=runAfterMatch;
runAfterMatch=function(){const r=S.run,won=!!(M&&M.runWin),tactical=won&&M.tacticalReward,anom=r&&r.anomaly,challenge=r&&r.challenge;if(tactical&&r){r.gems+=8;giveDeckXP(20)}if(won&&r&&anom&&anom.act===r.act&&anom.floor===r.floor&&anom.k==='synced')giveDeckXP(20);
 TL_runAfter();if(won&&S.run===r&&challenge&&r.reward){const extra=challenge==='calc'||challenge==='code'?18:challenge==='tables'?15:12;r.gems+=extra;r.reward.gem=(r.reward.gem||0)+extra;r.reward.bonus=`🧭 Ruta ${NODES2[challenge].profile}: +${extra} gemas`}
 if(won&&S.run&&anom&&anom.act===S.run.act&&anom.floor===S.run.floor&&S.run.reward){if(anom.k==='fast'){const extra=Math.round((S.run.reward.gem||0)*.3);S.run.gems+=extra;S.run.reward.gem=(S.run.reward.gem||0)+extra;S.run.reward.bonus='⚡ Anomalía: +30 % gemas'}else if(anom.k==='slow'){const loss=Math.round((S.run.reward.gem||0)*.1);S.run.gems=Math.max(0,S.run.gems-loss);S.run.reward.gem=Math.max(0,(S.run.reward.gem||0)-loss);S.run.reward.bonus='🧘 Anomalía: −10 % gemas'}save();render()}};
runEnd=(old=>function(win){const r=S.run;if(r){const xp=(win?120:15)+(r.kills||0)*8+Math.max(0,r.floor-1)*3;S.xp=(S.xp||0)+xp;if(typeof petGain==='function')petGain(Math.max(1,Math.round(xp/10)));if(r.asig&&r.asig!=='ALL'){const m=S.runMastery||(S.runMastery={});m[r.asig]=(m[r.asig]||0)+(win?1:0)}save()}old(win)})(runEnd);
const TL_drawQ=drawQ;
drawQ=function(){TL_drawQ();if(!M||M.mode!=='run'||M.ans!==null||M.overclockUsed)return;const tools=V.querySelector('.tools');if(!tools)return;const b=document.createElement('button');b.type='button';b.className='tool tl-tools';b.textContent=M.shields>0?'⚡ Sobrecarga táctica · gasta 1 escudo → +70 % daño; victoria: +8 💎 y +20 XP de cartas':'⚡ Sobrecarga táctica · arriesga 6 PV → +70 % daño; victoria: +8 💎 y +20 XP de cartas';b.onclick=tlOverclock;tools.appendChild(b)};
const TL_runView=VIEWS.run;
VIEWS.run=function(){TL_runView();if(!V)return;const r=S.run;if(r&&r.anomaly){const h=V.querySelector('.actban');if(h)h.insertAdjacentHTML('afterend',`<div class=\"tl-anomaly\">⏳ Anomalía temporal · <b>${esc(r.anomaly.n)}</b><br><span class=\"mut\">${esc(r.anomaly.d)} · solo este piso</span></div>`)}else if(!r){const b=V.querySelector('button.btn.big');if(b){const rm=S.runMastery||{},counts=Object.keys(rm).filter(k=>rm[k]>0).map(k=>`${ASIG[k].icon} ${ASIG[k].name}: ${rm[k]} expedición${rm[k]===1?'':'es'}`),pet=typeof petState==='function'?petState():null,info=document.createElement('div');info.className='card-box tl-study';info.innerHTML=`<b>📈 Progreso entre expediciones</b><div class=\"mut\" style=\"margin-top:5px\">Cuenta XP de cartas durante la run, dominio por asignatura al completarla y XP para tu compi activo${pet&&PET[pet.act]?` (${esc(PET[pet.act].n)})`:''}.</div><div class=\"mut\" style=\"margin-top:5px\">${counts.length?counts.join(' · '):'Completa tu primera expedición para registrar maestría por asignatura.'}</div>`;b.insertAdjacentElement('beforebegin',info)}}};
const TL_anomalyView=VIEWS.run;
VIEWS.run=function(){TL_anomalyView();const a=S.run&&S.run.anomaly;if(a&&!Number.isFinite(a.turns)){a.turns=2;save()}const box=V&&V.querySelector('.tl-anomaly'),detail=box&&box.querySelector('.mut');if(!a||!box||!detail)return;box.classList.toggle('expired',a.turns<=0);detail.textContent=`${a.d} · ${a.turns>0?`Quedan ${a.turns} preguntas`:'La anomalía se disipó'}`};
const TL_routePreview=nodePreview;
nodePreview=function(id){const r=S.run,n=r&&r.map&&r.map.nodes[id];if(!r||!n||!ROUTE_CHALLENGES.includes(n.k))return TL_routePreview(id);const previous=r.challenge;r.challenge=n.k;try{return TL_routePreview(id)}finally{r.challenge=previous}};
const TL_anomalyAnswer=answer;
answer=function(k){const match=M,before=match&&match.res.length;TL_anomalyAnswer(k);if(!match||match.mode!=='run'||match.res.length===before)return;const r=S.run,a=r&&r.anomaly;if(a&&a.turns>0&&a.act===r.act&&a.floor===r.floor){a.turns--;if(a.turns===0)toast('La anomalía se disipa: el encuentro continúa en condiciones normales.');save()}};
const EX={asig:'ALL'};
function examBest(a){const n=S.exam&&S.exam[a];return n?Number(n):0}
function startExam(){const pred=q=>EX.asig==='ALL'||q.asig===EX.asig;const pool=S.qs.filter(pred);if(pool.length<4){toast('Hacen falta al menos 4 preguntas en este temario');return}
 const seen=new Set(),qs=[];[[1,2],[2,4],[3,3],[4,1]].forEach(([d,n])=>{pickQs(q=>pred(q)&&!seen.has(q.id),n,[d]).forEach(q=>{if(qs.length<10&&!seen.has(q.id)){seen.add(q.id);qs.push(q)}})});
 if(qs.length<10)pickQs(q=>pred(q)&&!seen.has(q.id),10-qs.length,[2,3,1,4]).forEach(q=>{if(qs.length<10&&!seen.has(q.id)){seen.add(q.id);qs.push(q)}});
 startMatch({mode:'exam',asig:EX.asig,qs:shuffle(qs).slice(0,10),gt:8*60,gtMax:8*60,dif:3})}
VIEWS.exam=()=>{const asigs=ASIGS.filter(a=>S.qs.some(q=>q.asig===a.id));if(EX.asig!=='ALL'&&!asigs.some(a=>a.id===EX.asig))EX.asig='ALL';
 const n=S.qs.filter(q=>EX.asig==='ALL'||q.asig===EX.asig).length,best=examBest(EX.asig);
 V.innerHTML=`<button class="lnk" onclick="go('home')">← Inicio</button><h2>📄 Simulacro de examen</h2>
 <div class="card-box"><b>Convocatoria de 10 preguntas</b><div class="mut" style="margin-top:6px">Tienes 8 minutos para el examen entero. El reloj se para mientras lees la corrección. No hay rival, escudos ni habilidades: la nota son los aciertos sobre 10 y se aprueba con un 5,0.</div><div class="mut" style="margin-top:6px">Teclas <b>1–4</b> o <b>A–D</b> para responder, e <b>Intro</b> para la siguiente.</div></div>
 <div class="mut">Asignatura</div><div class="chips">${chip('🔀 Convocatoria mixta',EX.asig==='ALL',"EX.asig='ALL';render()")}${asigs.map(a=>chip(a.icon+' '+esc(a.name),EX.asig===a.id,`EX.asig='${a.id}';render()`)).join('')}</div>
 <div class="grid2" style="margin-bottom:12px">${sbox('Preguntas listas',n)}${sbox('Mejor nota',best?best.toFixed(1)+' / 10':'—')}</div>
 <button class="btn big" ${n>=4?'':'disabled'} onclick="startExam()">📄 EMPEZAR SIMULACRO</button>
 ${n>=4?'':'<div class="mut" style="margin-top:8px">Hacen falta al menos 4 preguntas. Importa más desde Más → Importar.</div>'}
 ${S.examLast?`<div class="card-box"><b>Último intento</b><div class="mut">${esc(S.examLast.d)} · ${S.examLast.asig==='ALL'?'Mezcla':esc((ASIG[S.examLast.asig]||{}).name||S.examLast.asig)} · ${Number(S.examLast.nota).toFixed(1)} / 10 · ${S.examLast.c}/${S.examLast.n}</div></div>`:''}`};
ACH.push(['exam1','📄','Primera convocatoria','Aprueba un simulacro con un 5,0 o más',()=>Object.values(S.exam||{}).some(v=>Number(v)>=5),250],['exam9','🎓','Matrícula de honor','Saca un 9,0 o más en un simulacro',()=>Object.values(S.exam||{}).some(v=>Number(v)>=9),600]);
function init(){refreshCards();ensureMis();if(!S.v4){S.v4=1;S.chests=S.chests||[];addChest('g');setTimeout(()=>celebrate('🎁','¡Novedades!','Te regalamos un 🥇 Cofre de oro. Hay 45 cartas nuevas (11 ICON), cartas ✨ brillantes, cofres, Pase Telecom, maestrías por tema, preguntas doradas, títulos y jefes con barra de vida.'),600)}if(!S.seeded){S.qs=SAMPLE.map(normQ);S.seeded=true;save()}mergeBank();applyQFix();ensureDaily()}
window.addEventListener('load',()=>math($('#modal')));
/* v7 · Expedición: contratos de riesgo, tensión persistente y reliquias de emergencia */
Object.assign(RELICS,{
 ancla:{e:'⚓',n:'Ancla de emergencia',d:'Una vez por expedición, evita una muerte y te deja con 1 PV'},
 amort:{e:'🧱',n:'Amortiguador',d:'La tensión acumulada aumenta el daño recibido solo un 5 % por carga, en vez de un 12 %'},
 filo:{e:'🗡️',n:'Filo de última señal',d:'+25 % de daño cuando tienes 30 % de vida o menos'}
});
RCAT.def.push('ancla','amort');
RCAT.off.push('filo');
Object.assign(RUNMODS,{
 caceria:{e:'🩸',n:'Cacería',d:'Enemigos con +25 % de PV y +20 % de ataque',g:.45},
 escasez:{e:'🧪',n:'Escasez',d:'Empiezas sin botiquín; pociones y descanso curan la mitad',g:.35},
 sobrecarga:{e:'⚡',n:'Sobrecarga',d:'Cada fallo añade 2 cargas de tensión en vez de 1',g:.4}
});
const TL_pressureHTML=r=>{
 const pressure=Math.min(6,Math.max(0,Number(r&&r.pressure)||0));
 const increase=pressure*(hasR('amort')?.05:.12);
 return `<div class="tl-pressure${pressure>=4?' high':''}">⚠️ Tensión <b>${pressure}/6</b> · el siguiente fallo golpea ${Math.round(increase*100)} % más fuerte${hasR('amort')?' · amortiguador activo':''}</div>`;
};
const TL_anchorHTML=r=>r&&hasR('ancla')?`<div class="tl-anchor">⚓ Ancla ${r.anchorSpent?'consumida · no detendrá otro golpe':'lista · te salva una vez de un golpe letal'}</div>`:'';
const tlPressureStyle=document.createElement('style');
tlPressureStyle.textContent='.tl-pressure{margin:7px 0;padding:7px 10px;border:1px solid #f9731680;border-radius:9px;background:#30140c;color:#fdba74;font-size:12px;font-weight:700}.tl-pressure.high{border-color:#ef4444;background:#3b0a0a;color:#fecaca}.tl-anchor{margin:5px 0;padding:6px 9px;border:1px solid #38bdf866;border-radius:8px;background:#082f49;color:#bae6fd;font-size:12px}.tl-contract-note{margin-top:5px;font-size:12px;color:#fca5a5}';
document.head.appendChild(tlPressureStyle);
const TL_pressureStart=startRun;
startRun=function(){TL_pressureStart();const r=S.run;if(!r)return;r.pressure=0;r.anchorSpent=false;if(runMods().includes('escasez'))r.pots=[];save();render()};
const TL_pressureGo=runGo;
runGo=function(id){
 const r=S.run,n=r&&r.map&&r.map.nodes[id],e=n&&n.en;
 if(e&&runMods().includes('caceria')&&!e.tlHuntScaled){e.maxhp=Math.round(e.maxhp*1.25);e.hp=e.maxhp;e.atk=Math.round(e.atk*1.2);e.tlHuntScaled=true}
 TL_pressureGo(id);
};
const TL_pressureAnswer=runOnAnswer;
runOnAnswer=function(good,saved){
 const r=S.run,E=r&&r.enemy;
 if(!r||!E)return TL_pressureAnswer(good,saved);
 const attack=E.atk,pressure=Math.min(6,Math.max(0,Number(r.pressure)||0));
 const multiplier=1+pressure*(hasR('amort')?.05:.12);
 E.atk=Math.ceil(attack*multiplier);
 TL_pressureAnswer(good,saved);
 if(S.run!==r||r.enemy!==E)return;
 const growth=Math.max(0,E.atk-Math.ceil(attack*multiplier));
 E.atk=attack+growth;
 if(!good&&!saved){
  r.pressure=Math.min(6,pressure+1+(runMods().includes('sobrecarga')?1:0));
  if(r.pressure>pressure)floatTxt(`⚠️ Tensión ${r.pressure}/6`,'#fb923c',350);
 }
 if(r.hp<=0&&E.hp>0&&hasR('ancla')&&!r.anchorSpent){
  r.hp=1;r.anchorSpent=true;M.over=false;M.runWin=false;
  floatTxt('⚓ El ancla te salva · 1 PV','#7dd3fc');toast('El Ancla de emergencia se ha consumido.');
 }
 updRunUI();save();
};
const TL_pressureDamage=runDmg;
runDmg=function(){let damage=TL_pressureDamage();const r=S.run;if(r&&hasR('filo')&&r.hp/r.maxhp<=.3)damage=Math.round(damage*1.25);return damage};
const TL_pressureRisk=nodeRisk;
nodeRisk=function(n){
 const result=TL_pressureRisk(n);
 if(!result||!n||!n.en||n.en.tlHuntScaled||!runMods().includes('caceria'))return result;
 result.hp=Math.round(result.hp*1.25);result.exp=Math.round(result.exp*1.5);
 const ratio=result.exp/Math.max(1,S.run.hp);result.lv=ratio<.25?0:ratio<.6?1:2;
 return result;
};
const TL_pressureRest=runRest;
runRest=function(k){
 const r=S.run;
 if(k==='breathe'&&r){const cleared=r.pressure||0;r.pressure=0;r.hp=Math.min(r.maxhp,r.hp+8);r.rest=null;save();toast(`🫁 Recuperas 8 PV y eliminas ${cleared} cargas de tensión.`);runAdvance();return}
 if(k==='heal'&&r&&runMods().includes('escasez')){
  const before=r.hp;TL_pressureRest(k);const healed=r.hp-before;r.hp=before+Math.ceil(Math.max(0,healed)*.5);save();render();return
 }
 TL_pressureRest(k);
};
const TL_pressurePotion=usePot;
usePot=function(i){
 const r=S.run,k=r&&r.pots[i],before=r&&r.hp;
 TL_pressurePotion(i);
 if(r&&k==='botiquin'&&runMods().includes('escasez')){const healed=r.hp-before;r.hp=before+Math.ceil(Math.max(0,healed)*.5);updRunUI();save()}
};
const TL_pressureReward=runReward;
runReward=function(k){
 const r=S.run,before=r&&r.hp;
 TL_pressureReward(k);
 if(r&&k==='heal'&&runMods().includes('escasez')){const healed=r.hp-before;r.hp=before+Math.ceil(Math.max(0,healed)*.5);save();render()}
};
const TL_pressureRunBar=runBar;
runBar=function(){const r=S.run,html=TL_pressureRunBar();return r&&html?html+TL_pressureHTML(r)+TL_anchorHTML(r):html};
const TL_pressureUpdate=updRunUI;
updRunUI=function(){
 TL_pressureUpdate();
 const r=S.run;if(!r||!V)return;
 V.querySelectorAll('.tl-pressure').forEach(el=>{
  const pressure=Math.min(6,Math.max(0,Number(r.pressure)||0)),increase=pressure*(hasR('amort')?.05:.12);
  el.classList.toggle('high',pressure>=4);
  el.innerHTML=`⚠️ Tensión <b>${pressure}/6</b> · el siguiente fallo golpea ${Math.round(increase*100)} % más fuerte${hasR('amort')?' · amortiguador activo':''}`;
 });
};
const TL_pressureOverclock=tlOverclock;
tlOverclock=function(){const hp=S.run&&S.run.hp;TL_pressureOverclock();if(S.run&&S.run.hp!==hp)updRunUI()};
const TL_pressureRunView=VIEWS.run;
VIEWS.run=function(){
 TL_pressureRunView();
 const r=S.run;if(!V)return;
 if(!r){
  const intro=V.querySelector('.acts')&&V.querySelector('.acts').nextElementSibling;
  if(intro)intro.insertAdjacentHTML('beforeend','<div class="tl-contract-note">Los fallos sin escudo generan tensión: cada carga hace más peligroso el siguiente golpe. Purga tensión en las hogueras. Si tus PV llegan a cero, la expedición termina.</div>');
  return;
 }
 const hp=V.querySelector('.hpb.me.big');
 if(hp)hp.insertAdjacentHTML('afterend',TL_pressureHTML(r)+TL_anchorHTML(r));
 if(r.rest){
  const restButtons=V.querySelectorAll('.menu[onclick^="runRest("]');
  const last=restButtons[restButtons.length-1];
  if(last)last.insertAdjacentHTML('afterend',`<button class="menu" onclick="runRest('breathe')"><span>🫁</span><div><b>Recuperar el aliento</b><small>+8 PV y elimina ${r.pressure||0}/6 cargas de tensión</small></div><i>›</i></button>`);
 }
};

/* ====== Proyecto Horizonte · investigación y mutaciones ====== */
const MUTATIONS={
 bulwark:{n:'Bastión',e:'🛡️',d:'Al entrar en cada combate de expedición, concede +1 escudo.'},
 resonance:{n:'Resonante',e:'📡',d:'Inflige +18 % de daño en preguntas de su asignatura (o todas, si es universal).'},
 symbiote:{n:'Simbionte',e:'🧬',d:'La primera respuesta correcta de cada combate da +5 gemas y +20 XP al mazo.'}
};
const TL_LAB_STEP=100,TL_LAB_REWARDS=[
 {n:'Sobre de Especialidad',e:'📡',d:'1 sobre de Especialidad'},
 {n:'Catalizador mutágeno',e:'🧬',d:'1 catalizador'},
 {n:'Sobre Mutágeno',e:'🧪',d:'1 sobre Mutágeno'},
 {n:'Polvo de señal',e:'✨',d:'+120 polvo'},
 {n:'Sobre Premium',e:'✨',d:'1 sobre Premium'},
 {n:'Sobre de Especialidad',e:'📡',d:'1 sobre de Especialidad'},
 {n:'Catalizadores mutágenos',e:'🧬',d:'2 catalizadores'},
 {n:'Sobre ICON',e:'👑',d:'1 sobre ICON'}
];
function tlLabLevel(){return Math.floor((S.labXp||0)/TL_LAB_STEP)}
function tlLabReward(tier){return TL_LAB_REWARDS[(tier-1)%TL_LAB_REWARDS.length]}
function tlLabAdd(points){if(points<=0)return;S.labXp=(S.labXp||0)+points;save()}
function tlLabClaim(tier){
 S.labClaimed=Array.isArray(S.labClaimed)?S.labClaimed:[];
 if(tier<1||tier>tlLabLevel()||S.labClaimed.includes(tier))return;
 switch((tier-1)%TL_LAB_REWARDS.length){
  case 0:S.inv.themed=(S.inv.themed||0)+1;break;
  case 1:S.mutagen=(S.mutagen||0)+1;break;
  case 2:S.inv.mutation=(S.inv.mutation||0)+1;break;
  case 3:S.dust=(S.dust||0)+120;break;
  case 4:S.inv.premium=(S.inv.premium||0)+1;break;
  case 5:S.inv.themed=(S.inv.themed||0)+1;break;
  case 6:S.mutagen=(S.mutagen||0)+2;break;
  case 7:S.iconPacks=(S.iconPacks||0)+1;break;
 }
 S.labClaimed.push(tier);save();sfx('gold');toast(`🔬 Horizonte · nivel ${tier}: ${tlLabReward(tier).d}`);render();
}
VIEWS.lab=()=>{
 const level=tlLabLevel(),claimed=Array.isArray(S.labClaimed)?S.labClaimed:[],start=Math.max(1,level-2),end=Math.max(8,level+3);
 const ownedMutations=CARDS.filter(c=>S.cards[c.id]&&S.cards[c.id].mut).length,active=claimed.filter(t=>t<=level).length;
 V.innerHTML=`<button class="lnk" onclick="go('home')">← Inicio</button><h2>🔬 Proyecto Horizonte</h2>
 <div class="card-box"><div class="rowb"><b>Investigación · nivel ${level}</b><span class="mut">${S.labXp||0} puntos</span></div><div class="xpbar"><i style="width:${(S.labXp||0)%TL_LAB_STEP}%"></i></div><div class="mut">${(S.labXp||0)%TL_LAB_STEP}/${TL_LAB_STEP} puntos para el siguiente protocolo. Acierta preguntas (+1, +1 extra en dificultad alta) y completa expediciones para avanzar.</div><div class="chips"><span class="chip">🧬 ${S.mutagen||0} catalizadores</span><span class="chip">🧪 ${ownedMutations} cartas mutadas</span><span class="chip">🎁 ${active} protocolos cobrados</span></div></div>
 <div class="card-box"><b>Un motivo para volver</b><div class="mut">El laboratorio no tiene límite de nivel: cada protocolo abre una recompensa nueva. Cada expedición da 15 puntos, +4 por baja y +60 por victoria; alterna asignaturas con sobres de Especialidad, consigue catalizadores y prepara mutaciones para los jefes.</div></div>
 <h3>Protocolos</h3>${Array.from({length:end-start+1},(_,i)=>start+i).map(t=>{const done=claimed.includes(t),ready=t<=level&&!done,r=tlLabReward(t);return `<div class="menu"><span>${done?'✅':ready?'🔬':r.e}</span><div><b>Nivel ${t} · ${esc(r.n)}</b><small>${esc(r.d)} · ${done?'reclamado':ready?'listo para reclamar':`${Math.max(0,t*TL_LAB_STEP-(S.labXp||0))} pts restantes`}</small></div>${ready?`<button class="btn gold sm" onclick="tlLabClaim(${t})">Cobrar</button>`:'<i>›</i>'}</div>`}).join('')}
 <button class="btn sec" style="margin-top:12px" onclick="go('packs')">🎁 Ir a Sobres</button><button class="btn sec" style="margin:12px 0 0 8px" onclick="go('album')">🃏 Mutar cartas en el Álbum</button>`;
};
const TL_labAnswer=answer;
answer=function(k){
 const current=M,before=current?current.res.length:0,q=current&&current.qs[current.i]?current.qs[current.i].q:null;
 TL_labAnswer(k);
 if(!current||!current.res||current.res.length<=before)return;
 const result=current.res[current.res.length-1];
 if(result.ok)tlLabAdd(1+(q&&q.dif>=3?1:0));
};
const TL_labRunEnd=runEnd;
runEnd=function(win){
 const r=S.run;if(r&&!r.labPaid){r.labPaid=true;tlLabAdd(15+(r.kills||0)*4+(win?60:0))}
 TL_labRunEnd(win);
};
const TL_labHome=VIEWS.home;
VIEWS.home=function(){TL_labHome();if(!V)return;const hero=V.querySelector('.hero');if(hero)hero.insertAdjacentHTML('afterend',`<button class="card-box" style="width:100%;text-align:left;cursor:pointer;margin:0 0 12px" onclick="go('lab')"><div class="rowb"><b>🔬 Proyecto Horizonte · Nv ${tlLabLevel()}</b><span class="mut">${(S.labXp||0)%TL_LAB_STEP}/${TL_LAB_STEP} pts</span></div><div class="xpbar"><i style="width:${(S.labXp||0)%TL_LAB_STEP}%"></i></div><div class="mut">${S.labXp||0} puntos de investigación · ${Math.max(0,tlLabLevel()-(Array.isArray(S.labClaimed)?S.labClaimed.length:0))} recompensas por cobrar · ${S.mutagen||0} catalizadores</div></button>`)};
const TL_labMore=VIEWS.more;
VIEWS.more=function(){TL_labMore();if(V)V.insertAdjacentHTML('beforeend',`<button class="menu" onclick="go('lab')"><span>🔬</span><div><b>Proyecto Horizonte</b><small>Progreso permanente, sobres y mutaciones</small></div><i>›</i></button>`)};
const TL_cardHTMLMutation=cardHTML;
cardHTML=function(c,o={}){
 const html=TL_cardHTMLMutation(c,o),owned=S.cards[c.id],m=owned&&owned.mut&&MUTATIONS[owned.mut];
 return m&&!o.locked?html.replace(/(<div class="gcard[^"]*"[^>]*>)/,`$1<i class="mutation-mark" title="${esc(m.n)}">${m.e}</i>`):html;
};
const TL_cardDetailMutation=cardDetail;
cardDetail=function(id){
 TL_cardDetailMutation(id);
 const o=S.cards[id],c=CARD[id],box=$('#modal .mbox');if(!o||!c||!box)return;
 const need=o.mut?'':`<div class="mut" style="margin:6px 0">Coste: 1 copia repetida y 1 catalizador. La mutación es permanente y solo activa su efecto si la carta está en tu mazo.</div>`;
 box.insertAdjacentHTML('beforeend',`<div class="card-box" style="margin-top:12px"><b>🧬 Mutación ${o.mut?`· ${esc(MUTATIONS[o.mut].n)}`:''}</b>${o.mut?`<div class="mut">${MUTATIONS[o.mut].e} ${esc(MUTATIONS[o.mut].d)}</div>`:`${need}<div class="mut">Tienes ${o.n-1} copias extra y ${S.mutagen||0} catalizadores.</div><div class="grid2" style="margin-top:8px">${Object.entries(MUTATIONS).map(([k,m])=>`<button class="btn sec" onclick="mutateCard('${id}','${k}')" ${o.n>1&&(S.mutagen||0)>0?'':'disabled'}>${m.e} ${esc(m.n)}<small style="display:block">${esc(m.d)}</small></button>`).join('')}</div>`}</div>`);
};
function mutateCard(id,type){
 const o=S.cards[id],m=MUTATIONS[type];if(!o||!m||o.mut)return;
 if(o.n<2){toast('Necesitas una copia repetida de esta carta');return}
 if((S.mutagen||0)<1){toast('Te falta un catalizador: avanza en Horizonte o abre un Sobre Mutágeno');return}
 o.n--;S.mutagen--;o.mut=type;save();sfx('gold');closeModal();render();cardDetail(id);toast(`🧬 ${m.n}: mutación aplicada`);
}
function tlMutatedDeck(){return S.deck.map(id=>({c:CARD[id],o:S.cards[id]})).filter(x=>x.c&&x.o&&x.o.mut&&MUTATIONS[x.o.mut])}
const TL_mutationFight=runFight;
runFight=function(kind){
 TL_mutationFight(kind);
 if(!M||M.mode!=='run')return;
 const bulwarks=tlMutatedDeck().filter(x=>x.o.mut==='bulwark').length;
 M.mutationRewarded=false;
 if(bulwarks){M.shields=(M.shields||0)+bulwarks;toast(`🧬 Bastión: +${bulwarks} escudo${bulwarks===1?'':'s'}`)}
};
const TL_mutationDamage=runDmg;
runDmg=function(){
 let damage=TL_mutationDamage();
 const entry=M&&M.qs&&M.qs[M.i],q=entry&&entry.q,asig=q&&q.asig;
 if(M&&M.mode==='run'&&asig&&tlMutatedDeck().some(x=>x.o.mut==='resonance'&&(x.c.a==='ALL'||x.c.a===asig)))damage=Math.round(damage*1.18);
 return damage;
};
const TL_mutationAnswer=runOnAnswer;
runOnAnswer=function(good,saved){
 TL_mutationAnswer(good,saved);
 if(!good||!M||M.mode!=='run'||M.mutationRewarded)return;
 if(tlMutatedDeck().some(x=>x.o.mut==='symbiote')){
  M.mutationRewarded=true;if(S.run)S.run.gems=(S.run.gems||0)+5;giveDeckXP(20);
  if(typeof updRunUI==='function')updRunUI();toast('🧬 Simbionte: +5 gemas y +20 XP al mazo');
 }
};

