function tlSetAnomaly(r){
 if(!r)return;
 const all=[
  ['fast','Reloj acelerado','−18 % tiempo · +30 % gemas al vencer'],
  ['slow','Ventana extendida','+20 % tiempo · −10 % gemas al vencer'],
  ['synced','Canal sincronizado','+20 XP de cartas al vencer'],
  ['fade','Desvanecimiento','−15 % tiempo · los fallos sin escudo suman tensión'],
  ['congestion','Congestión','−15 % daño · +25 % gemas al vencer'],
  ['thermal','Ruido térmico','+10 % tiempo · los fallos sin escudo suman tensión'],
  ['window','Ventana óptima','aciertos rápidos hacen +25 % daño']
 ];
 const x=seeded('anomaly'+r.act+'_'+r.floor,()=>pk(all));
 r.anomaly={act:r.act,floor:r.floor,k:x[0],n:x[1],d:x[2],turns:2};
}
const TL_signalRunTime=runTime;
runTime=function(t){
 let x=TL_signalRunTime(t);const a=S.run&&S.run.anomaly;
 if(a&&a.turns>0&&a.act===S.run.act&&a.floor===S.run.floor){
  if(a.k==='fade')x*=.85;
  if(a.k==='thermal')x*=1.1;
 }
 return x;
};
const TL_signalStartRun=startRun;
startRun=function(){
 TL_signalStartRun();const r=S.run;
 if(r){r.modifiers=[...new Set(runMods())];r.clearedNodes=0;r.clearedNodeIds=[];r.mutatedUsed=[];save()}
};
function tlRecordRunNode(r){
 if(!r||r.pos==null)return;
 const id=`${r.act}:${r.pos}`,seen=r.clearedNodeIds||(r.clearedNodeIds=[]);
 if(seen.includes(id))return;
 seen.push(id);r.clearedNodes=(r.clearedNodes||0)+1;
}
function tlRecordMutations(r,types){
 if(!r)return;
 const ids=r.mutatedUsed||(r.mutatedUsed=[]);
 tlMutatedDeck().filter(x=>types.includes(x.o.mut)).forEach(x=>{if(!ids.includes(x.c.id))ids.push(x.c.id)});
}
const TL_signalFight=runFight;
runFight=function(kind){
 TL_signalFight(kind);
 if(!M||M.mode!=='run'||!S.run)return;
 const r=S.run,mut=tlMutatedDeck().filter(x=>x.o.mut==='bulwark');
 M.signalBetArmed=false;M.signalBetUsed=false;
 if(mut.length){
  tlRecordMutations(r,['bulwark']);
  if(runMods().some(x=>x==='caceria'||x==='sobrecarga'))r.pressure=Math.max(0,(r.pressure||0)-1);
 }
};
const TL_signalOverclock=tlOverclock;
tlOverclock=function(){
 const match=M;
 TL_signalOverclock();
 if(match&&M===match&&match.mode==='run'&&match.overclockUsed){
  match.signalBetArmed=true;match.signalBetUsed=true;match.tacticalReward=false;drawQ();
 }
};
const TL_signalDamage=runDmg;
runDmg=function(){
 let damage=TL_signalDamage();const match=M,r=S.run,a=r&&r.anomaly;
 if(!match||match.mode!=='run'||!r)return damage;
 const q=match.qs[match.i]&&match.qs[match.i].q,asig=q&&q.asig;
 const resonant=asig&&tlMutatedDeck().filter(x=>x.o.mut==='resonance'&&(x.c.a==='ALL'||x.c.a===asig));
 if(resonant&&resonant.length){tlRecordMutations(r,['resonance'])}
 else if(a&&a.turns>0&&a.k==='congestion'&&a.floor===r.floor)damage=Math.round(damage*.85);
 if(match.signalBetArmed&&match.t/Math.max(1,match.tMax)>=.5)damage=Math.round(damage*1.25);
 if(a&&a.turns>0&&a.k==='window'&&match.t/Math.max(1,match.tMax)>.66)damage=Math.round(damage*1.25);
 return damage;
};
const TL_signalAnswer=answer;
answer=function(k){
 const match=M,before=match&&match.res.length,wasMutationRewarded=!!(match&&match.mutationRewarded);
 const activeAnomaly=!!(match&&match.mode==='run'&&S.run&&S.run.anomaly&&S.run.anomaly.turns>0&&S.run.anomaly.floor===S.run.floor),anomaly=activeAnomaly&&S.run.anomaly;
 TL_signalAnswer(k);
 if(!match||match.mode!=='run'||!match.res||match.res.length===before)return;
 const result=match.res[match.res.length-1],r=S.run,a=anomaly;
 if(!r)return;
 const quick=!match.noTimer&&match.mode!=='blitz'&&match.tMax>0&&result.t<=match.tMax*.5;
 if(match.signalBetArmed){
  match.signalBetArmed=false;
  if(result.ok&&quick){match.tacticalReward=true;toast('📡 Apuesta ganada: golpe reforzado · +8 💎 y +20 XP al vencer')}
  else if(!result.ok&&!result.saved){r.pressure=Math.min(6,(r.pressure||0)+1);toast('📡 La apuesta falla: +1 tensión')}
 }
 if(activeAnomaly&&a&&a.floor===r.floor&&!result.ok&&!result.saved&&(a.k==='fade'||a.k==='thermal')){
  r.pressure=Math.min(6,(r.pressure||0)+1);
  toast(a.k==='fade'?'🌫️ Desvanecimiento: +1 tensión':'♨️ Ruido térmico: +1 tensión');
 }
 const mutated=tlMutatedDeck();
 if(result.ok&&!wasMutationRewarded&&match.mutationRewarded&&mutated.some(x=>x.o.mut==='symbiote')){
  tlRecordMutations(r,['symbiote']);
  if(runMods().includes('sobrecarga'))r.pressure=Math.max(0,(r.pressure||0)-1);
  if(runMods().includes('escasez')&&r.pots.length<potMax()){addPot('botiquin');toast('🧬 Simbionte y Escasez: +1 botiquín')}
 }
 if(result.ok&&quick&&activeAnomaly&&a&&a.floor===r.floor&&a.k==='window'){r.gems+=5;toast('🪟 Ventana óptima: +5 💎')}
 const anomalyBox=V.querySelector('.tl-live-anomaly');
 if(anomalyBox&&a)anomalyBox.textContent=`📡 ${a.n} · ${a.d} · ${a.turns>0?`quedan ${a.turns} preguntas`:'se disipó'}`;
 if(!match.runWin&&!result.ok&&!result.saved&&r.hp>0)save();
 updRunUI();
};
const TL_signalRunAfter=runAfterMatch;
runAfterMatch=function(){
 const r=S.run,won=!!(M&&M.mode==='run'&&M.runWin),a=r&&r.anomaly;
 if(won&&r&&a&&a.act===r.act&&a.floor===r.floor&&a.k==='congestion'){
  const bonus=Math.round((8+r.act*3)*.25);r.gems+=bonus;toast(`📡 Congestión superada: +${bonus} 💎`);
 }
 if(won&&r)tlRecordRunNode(r);
 TL_signalRunAfter();
};
const TL_signalAdvance=runAdvance;
runAdvance=function(){tlRecordRunNode(S.run);TL_signalAdvance()};
const TL_signalReward=runReward;
runReward=function(k){
 const r=S.run;if(r&&r.reward&&r.reward.boss)tlRecordRunNode(r);
 TL_signalReward(k);
};
const TL_signalEnd=runEnd;
runEnd=function(win){
 const r=S.run;
 if(r&&!r.horizonRunPaid){
  r.horizonRunPaid=true;
  const completedNodes=r.clearedNodes||0,modifiers=[...new Set(r.modifiers||runMods())].length,mutations=(r.mutatedUsed||[]).length;
  const bonus=completedNodes*2+modifiers*8+mutations*6+(win?12:0),base=r.labPaid?0:15+(r.kills||0)*4+(win?60:0);
  r.horizonPointsEarned=bonus+base;tlLabAdd(bonus);toast(`🔬 Proyecto Horizonte: +${r.horizonPointsEarned} puntos de investigación`);
 }
 TL_signalEnd(win);
};
const TL_signalRunView=VIEWS.run;
VIEWS.run=function(){
 TL_signalRunView();
 const r=S.run;if(!V)return;
 if(!r){
  const intro=V.querySelector('.acts')&&V.querySelector('.acts').nextElementSibling;
  if(intro&&!intro.querySelector('.tl-signal-guide'))intro.insertAdjacentHTML('beforeend','<div class="tl-signal-guide tl-live-anomaly">📡 Durante la expedición aparecen anomalías de canal de 2 preguntas. En combate puedes apostar una vez: consume 1 escudo o 6 PV; el golpe gana daño y un acierto rápido mejora la recompensa, pero fallar sin escudo añade tensión.</div>');
  return;
 }
 const target=V.querySelector('.tl-anomaly');
 if(r.anomaly&&target)target.innerHTML=`📡 Anomalía · <b>${esc(r.anomaly.n)}</b><br><span class="mut">${esc(r.anomaly.d)} · ${r.anomaly.turns>0?`quedan ${r.anomaly.turns} preguntas`:'se disipó'}</span>`;
 const hp=V.querySelector('.hpb.me.big');
 if(hp&&!V.querySelector('.tl-horizon-run'))hp.insertAdjacentHTML('afterend',`<div class="tl-horizon-run">🔬 Horizonte registrará ${r.clearedNodes||0} nodos, ${[...new Set(r.modifiers||[])].length} modificadores y ${(r.mutatedUsed||[]).length} cartas mutadas usadas al cerrar la expedición.</div>`);
};
const TL_signalDrawQ=drawQ;
drawQ=function(){
 TL_signalDrawQ();
 if(!M||M.mode!=='run')return;
 const r=S.run,a=r&&r.anomaly;
 if(a&&a.turns>0&&a.act===r.act&&a.floor===r.floor){
  const enemy=V.querySelector('.enemy');
  if(enemy)enemy.insertAdjacentHTML('afterend',`<div class="tl-live-anomaly">📡 ${esc(a.n)} · ${esc(a.d)} · quedan ${a.turns} preguntas</div>`);
 }
 const tools=V.querySelector('.tools');if(!tools)return;
 const button=[...tools.querySelectorAll('button')].find(b=>b.classList.contains('tl-tools'));
 if(button)button.textContent=M.shields>0?'📡 Apuesta de señal · gasta 1 escudo · +70 % daño; acierto rápido: +25 % y botín':'📡 Apuesta de señal · arriesga 6 PV · +70 % daño; acierto rápido: +25 % y botín';
 if(M.signalBetArmed)tools.insertAdjacentHTML('beforeend','<div class="tl-signal">📡 Apuesta activa · el golpe mejora un 25 % más si aciertas con al menos la mitad del tiempo. Si fallas sin escudo, ganas 1 carga de tensión.</div>');
};
const TL_labViewSignal=VIEWS.lab;
VIEWS.lab=function(){
 TL_labViewSignal();
 const copy=V&&[...V.querySelectorAll('.card-box')].find(x=>x.textContent.includes('Un motivo para volver'));
 if(copy)copy.querySelector('.mut').textContent='El laboratorio no tiene límite de nivel. Cada acierto da investigación; cada expedición añade progreso por nodos superados (+2), modificadores activos (+8 cada uno), cartas mutadas usadas (+6 cada una) y victoria (+12), además de la recompensa base por bajas y completar.';
};

