const TL_RARITY_ORDER=['T','C','M','I','O','P','B'];
rollR=function(kind){
 const weights=(PACKS[kind]||PACKS.normal).o,roll=Math.random();let edge=0;
 for(const r of TL_RARITY_ORDER){edge+=weights[r]||0;if(roll<edge)return r}
 return 'B'
};
const TL_grantCards=grantCards;
grantCards=function(n,kind,forceI,asig){
 const got=[];let pity=S.pity||0,hitPity=false;
 for(let i=0;i<n;i++){
  const pityHit=!forceI&&pity>=119,r=(forceI&&i===0)||pityHit?'I':rollR(kind);
  if(pityHit)hitPity=true;
  let pool=CARDS.filter(c=>c.r===r&&(!asig||c.a===asig||c.a==='ALL'));
  if(!pool.length)pool=CARDS.filter(c=>c.r===r);
  if(!pool.length)pool=CARDS.filter(c=>c.r==='B');
  got.push(rnd(pool));pity=got[i].r==='I'?0:pity+1
 }
 if(hitPity)setTimeout(()=>toast('★ ¡ICON garantizada tras 120 cartas sin ICON!'),400);
 S.pity=pity;
 const shp=kind==='premium'||kind==='themed'?.07:kind==='mutation'?.08:.04;
 const info=got.map(c=>{const had=!!S.cards[c.id];if(had)S.cards[c.id].n++;else S.cards[c.id]={n:1,l:1};const sh=Math.random()<shp;if(sh)S.cards[c.id].sh=1;return{c,isNew:!had,sh}});
 info.forEach(({c})=>{if(S.deck.length<3&&!S.deck.includes(c.id))S.deck.push(c.id)});
 return info.sort((a,b)=>RORD[a.c.r]-RORD[b.c.r])
};

const TL_ADV_FUSION={M:{to:'C',need:6,coins:650},C:{to:'T',need:5,coins:1200}};
function tlFuseAdvanced(from){
 const rule=TL_ADV_FUSION[from];if(!rule)return;
 let need=rule.need;const copies=CARDS.filter(c=>c.r===from&&S.cards[c.id]&&S.cards[c.id].n>1).sort((a,b)=>S.cards[b.id].n-S.cards[a.id].n);
 const total=copies.reduce((sum,c)=>sum+S.cards[c.id].n-1,0);
 if(total<need||S.coins<rule.coins){toast(`Se necesitan ${rule.need} repetidas ${RN[from]} y ${rule.coins} 🪙`);return}
 for(const c of copies){const take=Math.min(need,S.cards[c.id].n-1);S.cards[c.id].n-=take;need-=take;if(!need)break}
 S.coins-=rule.coins;const miss=CARDS.filter(c=>c.r===rule.to&&!S.cards[c.id]),pool=miss.length?miss:CARDS.filter(c=>c.r===rule.to),c=rnd(pool),had=!!S.cards[c.id];
 if(had)S.cards[c.id].n++;else S.cards[c.id]={n:1,l:1};
 save();sfx('gold');showOpening([{c,isNew:!had,sh:false}],{n:`🔮 Fusión ${RN[from]} → ${RN[rule.to]}`});renderTop()
}
const TL_workshopRarity=workshop;
workshop=function(){
 TL_workshopRarity();const box=$('#modal .mbox');if(!box)return;
 const rows=Object.entries(TL_ADV_FUSION).map(([from,x])=>{const n=CARDS.filter(c=>c.r===from&&S.cards[c.id]).reduce((s,c)=>s+S.cards[c.id].n-1,0);return `<button class="btn sec" style="margin:5px" ${n>=x.need&&S.coins>=x.coins?'':'disabled'} onclick="tlFuseAdvanced('${from}')">🔮 ${x.need} repetidas ${RN[from]} → ${RN[x.to]} · ${x.coins} 🪙 <small>(tienes ${n})</small></button>`}).join('');
 box.insertAdjacentHTML('beforeend',`<div class="card-box"><b>Ascenso de rareza</b><div class="mut">Ruta independiente de la fusión clásica: consume repetidas y monedas; no transforma cartas ICON.</div>${rows}</div>`)
};
const TL_cardFormRarity=cardForm;
cardForm=function(){
 TL_cardFormRarity();const select=$('#cf-r');if(!select)return;
 [['M','Mítica'],['C','Cósmica'],['T','Prototipo']].forEach(([v,n])=>select.add(new Option(n,v)));
 select.onchange=()=>$('#cf-abw').classList.toggle('hidden',select.value!=='I')
};
let TL_RAR_FILTER='ALL';
const TL_albumRarity=VIEWS.album;
VIEWS.album=function(){
 TL_albumRarity();if(!V)return;const chips=V.querySelector('.chips'),grid=V.querySelector('.grid3');if(!chips||!grid)return;
 const filters=['ALL','B','P','O','I','M','C','T'];
 chips.insertAdjacentHTML('beforeend',filters.map(r=>`<button class="chip ${TL_RAR_FILTER===r?'on':''}" onclick="TL_RAR_FILTER='${r}';render()">${r==='ALL'?'Todas las rarezas':RN[r]}</button>`).join(''));
 const list=CARDS.filter(c=>(AF==='ALL'||(AF==='I'?c.r==='I':c.a===AF))&&(TL_RAR_FILTER==='ALL'||c.r===TL_RAR_FILTER)).sort((a,b)=>RORD[b.r]-RORD[a.r]);
 grid.innerHTML=list.map(c=>`<div onclick="${S.cards[c.id]?'cardDetail':'craftCard'}('${c.id}')">${cardHTML(c,{locked:!S.cards[c.id],count:true})}</div>`).join('')
};
const TL_packViewRarity=VIEWS.packs;
VIEWS.packs=function(){
 TL_packViewRarity();if(!V)return;
 const boxes=V.querySelectorAll('.card-box'),pity=boxes[0],odds=boxes[boxes.length-1];
 if(pity){const bar=pity.querySelector('.xpbar i'),text=pity.querySelector('.mut');if(bar)bar.style.width=Math.min(100,(S.pity||0)/120*100)+'%';if(text)text.textContent=`Cada carta sin ICON llena la barra. Una ICON queda garantizada al llegar a 120 intentos sin obtenerla (${Math.max(0,120-(S.pity||0))} restantes).`}
 if(odds)odds.textContent=`Probabilidad por carta: Normal ${(PACKS.normal.o.I*100).toFixed(2)} % · Premium ${(PACKS.premium.o.I*100).toFixed(2)} % · Especialidad ${(PACKS.themed.o.I*100).toFixed(2)} % · Mutágeno ${(PACKS.mutation.o.I*100).toFixed(2)} %. No aumenta con la liga; las cartas repetidas no modifican el sorteo.`
};

