const TL_MUTATION_TYPES={
 overclock:{n:'Overclock',e:'⏩',d:'Un acierto rápido añade daño; en otros modos suma puntos.'},
 salvage:{n:'Recuperación',e:'♻️',d:'Cada tercera respuesta correcta da monedas extra.'},
 deadline:{n:'Ventana amplia',e:'⌛',d:'+4 s en preguntas con temporizador.'},
 scholar:{n:'Maestría',e:'🎓',d:'Aciertos difíciles dan XP adicional al mazo.'},
 ward:{n:'Pararrayos',e:'🔰',d:'La primera respuesta correcta del combate concede 1 escudo.'},
 pressure:{n:'Presión',e:'🎯',d:'+5 % de daño por nivel contra élites.'},
 fortune:{n:'Botín',e:'🍀',d:'El primer acierto de la run concede +2 gemas.'},
 static:{n:'Estática',e:'📡',d:'El primer fallo del combate se amortigua con 3 PV menos.'},
 relay:{n:'Repetidor',e:'🔁',d:'Cada dos aciertos seguidos devuelve 1 ⚡ al combate táctico.'},
 polarity:{n:'Polaridad',e:'🧲',d:'Potencia SEÑ y AB; mejora daño al coincidir asignatura y compi.'},
 economy:{n:'Economía',e:'🪙',d:'Las respuestas correctas generan monedas extra; los fallos reducen la recompensa.'}
};
Object.assign(MUTATIONS,TL_MUTATION_TYPES,{
 harmonic:{n:'Híbrida · Armónico',e:'🌈',d:'Resonante + Bastión: +1 escudo inicial y +10 % daño de afinidad.'},
 mint:{n:'Híbrida · Señal rentable',e:'💠',d:'Simbionte + Recuperación: duplica el primer premio de monedas de la run.'},
 singularity:{n:'Suprema · Singularidad',e:'🌠',d:'Overclock + Maestría: acierto rápido difícil potencia daño y XP.'}
});
const TL_HYBRIDS=[
 {id:'harmonic',needs:['resonance','bulwark'],name:'Armónico'},
 {id:'mint',needs:['symbiote','salvage'],name:'Señal rentable'},
 {id:'singularity',needs:['overclock','scholar'],name:'Singularidad'}
];
const TL_HYBRID_IDS=new Set(TL_HYBRIDS.map(x=>x.id));
function tlMutationDeck(){return (S.deck||[]).map(id=>({id,c:CARD[id],o:S.cards[id]})).filter(x=>x.c&&x.o&&x.o.mut&&MUTATIONS[x.o.mut])}
function tlHasMutation(id){return tlMutationDeck().some(x=>x.o.mut===id)}
function tlMutLevel(x){return Math.max(1,Math.min(3,Number(x&&x.o&&x.o.ml)||1))}
const TL_statMutation=stat;
stat=function(c,i){
 let value=TL_statMutation(c,i);const own=c&&S.cards&&S.cards[c.id];if(!own||!own.mut)return value;
 const lv=tlMutLevel({o:own});
 if(own.mut==='polarity'&&(i===0||i===2))value+=2*lv;
 if(own.mut==='overclock'&&i===1)value+=2*lv;
 if((own.mut==='economy'||own.mut==='salvage')&&i===3)value+=2*lv;
 if(own.mut==='pressure'&&i===0)value+=lv;
 return Math.min(99,value)
};
function tlActiveHybrid(){return TL_HYBRIDS.find(h=>h.id===S.activeHybrid&&h.needs.every(tlHasMutation))}
function tlSetHybrid(id){
 const h=TL_HYBRIDS.find(x=>x.id===id);
 if(!h||!h.needs.every(tlHasMutation)){toast('Equipa las dos mutaciones compatibles en tu mazo.');return}
 S.activeHybrid=id;save();sfx('gold');toast(`🧬 Híbrida activa: ${h.name}`);render()
}
const TL_cardDetailProgress=cardDetail;
cardDetail=function(id){
 TL_cardDetailProgress(id);
 const o=S.cards[id],box=$('#modal .mbox');
 if(box&&!o?.mut)box.querySelectorAll('button[onclick^="mutateCard"]').forEach(btn=>{const action=btn.getAttribute('onclick')||'';if(Array.from(TL_HYBRID_IDS).some(x=>action.includes(`'${x}'`)))btn.remove()});
 if(!o||!o.mut||!MUTATIONS[o.mut]||!box)return;
 const lv=tlMutLevel({o}),cost=lv*100,need=lv===1?1:2;
 box.insertAdjacentHTML('beforeend',`<div class="card-box tl-mutation-panel" style="margin-top:10px"><b>🧬 ${esc(MUTATIONS[o.mut].n)} · Nivel ${lv}/3</b><div class="mut">${esc(MUTATIONS[o.mut].d)} · bonificación de nivel ${lv}</div>${lv<3?`<button class="btn sec" style="margin-top:8px" onclick="tlUpgradeMutation('${id}')" ${S.coins>=cost&&(S.mutagen||0)>=need?'':'disabled'}>Evolucionar · ${cost} 🪙 + ${need} catalizador${need>1?'es':''}</button>`:'<div class="mut">Evolución máxima alcanzada.</div>'}</div>`);
};
const TL_mutateBase=mutateCard;
mutateCard=function(id,type){
 if(TL_HYBRID_IDS.has(type)){toast('Las mutaciones híbridas se activan al combinar sus dos mutaciones compatibles.');return}
 TL_mutateBase(id,type)
};
function tlUpgradeMutation(id){
 const o=S.cards[id];if(!o||!o.mut||!MUTATIONS[o.mut])return;
 const lv=tlMutLevel({o}),need=lv===1?1:2,cost=lv*100;
 if(lv>=3||S.coins<cost||(S.mutagen||0)<need){toast('Faltan monedas o catalizadores para evolucionar.');return}
 S.coins-=cost;S.mutagen-=need;o.ml=lv+1;save();sfx('lvl');floatTxt(`🧬 ${MUTATIONS[o.mut].n} · nivel ${o.ml}`,'#c4b5fd');cardDetail(id);renderTop()
}
let TL_ARCADE_AUDIO=null;
function tlArcadeTone(combo){
 const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio){sfx('gold');return}
 const ctx=TL_ARCADE_AUDIO||(TL_ARCADE_AUDIO=new Audio());if(ctx.state==='suspended')ctx.resume();
 const osc=ctx.createOscillator(),gain=ctx.createGain(),now=ctx.currentTime,base=260+combo*48;
 osc.type='triangle';osc.frequency.setValueAtTime(base,now);osc.frequency.exponentialRampToValueAtTime(base*1.55,now+.16);
 gain.gain.setValueAtTime(.0001,now);gain.gain.exponentialRampToValueAtTime(.11,now+.025);gain.gain.exponentialRampToValueAtTime(.0001,now+.29);
 osc.connect(gain);gain.connect(ctx.destination);osc.start(now);osc.stop(now+.3)
}
function tlMutationsPanel(){
 const owned=tlMutationDeck(),active=tlActiveHybrid();
 return `<div class="card-box tl-mutation-panel"><div class="rowb"><b>🧬 Mutaciones activas</b><span class="mut">${owned.length} en el mazo</span></div><div class="tl-mut-active">${owned.length?owned.map(x=>`<span class="tl-mut-pill" data-mut="${x.o.mut}">${MUTATIONS[x.o.mut].e} ${esc(MUTATIONS[x.o.mut].n)} Nv ${tlMutLevel(x)} · ${esc(x.c.n)}</span>`).join(''):'<span class="mut">Añade cartas mutadas a tu mazo desde el Álbum.</span>'}</div><h4 style="margin:12px 0 4px">Fusiones compatibles</h4>${TL_HYBRIDS.map(h=>`<div class="mrow"><span>${MUTATIONS[h.id].e} <b>${h.name}</b><small>Requiere ${h.needs.map(x=>MUTATIONS[x].n).join(' + ')}</small></span><button class="btn sm ${active&&active.id===h.id?'gold':'sec'}" onclick="tlSetHybrid('${h.id}')" ${h.needs.every(tlHasMutation)?'':'disabled'}>${active&&active.id===h.id?'Activa':'Activar'}</button></div>`).join('')}</div>`
}
const TL_labMutationView=VIEWS.lab;
VIEWS.lab=function(){TL_labMutationView();if(V)V.insertAdjacentHTML('beforeend',tlMutationsPanel())};
const TL_moreBestiary=VIEWS.more;
VIEWS.more=function(){TL_moreBestiary();if(V)V.insertAdjacentHTML('beforeend',`<button class="menu" onclick="go('bestiary')"><span>📚</span><div><b>Bestiario</b><small>${Object.keys(S.codex||{}).length}/${TL_ENEMIES.length+TL_BOSSES.length} rivales descubiertos</small></div><i>›</i></button>`)};

function tlMarkEnemy(e){
 if(!e||!e.tlId)return;
 S.codex=S.codex||{};S.codex[e.tlId]=S.codex[e.tlId]||{seen:today(),wins:0};
}
const TL_genEnemyRoster=genEnemy;
genEnemy=function(kind){
 const E=TL_genEnemyRoster(kind),r=S.run;
 if(!r)return E;
 let a=r.asig;
 if(!a||a==='ALL')a=kind==='boss'?(ASIG[weekAsig()]?weekAsig():ASIGS[(r.act-1)%ASIGS.length].id):ASIGS[(r.act+Math.max(0,r.floor-1))%ASIGS.length].id;
 let pick;
 if(kind==='boss'){
  const secret=Math.random()<.008&&!S.codex?.boss_secret_bug;
  pick=secret?TL_BOSSES[8]:TL_BOSSES.find(x=>x.a===a)||TL_BOSSES[(r.act-1)%7]
 }else{
  const rare=Math.random()<.035;
  if(rare)pick=TL_BOSSES[Math.random()<.5?7:8];
  else{
   const pool=TL_ENEMIES.filter(x=>x.a===a),recent=(S.enemyRecent||[]).slice(-2),fresh=pool.filter(x=>!recent.includes(x.id));
   pick=rnd(fresh.length?fresh:pool)
  }
 }
 if(!pick)return E;
 if(!S.enemyRecent)S.enemyRecent=[];
 if(!pick.rare){S.enemyRecent.push(pick.id);S.enemyRecent=S.enemyRecent.slice(-4)}
 Object.assign(E,{n:pick.n,e:pick.e,tlId:pick.id,tlAsig:pick.a,tlType:pick.type,tlLine:pick.line,tlRare:!!pick.rare});
 if(pick.type==='Tanque'){E.maxhp=E.hp=Math.round(E.hp*1.3);E.atk=Math.max(1,Math.round(E.atk*.9));E.tlArmor=.22}
 if(pick.type==='Velocista'){E.maxhp=E.hp=Math.round(E.hp*.8);E.atk=Math.round(E.atk*1.1);if(!E.traits.includes('rapido'))E.traits.push('rapido')}
 if(pick.type==='Vampiro'&&!E.traits.includes('vampiro'))E.traits.push('vampiro');
 if(pick.type==='Saboteador'&&!E.traits.includes('furia'))E.traits.push('furia');
 if(pick.type==='Especialista')E.tlSpecialist=true;
 if(pick.type==='Raro'){E.hp=E.maxhp=Math.round(E.maxhp*.6);E.atk=Math.max(1,Math.round(E.atk*.7))}
 if(kind==='elite')E.channel=Math.random()<.5?'echo':'narrow';
 return E
};
const TL_runFightBestiary=runFight;
runFight=function(kind){
 const E=S.run&&S.run.enemy,fresh=!!(E&&E.tlId&&!(S.codex&&S.codex[E.tlId]));
 TL_runFightBestiary(kind);
 const actual=S.run&&S.run.enemy;if(actual)tlMarkEnemy(actual);
 if(fresh&&E){toast(`📚 ¡Nuevo enemigo descubierto! ${E.e} ${E.n}`);const view=$('#view');if(view)view.classList.add('tl-new-enemy')}
 save()
};
const TL_runBarRoster=runBar;
runBar=function(){
 const html=TL_runBarRoster(),E=S.run&&S.run.enemy;if(!E||!E.tlId)return html;
 const channel=E.channel==='echo'?'📡 Canal con Eco · primera técnica +1 ⚡ y se repite':E.channel==='narrow'?'📶 Ancho de Banda Estrecho · mano máx. 2 · respuestas rápidas hacen crítico':'';
 const line=`<div class="tl-enemy-card${E.tlRare?' rare':''}${E.tlRare?' tl-enemy-intro':''}"><span class="tl-en-icon">${E.e}</span><div><b>${esc(E.tlLine||'')}</b><small>${esc(channel||`${E.tlType||'Rival'} · ${E.tlAsig&&ASIG[E.tlAsig]?ASIG[E.tlAsig].name:'expedición'}`)}</small></div></div>`;
 const muts=tlMutationDeck().map(x=>`<span class="tl-mut-pill" data-mut="${x.o.mut}">${MUTATIONS[x.o.mut].e} ${esc(MUTATIONS[x.o.mut].n)} Nv ${tlMutLevel(x)}</span>`).join('');
 return html.replace('<div class="hpb"><i id="ehp"',`${line}${muts?`<div class="tl-mut-active">${muts}</div>`:''}<div class="hpb"><i id="ehp"`)
};
const TL_tqCostRoster=tqCost;
tqCost=function(id){
 const cost=TL_tqCostRoster(id),T=M&&M.tq,E=S.run&&S.run.enemy;
 if(E&&E.channel==='echo'&&T&&!T.echoUsed&&!T.echoReplay&&cost>0)return cost+1;
 return cost
};
const TL_tqPlayRoster=tqPlay;
tqPlay=function(i){
 const T=M&&M.tq,E=S.run&&S.run.enemy,echo=!!(T&&E&&E.channel==='echo'&&!T.echoUsed),before=T&&T.plays;
 TL_tqPlayRoster(i);
 if(!echo||!T||T.plays===before||!M||M.over)return;
 T.echoUsed=true;
 const id=T.disc[T.disc.length-1];if(!id)return;
 const index=Math.min(i,T.hand.length);T.hand.splice(index,0,id);T.echoReplay=true;
 try{TL_tqPlayRoster(index)}finally{T.echoReplay=false}
 floatTxt('📡 ¡Eco de señal: técnica repetida!','#67e8f9',180)
};
const TL_runDamageRoster=runDmg;
runDmg=function(){
 let d=TL_runDamageRoster();const E=S.run&&S.run.enemy,q=M&&M.qs&&M.qs[M.i]&&M.qs[M.i].q;
 if(E&&E.tlArmor)d=Math.round(d*(1-E.tlArmor));
 if(E&&E.tlSpecialist&&q)d=Math.round(d*(q.asig===E.tlAsig?1.25:.9));
 if(E&&E.channel==='narrow'&&M&&M.tMax&&M.t/M.tMax>.66)d=Math.round(d*2);
 if(E&&E.boss&&E.tlPhaseAmp)d=Math.round(d*E.tlPhaseAmp);
 return Math.max(1,d)
};
const TL_runAnswerRoster=runOnAnswer;
runOnAnswer=function(good,saved){
 const r=S.run,E=r&&r.enemy;
 TL_runAnswerRoster(good,saved);
 if(!r||!E||!M||!M.runWin){
  if(r&&E&&!good&&!saved&&E.tlType==='Saboteador'){r.gems=Math.max(0,(r.gems||0)-2);floatTxt('🧤 −2 💎','#f87171')}
  return
 }
 save()
};
const TL_runAfterBestiary=runAfterMatch;
runAfterMatch=function(){
 const r=S.run,E=r&&r.enemy,won=!!(M&&M.runWin);
 TL_runAfterBestiary();
 if(!r||!E||!E.tlId||!won)return;
 S.codex=S.codex||{};const entry=S.codex[E.tlId]||(S.codex[E.tlId]={seen:today(),wins:0});entry.wins=(entry.wins||0)+1;
 if(!entry.reward){entry.reward=1;S.coins+=E.tlRare?150:35;S.dust+=E.tlRare?80:15;toast(`📚 ¡Entrada completada: ${E.n}! +${E.tlRare?150:35} 🪙`)}
 if(E.tlRare&&!entry.rareReward){entry.rareReward=1;r.gems=(r.gems||0)+35;if(S.run)addPot('botiquin');floatTxt('✨ Botín raro +35 💎','#fde047')}
 if(E.tlType==='Especialista'&&E.tlAsig===r.asig){r.gems=(r.gems||0)+4;floatTxt('🎯 Debilidad de asignatura +4 💎','#67e8f9')}
 save()
};
VIEWS.bestiary=function(){
 const all=TL_ENEMIES.concat(TL_BOSSES),codex=S.codex||{};
 V.innerHTML=`<button class="lnk" onclick="go('more')">← Más</button><h2>📚 Bestiario de Señal</h2><div class="mut">${Object.keys(codex).length}/${all.length} rivales descubiertos · primera victoria: recompensa única de colección.</div><div class="tl-best-grid" style="margin-top:10px">${all.map(e=>{const c=codex[e.id],a=e.a==='ALL'?'Todas':ASIG[e.a].name;return `<article class="tl-best-card ${c?'':'locked'}"><b>${e.e} ${c?esc(e.n):'Rival desconocido'}</b><small>${c?`${esc(a)} · ${esc(e.type)} · ${esc(e.line)} · victorias ${c.wins||0}`:'Descúbrelo en una expedición para revelar su entrada.'}</small></article>`}).join('')}</div>`
};
const TL_runNodeDaily=runNode;
runNode=function(k){
 TL_runNodeDaily(k);const r=S.run,E=r&&r.enemy;
 if(E&&r.dailyMod==='overload'&& !E.dailyOverloadApplied){E.atk++;E.dailyOverloadApplied=true;save()}
};

/* Evolución de mutaciones y resonancia en todos los modos */
const TL_runTimeMutation=runTime;
runTime=function(t){return TL_runTimeMutation(t)+(tlHasMutation('deadline')?4:0)};
const TL_runFightMutation=runFight;
runFight=function(kind){
 TL_runFightMutation(kind);
 if(!M||M.mode!=='run')return;
 const h=tlActiveHybrid();
 if(h&&h.id==='harmonic'){M.shields=(M.shields||0)+1;M.mutationHybrid='harmonic';toast('🌈 Armónico: +1 escudo inicial')}
};
const TL_runDamageMutation=runDmg;
runDmg=function(){
 let d=TL_runDamageMutation(),E=S.run&&S.run.enemy,q=M&&M.qs&&M.qs[M.i]&&M.qs[M.i].q,deck=tlMutationDeck();
 const levels=id=>deck.filter(x=>x.o.mut===id).reduce((n,x)=>n+tlMutLevel(x),0);
 const resonance=deck.filter(x=>x.o.mut==='resonance'&&q&&(x.c.a==='ALL'||x.c.a===q.asig)).reduce((n,x)=>n+tlMutLevel(x),0);
 if(resonance>1)d=Math.round(d*(1+.04*(resonance-1)));
 if(E&&E.elite&&levels('pressure'))d=Math.round(d*(1+.05*levels('pressure')));
 if(E&&E.tlAsig&&q&&q.asig===E.tlAsig&&levels('polarity'))d=Math.round(d*(1+.05*levels('polarity')));
 const petStateNow=typeof petState==='function'?petState():null,petNow=petStateNow&&typeof PET!=='undefined'?PET[petStateNow.act]:null;
 if(q&&petNow&&petNow.a===q.asig&&levels('polarity'))d=Math.round(d*(1+.05*levels('polarity')));
 if(E&&M&&M.tMax&&M.t/M.tMax>.66&&levels('overclock'))d=Math.round(d*(1+.04*levels('overclock')));
 const h=tlActiveHybrid();if(h&&h.id==='harmonic'&&q&&E&&q.asig===E.tlAsig)d=Math.round(d*1.1);
 if(h&&h.id==='singularity'&&q&&q.dif>=3&&M.t/M.tMax>.66)d=Math.round(d*1.15);
 return Math.max(1,d)
};
const TL_answerMutation=answer;
answer=function(k){
 const before=M&&M.res?M.res.length:0,combo=M&&M.combo;
 TL_answerMutation(k);
 if(!M||!M.res||M.res.length<=before)return;
 const result=M.res[M.res.length-1],q=M.qs[M.i]&&M.qs[M.i].q,deck=tlMutationDeck();
 if(result.ok){
  if(deck.some(x=>x.o.mut==='salvage')&&(M.correct%3===0)){M.coinsAcc+=6;if(S.run)S.run.gems=(S.run.gems||0)+2;floatTxt('♻️ +6 🪙','#fde047')}
  if(deck.some(x=>x.o.mut==='economy')){M.coinsAcc+=3;if(S.run)S.run.gems=(S.run.gems||0)+1}
  if(deck.some(x=>x.o.mut==='scholar')&&q&&q.dif>=3)giveDeckXP(8);
  if(deck.some(x=>x.o.mut==='overclock')&&result.t<3){if(M.mode==='run')M.shields=(M.shields||0)+1;else M.points+=12}
  if(deck.some(x=>x.o.mut==='ward')&&M.correct===1&&M.mode==='run'){M.shields=(M.shields||0)+1;floatTxt('🔰 Pararrayos: +1 escudo','#7dd3fc')}
  if(deck.some(x=>x.o.mut==='relay')&&M.combo%2===0&&M.tq){M.tq.en=Math.min(TQ_MAX,M.tq.en+1);tqRefresh()}
  if(deck.some(x=>x.o.mut==='fortune')&&M.mode==='run'&&M.combo===1)S.run.gems=(S.run.gems||0)+2;
  if(q&&q.asig===weekAsig()&&deck.some(x=>x.o.mut==='polarity'))M.points+=10;
  const h=tlActiveHybrid();if(h&&h.id==='mint'&&M.correct===1&&S.run)S.run.gems+=5
 }
 const milestones={3:'SEÑAL ESTABLE',5:'SOBRECARGA',8:'OVERDRIVE',10:'MODO LEYENDA'};
 const m=milestones[M.combo];
 if(result.ok&&m){
  const view=$('#view');if(view)view.classList.add('tl-od-view');
  const fb=$('#fb'),target=fb&&fb.querySelector('.verdict');
  if(target)target.insertAdjacentHTML('afterend',`<div class="tl-overdrive ${M.combo>=10?'tl-od-10':''}">⚡ ${m} · racha ${M.combo} · x${nextMult().toFixed(1)}</div>`);
  floatTxt(`${M.combo>=10?'🌠':'⚡'} ${m} · ${M.combo}`,'#facc15');
  tlArcadeTone(M.combo);
  if(M.combo>=8)vib([35,25,45]);
  if((S.bestCombo||0)-M.combo===1)toast('🔥 ¡A 1 acierto de récord!')
  setTimeout(()=>{if(view)view.classList.remove('tl-od-view')},1100)
 }else if(!result.ok){const view=$('#view');if(view)view.classList.remove('tl-od-view')}
 if(!result.ok&&deck.some(x=>x.o.mut==='static')&&!M.staticUsed){M.staticUsed=true;if(S.run)S.run.hp=Math.min(S.run.maxhp,S.run.hp+3);floatTxt('📡 Estática absorbe 3 PV','#7dd3fc')}
 if(!result.ok&&deck.some(x=>x.o.mut==='economy'))M.coinsAcc=Math.max(0,M.coinsAcc-2)
 if(result.ok){V&&V.querySelectorAll('.tl-mut-pill').forEach(x=>{x.classList.add('tl-mut-fired');setTimeout(()=>x.classList.remove('tl-mut-fired'),720)})}
 if(combo!==M.combo&&M.mode==='run'&&M.tq)tqRefresh()
};

/* Cofres y ruleta: actualización visible de rareza y proporciones reales */
const TL_openChestReroll=openChest;
openChest=function(i){
 const c=S.chests[i];if(!c)return;
 const next={w:'s',s:'g',g:'l'}[c.t];
 if(next&&!c.tlAscended&&Math.random()<.045){
  const button=document.querySelectorAll('.chest')[i];if(button)button.classList.add('tl-chest-reroll');
  toast(`✨ ¡El cofre chisporrotea! ${CHESTS[c.t].e} → ${CHESTS[next].e}`);
  setTimeout(()=>{if(S.chests[i]!==c)return;c.tlAscended=1;c.t=next;save();TL_openChestReroll(i)},650);return
 }
 TL_openChestReroll(i)
};
function tlWheelAngles(){
 const sum=WHEEL.reduce((n,x)=>n+x.w,0);let cur=0;
 return WHEEL.map(x=>{const start=cur/sum*360;cur+=x.w;return{start,end:cur/sum*360,mid:(start+cur/sum*360)/2}})
}
spinWheel=function(){
 if(S.spinDay===today()){toast('Ya has girado hoy. ¡Vuelve mañana! 🎡');return}
 const angles=tlWheelAngles(),stops=angles.map((x,i)=>`${WHEEL[i].c} ${x.start}deg ${x.end}deg`).join(',');
 modal(`<h3 style="text-align:center">🎡 Ruleta diaria</h3><div class="wheel-wrap"><div class="pin">🔻</div><div class="wheel" id="whl" style="background:conic-gradient(${stops})">${WHEEL.map((s,i)=>{const a=angles[i].mid*Math.PI/180;return `<span class="wl" style="left:${50+33*Math.sin(a)}%;top:${50-33*Math.cos(a)}%;transform:translate(-50%,-50%) rotate(${angles[i].mid}deg)">${s.t}</span>`}).join('')}</div></div><button class="btn gold big" id="spin">¡GIRAR!</button>`,true);
 $('#spin').onclick=()=>{$('#spin').disabled=true;S.spinDay=today();save();let x=Math.random()*WHEEL.reduce((a,s)=>a+s.w,0),k=0;for(;k<WHEEL.length-1;k++){x-=WHEEL[k].w;if(x<0)break}
  const mid=angles[k].mid,extra=360*6+360-mid;$('#whl').style.transform=`rotate(${extra}deg)`;
  for(let i=0;i<22;i++)setTimeout(()=>sfx('flip'),i*i*8);
  setTimeout(()=>{let chosen=k,upgraded=false;
   if(Math.random()<.025){const up={2:5};if(up[chosen]!=null){chosen=up[chosen];upgraded=true}}
   const w=WHEEL[chosen];w.f();save();renderTop();closeModal();
   celebrate(upgraded?'✨':'🎁',upgraded?'¡PREMIO ASCENDIDO!':'¡Te ha tocado!',`${w.t}${/Sobre|Premium|ICON/.test(w.t)?'<br>Lo tienes en Sobres':''}`);
   if(route==='home')render()
  },4400)}
};

