/* 3) Apertura de sobres: la animación cambia según la mejor carta del sobre */
const V9_TIER={B:{k:'b',c:'#d08a4a',n:'BRONCE',t:500},P:{k:'p',c:'#cbd5e1',n:'PLATA',t:700},O:{k:'o',c:'#fbbf24',n:'ORO',t:1500},M:{k:'m',c:'#c084fc',n:'MÍTICA',t:2300},C:{k:'c',c:'#22d3ee',n:'CÓSMICA',t:2500},T:{k:'t',c:'#fb7185',n:'PROTOTIPO',t:2700},I:{k:'i',c:'#ff6ad5',n:'★ ICON',t:3600}};
const V9_showOpeningBase=showOpening;
let V9_OPEN=null;
function v9Best(info){return info.reduce((b,x)=>(RORD[x.c.r]||0)>(RORD[b.c.r]||0)?x:b,info[0])}
showOpening=function(info,pk){
 if(!info||!info.length)return V9_showOpeningBase(info,pk);
 const best=v9Best(info),T=V9_TIER[best.c.r]||V9_TIER.B,shiny=info.some(x=>x.sh),reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;
 const packCls=(pk&&pk.cls)||'pk-n';
 V9_OPEN={info,pk,best,T,shiny,timers:[],done:false};
 modal(`<div class="po po-${T.k}${shiny?' po-shiny':''}" style="--tc:${T.c}">
  <div class="po-bg"></div><div class="po-rays"></div>
  <div class="po-pack ${packCls}" id="po-pack" onclick="v9Tear()"><div class="pk-art"></div><div class="po-pack-shine"></div><div class="po-pack-label">${esc((pk&&pk.n)||'Sobre')}</div><div class="po-seal">📡</div></div>
  <div class="po-hint" id="po-hint">Toca el sobre para abrirlo</div>
  <div class="po-walk" id="po-walk"></div>
  <button class="po-skip" onclick="v9OpenFinish()">Saltar ⏭</button></div>`,true);
 const pack=$('#po-pack');
 // pista: cuanto mejor la carta, más tiembla y brilla el sobre antes de abrirlo
 if(pack)pack.style.setProperty('--shake',T.k==='b'||T.k==='p'?'0':T.k==='o'?'1':'2');
 if(reduce){setTimeout(()=>v9OpenFinish(),200)}
};
function v9Tear(){const O=V9_OPEN;if(!O||O.done||O.torn)return;O.torn=true;const T=O.T,pack=$('#po-pack'),hint=$('#po-hint'),walk=$('#po-walk'),root=$('#modal .po');if(!pack||!root)return v9OpenFinish();
 sfx('flip');vib(30);pack.classList.add('torn');if(hint)hint.textContent='';
 const at=(ms,fn)=>O.timers.push(setTimeout(()=>{if(!O.done)fn()},ms));
 const c=O.best.c,A=c.a&&ASIG[c.a]?ASIG[c.a]:null;
 if(T.k==='b'||T.k==='p'){root.classList.add('go');at(T.t,()=>v9OpenFinish());return}
 if(T.k==='o'){root.classList.add('go','beams');at(350,()=>{sfx('gold');confetti(50,['#fde68a','#fbbf24','#fff'])});at(500,()=>walk.innerHTML=`<div class="po-tag">✨ ¡${T.n}!</div>`);at(T.t,()=>v9OpenFinish());return}
 // Mítica, Cósmica, Prototipo e ICON: salida en pasos con pistas sobre la carta
 root.classList.add('go','beams','walkout');
 const step=(html,ms)=>at(ms,()=>{walk.innerHTML=`<div class="po-clue">${html}</div>`;sfx('flip');vib(20)});
 if(T.k==='i'){
  at(200,()=>{root.classList.add('dark')});
  step(`<span class="po-big">${A?A.icon:'🌍'}</span><small>${A?esc(A.name):'Todas las asignaturas'}</small>`,600);
  step(`<span class="po-big">${esc(c.e||'★')}</span><small>Rareza máxima</small>`,1400);
  step(`<span class="po-rare">★ ICON</span>`,2200);
  at(2700,()=>{root.classList.remove('dark');root.classList.add('boom');flash();sfx('icon');vib([80,50,80,50,200]);confetti(140,['#ff6ad5','#ffe66d','#7cffcb','#94d0ff','#fff']);walk.innerHTML=`<div class="po-reveal">${cardHTML(c)}</div>`});
  at(T.t+400,()=>v9OpenFinish());return}
 step(`<span class="po-big">${A?A.icon:'🌍'}</span><small>${A?esc(A.name):'Todas las asignaturas'}</small>`,450);
 step(`<span class="po-rare">${T.n}</span>`,1250);
 at(1700,()=>{root.classList.add('boom');flash();sfx('gold');vib([60,40,120]);confetti(90,[T.c,'#fff','#fde68a']);walk.innerHTML=`<div class="po-reveal">${cardHTML(c)}</div>`});
 at(T.t+300,()=>v9OpenFinish())}
