(()=>{const s=document.createElement('style');s.textContent=".po{position:relative;min-height:440px;display:flex;flex-direction:column;align-items:center;justify-content:center;overflow:hidden;border-radius:16px;margin:-6px;padding:18px 8px 54px;isolation:isolate}\n.po-bg{position:absolute;inset:0;z-index:-2;background:radial-gradient(circle at 50% 45%,color-mix(in srgb,var(--tc) 22%,#0b1020) 0%,#070a14 70%);transition:filter .4s,background .4s}\n.po-rays{position:absolute;left:50%;top:45%;width:900px;height:900px;margin:-450px 0 0 -450px;z-index:-1;opacity:0;background:repeating-conic-gradient(from 0deg,color-mix(in srgb,var(--tc) 55%,transparent) 0deg 6deg,transparent 6deg 18deg);transition:opacity .5s;animation:poSpin 9s linear infinite}\n@keyframes poSpin{to{transform:rotate(360deg)}}\n.po-pack{position:relative;width:150px;height:210px;border-radius:14px;cursor:pointer;box-shadow:0 0 0 2px #ffffff22,0 18px 40px #0009,0 0 calc(10px + var(--shake,0)*14px) color-mix(in srgb,var(--tc) calc(15% + var(--shake,0)*25%),transparent);animation:poIdle calc(1.6s - var(--shake,0)*.45s) ease-in-out infinite;transform-origin:50% 90%}\n.po-pack .pk-art{position:absolute;inset:0;width:100%!important;height:100%!important;margin:0!important;border-radius:14px;transform:none!important}\n.po-pack-shine{position:absolute;inset:0;border-radius:14px;background:linear-gradient(115deg,transparent 30%,#ffffff55 45%,transparent 60%);background-size:250% 100%;animation:poShine 2.4s linear infinite}\n@keyframes poShine{from{background-position:120% 0}to{background-position:-120% 0}}\n.po-pack-label{position:absolute;left:0;right:0;bottom:16px;text-align:center;font-weight:900;font-size:13px;letter-spacing:.5px;color:#fff;text-shadow:0 2px 6px #000}\n.po-seal{position:absolute;left:50%;top:42%;transform:translate(-50%,-50%);font-size:44px;filter:drop-shadow(0 4px 8px #0008)}\n@keyframes poIdle{0%,100%{transform:rotate(0) translateY(0)}25%{transform:rotate(calc(var(--shake,0)*-2.5deg)) translateY(-3px)}75%{transform:rotate(calc(var(--shake,0)*2.5deg)) translateY(-3px)}}\n.po-hint{margin-top:16px;font-size:13px;color:#cbd5e1;animation:poBlink 1.4s ease-in-out infinite}@keyframes poBlink{50%{opacity:.4}}\n.po-pack.torn{animation:poTear .55s ease-in forwards;pointer-events:none}\n@keyframes poTear{30%{transform:scale(1.08) rotate(-3deg)}100%{transform:scale(1.3) translateY(-40px);opacity:0;filter:brightness(3)}}\n.po.go .po-bg{filter:brightness(1.25)}\n.po.beams .po-rays{opacity:.55}\n.po.dark .po-bg{background:#000;filter:none}.po.dark .po-rays{opacity:0}\n.po.boom .po-rays{opacity:.9;animation-duration:3s}\n.po.boom{animation:poShake .45s}\n@keyframes poShake{20%{transform:translate(-5px,2px)}40%{transform:translate(5px,-2px)}60%{transform:translate(-3px,1px)}80%{transform:translate(2px,-1px)}}\n.po-walk{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;pointer-events:none}\n.po-tag{font-size:30px;font-weight:900;color:var(--tc);text-shadow:0 0 18px var(--tc);animation:poPop .5s cubic-bezier(.2,1.6,.4,1)}\n.po-clue{display:flex;flex-direction:column;align-items:center;gap:6px;animation:poPop .45s cubic-bezier(.2,1.6,.4,1)}\n.po-clue small{color:#e2e8f0;font-size:14px;font-weight:700;letter-spacing:.4px}\n.po-big{font-size:72px;line-height:1;filter:drop-shadow(0 0 18px var(--tc))}\n.po-rare{font-size:36px;font-weight:900;letter-spacing:2px;color:#fff;text-shadow:0 0 10px var(--tc),0 0 30px var(--tc)}\n.po-reveal{width:170px;animation:poReveal .7s cubic-bezier(.2,1.4,.4,1)}.po-reveal .gcard{box-shadow:0 0 40px var(--tc)}\n@keyframes poPop{from{transform:scale(.3);opacity:0}to{transform:scale(1);opacity:1}}\n@keyframes poReveal{from{transform:scale(.2) rotateY(180deg);opacity:0}to{transform:scale(1) rotateY(0);opacity:1}}\n.po-shiny .po-pack::after{content:'\u2728';position:absolute;top:-10px;right:-8px;font-size:26px;animation:poBlink 1s infinite}\n.po-skip{position:absolute;right:10px;bottom:10px;padding:6px 12px;border-radius:999px;border:1px solid #ffffff33;background:#0008;color:#e2e8f0;font-size:12px;font-weight:700}\n.po-t .po-bg{background:radial-gradient(circle at 50% 45%,#7f1d1d 0%,#070a14 70%)}\n.po-c .po-rays{background:repeating-conic-gradient(from 0deg,#22d3ee88 0 5deg,transparent 5deg 12deg,#a78bfa66 12deg 17deg,transparent 17deg 24deg)}\n.po-i.beams .po-rays{background:repeating-conic-gradient(from 0deg,#ff6ad5aa 0 6deg,#ffe66d88 6deg 12deg,#7cffcb88 12deg 18deg,#94d0ff88 18deg 24deg)}\n@media(prefers-reduced-motion:reduce){.po-rays,.po-pack,.po-pack-shine,.po-hint{animation:none}}\n";document.head.appendChild(s)})();

